  ui_story_5045_50450101_41_dialog_content = "...하암, 어머? PlayerName 씨는 피고가 아닌데 왜 저기 서 있는 거죠?",
  ui_story_5045_50450101_42_dialog_content = "앗! 이런! 어쩌죠?! 큰일이네요!",
  ui_story_5045_50450101_43_dialog_content = "자느라 심판 첫 단계를 놓쳐버렸잖아요!\n절도 사건 피해자 진술은 벌써 끝났나요?!",
  ui_story_5045_50450101_44_dialog_content = "쉿!",
  ui_story_5045_50450101_45_dialog_content = "아, 크흠... 방금 전엔 피고가 도착했는지 확인하려던 것뿐이에요.",
  ui_story_5045_50450101_46_dialog_content = "피고는 잠시 자리로 돌아가세요.",
  ui_story_5045_50450101_47_dialog_content = "(이 상황... 아무래도 계속 장단을 맞춰 줘야 하는 건가?)",
  ui_story_5045_50450101_48_dialog_content = "먼저, 원고이자 이번 절도 사건의 피해자인 이리돈 님께\n사건 진술을 부탁드립니다.",
