  ui_story_5045_50450101_51_dialog_content = "소식을 받은 후, 사무실의 문을 잠그고 곧장 자리를 떠났죠.",
  ui_story_5045_50450101_52_dialog_content = "하지만 제가 4시에 사무실에 돌아와 보니 책상 위에 두었던\n거액의 나이티움이 날개라도 달린 듯 사라져 버렸던 거예요.",
