  ui_story_5045_50450101_54_dialog_content = "사무실의 문과 창문엔 그 어떤 훼손 흔적도 존재하지 않았어요.\n문의 자물쇠도 제가 나가기 전에 잠가 뒀던 그대로였죠.",
  ui_story_5045_50450101_55_dialog_content = "문고리엔 제가 방에 들어갈 때 남겼던 지문 이외엔\n아무런 흔적도 남아 있지 않았어요.",
  ui_story_5045_50450101_55X1_dialog_content = "(뭐가 어떻게 된 일인지는 도저히 모르겠지만,\n왠지 이리돈 씨가 지금 하는 이야기는 아주 중요해 보여.)",
