  ui_story_5045_50450101_57_dialog_content = "그렇다면 이리돈 님께선 왜 나이티움을 훔친 범인으로\nPlayerName 씨를 지목하신 건가요?",
  ui_story_5045_50450101_58_dialog_content = "사무실 안에서 제가 PlayerName 씨에게 보냈던\n초대장을 발견했기 때문이에요.",
