  ui_story_5045_50450101_66_dialog_content = "음, 그럼 다음 차례는... 증인 피트만 씨, 증인석으로 나와서 증언해 주세요!",
  ui_story_5045_50450101_67_dialog_content = "오늘 오후 2시, 전 업무와 관련된 질문을 몇 가지 드리러\n이리돈 님을 찾아뵈려 했습니다만...",
  ui_story_5045_50450101_68_dialog_content = "이리돈 님께서는 마침 그 시간에 회의를 하셔야 했기에,\n제게 조금 뒤에 다시 방문해 달라고 하셨습니다.",
