  ui_story_5045_50450101_88_dialog_content = "백야성에 위해를 가하려는 죄인은 감옥으로 보내 평생을 수감해야 해요!",
  ui_story_5045_50450101_89_dialog_content = "(그냥 농담이었는데... 다들 진짜 날 심판할 분위기네...)",
