  ui_story_5045_50450101_93_dialog_content = "잘 들었습니다. 즉, 피고는 중2병에 걸린 백수라고 이해하면 되겠네요.",
  ui_story_5045_50450101_94_dialog_content = "피고는 오늘 오후 2시에 어디 있었죠? 사실대로 대답하세요.",
  ui_story_5045_50450101_95_dialog_content = "전 계속 심판소에 있었어요.",
  ui_story_5045_50450101_96_dialog_content = "피고는 아이테르인데, 어떤 이유로 백야성 심판소에 방문한 거죠?",
