  ui_story_5045_50450101_96X2_dialog_content = "(여기 서 있으니까 머릿속이 새하얘져서 아무 생각도 안 나!)",
  ui_story_5045_50450101_96X3_dialog_content = "(다행히 아까 정보를 몇 가지 적어 뒀으니까, 심리를 진행하다 보면 뭔가 생각이 날지도 몰라...)",
  ui_story_5045_50450101_97_dialog_content = "만물은 백야 아래에. 얼렁뚱땅 얼버무리려 하지 마세요!",
  ui_story_5045_50450101_98_dialog_content = "제, 제가 말을 잘못 했네요...",
