  ui_story_5045_50450101_100_dialog_content = "전 이리돈 씨가 저한테 보낸 <color=#1875ad>초대장</color>을 받았어요.",
  ui_story_5045_50450101_101_dialog_content = "오늘 시간을 내서 심판소에 있는 사무실로 만나러 와 달라고 적혀 있었죠.",
  ui_story_5045_50450101_102_dialog_content = "절 데리고 심판소 구경도 시켜 준다고 했었어요.\n저한테 맡길 사건도 하나 있다고 했었고요.",
  ui_story_5045_50450101_103_dialog_content = "아무튼 2시에 도착했는데, 여기 사람들은 아무도 길을 안 가르쳐 주더라고요.",
  ui_story_5045_50450101_104_dialog_content = "덕분에 3시가 거의 다 돼서야 간신히 이리돈 씨의 사무실을 찾았는데,\n안에 들어가 보니까 이리돈 씨는 부재중이었어요.",
  ui_story_5045_50450101_105_dialog_content = "그래서 사무실에서 바로 나왔어요.",
  ui_story_5045_50450101_106_dialog_content = "그다음엔 누가 절 이 심판소로 데려오기 전까지 계속\n밖에 있는 계단에 앉아서 햇볕을 쬐고 있었어요.",
  ui_story_5045_50450101_107_dialog_content = "으음? 그러니까 이리돈 님의 사무실에 침입했단 사실을 인정한단 건가요?",
  ui_story_5045_50450101_108_dialog_content = "들어간 건 맞지만 「침입」한 건 아니에요.\n처음부터 문도 안 잠겨 있었다구요!",
  ui_story_5045_50450101_109_dialog_content = "그건 불가능해요.\n이리돈 님께선 문을 제대로 잠근 다음 외출하셨다고 말씀하셨는걸요.",
  ui_story_5045_50450101_110_dialog_content = "PlayerName 씨, 변명을 하려면 좀 그럴듯하게 해야죠.",
  ui_story_5045_50450101_111_dialog_content = "직업도 없으면서 돈이 필요하다는 이유로 당신에 대한\n이리돈 님의 신뢰를 이용할 줄이야...",
  ui_story_5045_50450101_112_dialog_content = "하지만 생각이 짧았네요...",
  ui_story_5045_50450101_113_dialog_content = "여긴 백야성 심판소예요. 죄를 지은 자는 단 한 명도 놓치지 않아요!",
  ui_story_5045_50450101_114_dialog_content = "따라서...",
