  ui_story_5045_50450201_3_dialog_content = "네? 유죄요? PlayerName 씨가요?",
  ui_story_5045_50450201_4_dialog_content = "가장 흥미진진한 부분에서 일어나다니, 요령도 좋군.",
  ui_story_5045_50450201_5_dialog_content = "안젤 양의 평소 실력은 오늘보다 훨씬 훌륭하리라고 믿습니다.\n오늘은 너무 긴장한 나머지 실력 발휘를 못 한 거겠죠.",
  ui_story_5045_50450201_6_dialog_content = "그러니까 서민은 심판관으로 안 맞는다고 말했잖아.\n서민에겐 너무 버거운 일이라고.",
  ui_story_5045_50450201_7_dialog_content = "이리돈 님, 혹시 저 이번에도 <color=#1875ad>모의 심판</color> 심사에서 탈락한 건가요...?",
  ui_story_5045_50450201_8_dialog_content = "뭐야? 이거 <color=#1875ad>모의 심판</color>이었어?!",
  ui_story_5045_50450201_9_dialog_content = "안젤, 재판은 아직 끝나지 않았어요. 당신은 아직 심판관입니다.",
  ui_story_5045_50450201_10_dialog_content = "잊지 마세요. 당신은 아직 「재판 종료」를 선포하지 않았어요.",
  ui_story_5045_50450201_11_dialog_content = "안젤 씨, 긴장하지 말아요.",
  ui_story_5045_50450201_12_dialog_content = "잠시 머리도 식힐 겸, 휴정하고 눈을 좀 붙이는 건 어때요?",
  ui_story_5045_50450201_13_dialog_content = "그보다는 모두의 진술에서 모순된 점은 없었는지,\n한번 생각을 차분히 정리해 보십시오.",
  ui_story_5045_50450201_14_option_content = "티나 말이 맞아.",
  ui_story_5045_50450201_15_dialog_content = "그래요? PlayerName 씨도 저와 같은 생각이신가요?",
  ui_story_5045_50450201_16_dialog_content = "응, 빨리 휴정하자!",
  ui_story_5045_50450201_17_dialog_content = "아깐 진짜 너무 놀라서 손발이 다 떨리더라니까.\n그러니까 나도 좀 쉬게 해 줘.",
  ui_story_5045_50450201_18_dialog_content = "조언해 주셔서 감사해요, 여러분.",
  ui_story_5045_50450201_19_option_content = "레인 씨 말이 맞는 것 같아.",
  ui_story_5045_50450201_20_dialog_content = "감사합니다, PlayerName 씨. 저와 같은 생각이시군요.",
  ui_story_5045_50450201_21_dialog_content = "맞아. 안젤, 생각을 차분히 정리해 봐!",
  ui_story_5045_50450201_22_dialog_content = "모의 심판이든 진짜 심판이든, 난 확실히 도둑이 아니니까!",
  ui_story_5045_50450201_23_dialog_content = "조언해 주셔서 감사해요, 여러분.",
  ui_story_5045_50450201_24_option_content = "그냥 그만하자.",
  ui_story_5045_50450201_25_dialog_content = "나도 참여시킬 거였으면 미리 말이라도 해 줬어야 하는 거 아니야?",
  ui_story_5045_50450201_26_dialog_content = "들어오라고 하더니 갑자기 「유죄」니 뭐니, 좀 너무하잖아.",
  ui_story_5045_50450201_27_dialog_content = "안젤, 아니면 이번 심사는 여기까지 하자.\n다음엔 나도 제대로 준비해서 더 잘 연기해 볼게!",
  ui_story_5045_50450201_28_dialog_content = "안 돼! 그럴 순 없어!",
  ui_story_5045_50450201_29_dialog_content = "(으음, 안젤이 이렇게 흥분하는 건 처음 보는 것 같은데...)",
  ui_story_5045_50450201_30_dialog_content = "(일단 상황을 지켜보는 편이 좋겠어...)",
  ui_story_5045_50450201_31_dialog_content = "크, 크흠... 이젠 좀 진정이 된 것 같아요.",
  ui_story_5045_50450201_32_dialog_content = "아까는 이번 심사도 또 떨어지는 게 아닌지 걱정돼서\n여러분 앞에서 추태를 보였네요.",
  ui_story_5045_50450201_33_dialog_content = "심판관에게는 사건의 진상이 심사 통과 여부보다 영원히 더 중요하답니다.",
  ui_story_5045_50450201_34_dialog_content = "비록 이건 심사에 불과하지만, 그래도 우린 자신의 신념을 포기하지 않고\n끝까지 관철해야 합니다.",
  ui_story_5045_50450201_35_dialog_content = "네!",
  ui_story_5045_50450201_36_dialog_content = "<color=#737378>탕!</color>",
  ui_story_5045_50450201_37_dialog_content = "그럼 지금부터 <color=#1875ad>심판소 변론</color> 절차를 시작하겠습니다!",
  ui_story_5045_50450201_38_dialog_content = "여러분께서는 서로에게 질의하거나 자신의 의견을 발표하고,\n자신의 주장에 대한 근거를 설명해 주세요.",
  ui_story_5045_50450201_39_dialog_content = "일단 전 도둑이 아닙니다!",
  ui_story_5045_50450201_40_dialog_content = "그렇지만 이 초대장은 당신이 분명히 제 사무실에 들어갔었다는\n사실을 증명해 주고 있어요.",
  ui_story_5045_50450201_41_dialog_content = "게다가 이 부분은 조금 전에 당신이 자기 입으로 직접 맞다고 인정까지 했죠.",
  ui_story_5045_50450201_42_dialog_content = "맞아요, 사무실 안에 들어가긴 했었죠. 근데 진짜 아무것도 안 가지고 나왔고,\n제가 갔을 땐 문도 안 잠겨 있었다니까요!",
  ui_story_5045_50450201_43_dialog_content = "전 확신해요. 전 문을 확실히 잠근 다음 사무실을 나섰어요.",
  ui_story_5045_50450201_44_dialog_content = "아마 당신이 감응 능력으로 장치를 열었다가 떠날 때 다시 잠근 거겠죠.",
  ui_story_5045_50450201_45_dialog_content = "감응 능력으로 그런 건 못 해요.",
  ui_story_5045_50450201_46_dialog_content = "우린 아이테르가 아니에요.\n따라서 당신이 그런 행동을 할 수 있는지 없는지는 알 수 없어요.",
  ui_story_5045_50450201_47_dialog_content = "이건 모함이에요!",
  ui_story_5045_50450201_48_dialog_content = "이의 있습니다! 심판관님, 피고는 지금 제게 인신 공격을 하고 있습니다.",
  ui_story_5045_50450201_49_dialog_content = "...이건 불공평해. 너흰 다들 한 패잖아!",
  ui_story_5045_50450201_50_dialog_content = "피고, 당신은 이 사건의 증거와 세부 사항에 대해\n질문 및 설명을 요구할 권리가 있습니다만...",
  ui_story_5045_50450201_51_dialog_content = "신성한 심판소에선 부디 언어 사용에 각별히 주의해 주세요.",
  ui_story_5045_50450201_52_dialog_content = "......",
  ui_story_5045_50450201_53_dialog_content = "그럼 변론하실 다른 분 안 계신가요?",
  ui_story_5045_50450201_54_dialog_content = "지금까지의 상황은 여전히 피고에게 불리합니다. 하실 말씀 없으신가요?",
  ui_story_5045_50450201_55_dialog_content = "(뭔가 이상해.)",
  ui_story_5045_50450201_56_dialog_content = "(내가 사무실에 들어간 건 맞아. 하지만 그 초대장 이외에도...)",
  ui_story_5045_50450201_57_dialog_content = "(다른 <color=#1875ad>흔적들</color>이 남아 있었어야 해!)",
  ui_story_5045_50450201_58_dialog_content = "그 부분에 무슨 문제라도 있나요?",
  ui_story_5045_50450201_59_dialog_content = "어? 문제가 없나?",
  ui_story_5045_50450201_60_dialog_content = "(다시 잘 생각해 보자! 초대장 말고 사무실에 남아 있어야 하는 흔적은...)",
  ui_story_5045_50450201_61_dialog_content = "이리돈 씨는 손잡이에 자기 지문밖에 없었다고 했지만, 그건 이상해요.",
  ui_story_5045_50450201_62_dialog_content = "왜냐하면 전 그 문고리를 잡아서 문을 열고 사무실 안으로 들어갔으니까요.",
  ui_story_5045_50450201_63_dialog_content = "그러니까 그 문고리엔 제 지문도 남아 있었어야 해요!",
  ui_story_5045_50450201_64_dialog_content = "정말 그렇군요!",
  ui_story_5045_50450201_65_dialog_content = "이건 진범이 사건의 진상을 감추기 위해 자기 지문을 지운 게 분명해요.",
  ui_story_5045_50450201_66_dialog_content = "그렇지만 제 지문까지 지워질 줄은 예상하지 못했겠죠!",
  ui_story_5045_50450201_67_dialog_content = "일리가 있네요...",
  ui_story_5045_50450201_68_dialog_content = "당신이 자기 손으로 직접 지웠을지도 모르는 일 아닌가요?",
  ui_story_5045_50450201_69_dialog_content = "(윽, 역시 진짜 도둑을 찾아내야만 혐의에서 벗어날 수 있겠어.)",
  ui_story_5045_50450201_70_dialog_content = "(잠깐만!)",
  ui_story_5045_50450201_71_dialog_content = "(난 도둑이 아니야. 그런데 <color=#1875ad>그 증언</color>은 명확하게 날 범인으로 몰고 있었어!)",
  ui_story_5045_50450201_72_dialog_content = "그 부분에 무슨 문제라도 있나요?",
  ui_story_5045_50450201_73_dialog_content = "앗, 이 얘길 하려던 게 아닌데 실수했네...",
  ui_story_5045_50450201_74_dialog_content = "(다시 차분히 잘 생각해 보자...)",
  ui_story_5045_50450201_75_dialog_content = "피트만 씨, 제가 「수상하게 행동하는 모습」을 봤다고 했었는데, 그건 언제였죠?",
  ui_story_5045_50450201_76_dialog_content = "아마 3시경이었을 겁니다.",
  ui_story_5045_50450201_77_dialog_content = "조금 더 구체적으론요? 3시 몇 분이었죠?",
  ui_story_5045_50450201_78_dialog_content = "아마... 3시 10분이었을 겁니다.",
  ui_story_5045_50450201_79_dialog_content = "하지만 그건 좀 이상하군요. 전 3시가 되기 전에 사무실을 떠났거든요.\n그런데 어떻게 제 모습을 봤다는 거죠?",
  ui_story_5045_50450201_80_dialog_content = "참고로 전 심판소에서 밖으로 나왔을 때 3시를 알리는 종소리를 들었어요.",
  ui_story_5045_50450201_81_dialog_content = "그때 마침 밖에서 순찰 중이던 경비병이 있었으니까,\n제 증언이 사실이란 건 그 사람이 증명해 줄 수 있을 거예요.",
  ui_story_5045_50450201_82_dialog_content = "그, 그렇습니까...",
  ui_story_5045_50450201_83_dialog_content = "저도 확실한 건 아닙니다만, 어쩌면 그때 제가 목격한 사람이\n진범일지도 모르겠군요.",
  ui_story_5045_50450201_84_dialog_content = "그럼 피트만 씨는 진짜 도둑이 따로 있다는 사실을 인정하는 거네요?",
  ui_story_5045_50450201_85_dialog_content = "그런 셈입니다.",
  ui_story_5045_50450201_86_dialog_content = "심판관님, 피트만 씨는 자신이 목격한 수상한 인물이\n저인지 아닌지 확신할 수 없는 모양이네요.",
  ui_story_5045_50450201_87_dialog_content = "따라서 전 피트만 씨의 증언에 효력이 없다고 생각합니다!",
  ui_story_5045_50450201_88_dialog_content = "확실히 그렇네요...",
  ui_story_5045_50450201_89_dialog_content = "하지만 그렇다고 해서 당신의 혐의가 완전히 사라진 건 아니에요.",
  ui_story_5045_50450201_90_dialog_content = "그럼 발상을 전환해 보죠.\n제가 도둑이 아니라고 가정한다면, 이 사건엔 몇 가지 의문점이 존재해요.",
  ui_story_5045_50450201_91_dialog_content = "첫 번째, 도둑은 잠겨 있던 문을 어떻게 열었을까요?\n열쇠를 복사해서 가지고 있었던 걸까요?",
  ui_story_5045_50450201_92_dialog_content = "......",
  ui_story_5045_50450201_93_dialog_content = "두 번째, 도둑은 어째서 지문을 닦아야만 했을까요?",
  ui_story_5045_50450201_94_dialog_content = "설마 심판소 내부 사람이라서, 조사하면 바로 정체가 들통나기 때문일까요?",
  ui_story_5045_50450201_95_dialog_content = "......",
  ui_story_5045_50450201_96_dialog_content = "피트만 씨, 혹시 피트만 씨가 진범이 아닌가요?",
  ui_story_5045_50450201_97_dialog_content = "그럴 리가 있겠습니까?",
  ui_story_5045_50450201_98_dialog_content = "피트만 씨는 이리돈 씨가 가장 신뢰하는 부하 중 한 사람이에요.\n그러니까 이리돈 씨가 사무실에 나이티움을 아무렇게나 자주\n놓고 다닌다는 사실을 알고 있었을 거예요.",
  ui_story_5045_50450201_99_dialog_content = "마침 오늘 이리돈 씨가 사무실을 나서는 모습을 보고,\n사전에 준비한 예비용 열쇠를 꺼내서 사무실의 문을 열었겠죠.",
  ui_story_5045_50450201_100_dialog_content = "그렇게 서둘러 나이티움을 훔쳐 달아났다가, 나중에야 깨달았겠죠.\n범행 흔적을 지우는 걸 잊었다는 사실을 말이에요.",
  ui_story_5045_50450201_101_dialog_content = "그래서 얼른 돌아와서 지문을 지우고 문을 잠가서,\n나이티움이 알아서 사라진 것처럼 현장을 조작했을 거예요.",
  ui_story_5045_50450201_102_dialog_content = "하지만 제가 이번 사건에 휘말리게 될 줄은 예상하지 못했겠죠.",
  ui_story_5045_50450201_103_dialog_content = "그러다 이리돈 씨가 절 의심한다는 사실을 깨닫고는,\n생각을 바꿔서 제게 혐의를 뒤집어씌우려고 한 게 분명해요!",
  ui_story_5045_50450201_104_dialog_content = "그래 봐야 다 당신의 상상 아닙니까! 증거 있습니까?",
  ui_story_5045_50450201_105_dialog_content = "맞아요. 다 제 상상이죠. 그런데 왜 제가 이 얘길 하고 나서부터...",
  ui_story_5045_50450201_106_dialog_content = "갑자기 이마에 땀까지 뻘뻘 흘리면서 <color=#1875ad>주머니</color>를 만지작거리고 있는 걸까요?",
  ui_story_5045_50450201_107_dialog_content = "설마 그 주머니 안에 이리돈 씨 사무실의 예비용 열쇠가 들어 있는 건 아니겠죠?",
  ui_story_5045_50450201_108_dialog_content = "피트만 씨, 그 주머니 안에 든 물건을 확인시켜 주시겠어요?",
  ui_story_5045_50450201_109_dialog_content = "......",
  ui_story_5045_50450201_110_dialog_content = "...이것 말고 또 뭐가 있겠습니까.",
  ui_story_5045_50450201_111_dialog_content = "이 열쇠는 제 사무실 열쇠와 똑같이 생겼군요!",
  ui_story_5045_50450201_112_dialog_content = "피트만 씨, 당신이 이리돈 님의 나이티움을 훔친 진범이었나요?",
  ui_story_5045_50450201_113_dialog_content = "이렇게 된 이상 더는 할 말이 없겠군요.",
  ui_story_5045_50450201_114_dialog_content = "그렇다면...",
  ui_story_5045_50450201_115_dialog_content = "<size=45>피트만 씨에게 <color=#1875ad>유죄</color>를 선고합니다!</size>",
  ui_story_5045_50450201_116_dialog_content = "휴, 드디어 끝났네.",
  ui_story_5045_50450201_117_dialog_content = "역시 이번에도 모의 심판 심사를 통과하지 못했어...",
  ui_story_5045_50450201_118_dialog_content = "기운 내세요, 기회는 앞으로도 있을 테니까요.",
  ui_story_5045_50450201_119_dialog_content = "당신 앞의 선배들도 진정한 심판관이 되기 위해 몇 번이고 심사를 거쳤었답니다.",
  ui_story_5045_50450201_120_dialog_content = "그렇습니다. 게다가 전 심판소에서 가장 많은 탈락 기록을 보유한 사람입니다!",
  ui_story_5045_50450201_121_dialog_content = "안젤 씨, 레인 씨가 하는 말에 속으면 안 돼요.\n저건 뿌듯해할 만한 일이 전혀 아니거든요.",
  ui_story_5045_50450201_122_dialog_content = "이리돈 님, 공사가 다망하셔서 기억에 혼선이 생기신 모양이군요.\n전 단번에 심사를 통과했습니다만!",
  ui_story_5045_50450201_123_dialog_content = "아, 확실히 그랬었죠. 마침 잘 이야기했어요.",
  ui_story_5045_50450201_124_dialog_content = "지금은 뢰베도 휴가 중이니까, 그동안 안젤 양을 조수로 곁에 두고\n업무를 좀 가르쳐 주도록 하세요.",
  ui_story_5045_50450201_125_dialog_content = "이리돈 님, 명석하고 지혜로운 제게 조수는 전혀 필요치 않습니다.",
  ui_story_5045_50450201_126_dialog_content = "가장 우수한 심판관 중 하나인 당신이라면, 후배들을 교육할 책임을 감당해야죠.",
  ui_story_5045_50450201_127_dialog_content = "그런 뜻이 있으셨군요!",
  ui_story_5045_50450201_128_dialog_content = "지당하신 말씀이십니다, 이리돈 님!",
  ui_story_5045_50450201_129_dialog_content = "그렇다면 이 견습 심판관에게 제 모든 걸 전수해,\n이리돈 님의 기대에 부응하도록 하겠습니다.",
  ui_story_5045_50450201_130_dialog_content = "하지만 제 가르침을 이 견습 심판관이 모두 배울 수 있을진 장담 못 합니다.",
  ui_story_5045_50450201_131_dialog_content = "<size=32>피트만 선배님의 조수가 되고 싶었는데!</size>",
  ui_story_5045_50450301_1_dialog_content = "<color=#737378>시간: 오후 8시</color>",
  ui_story_5045_50450301_2_dialog_content = "<color=#737378>장소: 심판소 로비</color>",
  ui_story_5045_50450301_3_dialog_content = "이 사건의 진상을 밝혀내는 사람이 당신이 될 줄은 몰랐네요.",
  ui_story_5045_50450301_4_dialog_content = "운이 좋았나 봐요...",
  ui_story_5045_50450301_5_dialog_content = "(사실은 다 피트만 씨의 「훌륭한」 연기 덕분이지만...)",
  ui_story_5045_50450301_6_dialog_content = "참, 오늘 모의 심판에서 다룬 사건은 실제 사건을 살짝 각색한 거 맞죠?",
  ui_story_5045_50450301_7_dialog_content = "그런 점까지 알아챌 줄이야, 역시 PlayerName 씨답네요.",
  ui_story_5045_50450301_8_dialog_content = "그리고 하나 더 알겠어요.\n저한테 보낸 초대장은 역시 이번 일에 절 끌어들이려는 덫이었겠죠!",
  ui_story_5045_50450301_9_dialog_content = "사실 모의 심판이라고 미리 말해줬어도 전 기꺼이 도우러 왔을 거예요.",
  ui_story_5045_50450301_10_dialog_content = "실제 재판 중에는 뜻밖의 일들이 많이 발생한답니다.",
  ui_story_5045_50450301_11_dialog_content = "그래서 모의 심판에 불확실한 요소를 일부 추가하면 좋을 것 같다고 생각했어요.",
  ui_story_5045_50450301_12_dialog_content = "하지만 오늘 안젤이 재판을 마무리할 수 있었던 건 모두 당신 덕분이에요.",
  ui_story_5045_50450301_13_dialog_content = "그럼 저라는 「불확실한 요소」가 제 역할을 잘한 모양이네요?",
  ui_story_5045_50450301_14_dialog_content = "네, 세부적인 부분들을 관찰하는 능력이 무척 뛰어나더군요.",
  ui_story_5045_50450301_15_dialog_content = "과장이 아니라, 오늘 보여준 실력은 심판관 심사 합격 기준에\n도달했다고 할 수 있을 정도예요.",
  ui_story_5045_50450301_16_dialog_content = "심판소에도 당신 같은 인재가 몇 명 더 있었다면 좋았을 텐데 말이죠.",
  ui_story_5045_50450301_17_dialog_content = "이 이야기는 여기까지 하죠...",
  ui_story_5045_50450301_18_dialog_content = "아무튼 PlayerName 씨에게 감사의 뜻으로 충분한 보수를 준비했어요.",
  ui_story_5045_50450301_19_dialog_content = "보수요?",
  ui_story_5045_50450301_20_dialog_content = "방금 그 「도둑」이 제출한 「장물」이에요.",
  ui_story_5045_50450301_21_dialog_content = "전 그 나이티움들도 모의 심판용 소품인 줄 알았는데요.",
  ui_story_5045_50450301_22_dialog_content = "근데 그게 저한테 줄 보수라구요?",
  ui_story_5045_50450301_23_dialog_content = "적은가요?",
  ui_story_5045_50450301_24_dialog_content = "아, 아니요, 아니에요! 오히려 너무 많아요!",
  ui_story_5045_50450301_25_dialog_content = "나중에도 이런 일이 있으면 자주 불러 주세요! 가능하다면요!",
  ui_story_5045_50450301_26_dialog_content = "으음? PlayerName 씨도 심판소의 업무에 관심이 생긴 건가요?",
  ui_story_5045_50450301_27_dialog_content = "처음엔 좀 놀랐지만...",
  ui_story_5045_50450301_28_dialog_content = "확실히 꽤 재미있었어요.",
  ui_story_5045_50450301_29_dialog_content = "그런 평가를 들으니 기쁘네요.",
  ui_story_5045_50450301_30_dialog_content = "그렇다면 조금 더 머물면서 심판소 업무를 경험해 보는 건 어떤가요?",
  ui_story_5045_50450301_31_dialog_content = "최근 심판소에 새로운 부서가 하나 생겼는데,\n마침 당신처럼 타인의 마음을 잘 아는 사람의 도움이 필요하던 참이었어요.",
  ui_story_5045_50450301_32_dialog_content = "새로운 부서요?",
  ui_story_5045_50450301_33_dialog_content = "그럼 동의했다고 간주할게요. 이걸 받아 두세요. 분명히 쓸모가 있을 거예요.",
  ui_story_5045_50450301_34_dialog_content = "이건... <color=#1875ad>심판관 노트</color>인가요?",
  ui_story_5045_50450301_35_dialog_content = "그럼 지금부터 당신은 <color=#1875ad>견습 심판관</color>이 된 거예요.",
  ui_story_5045_50450301_36_dialog_content = "<color=#737378>시간: 오전 8시</color>",
  ui_story_5045_50450301_37_dialog_content = "<color=#737378>장소: 백야성 심판소의 어느 사무실</color>",
  ui_story_5045_50450301_38_dialog_content = "이리돈 씨가 도착하면 가 보라고 했던 곳이... 여기 맞겠지?",
  ui_story_5045_50450301_39_dialog_content = "안녕하세요. 전 오늘 업무를 도와드리러 온...",
  ui_story_5045_50450301_40_dialog_content = "어떻게 이런 사건이 있단 말입니까!",
  ui_story_5045_50450301_41_dialog_content = "원고의 말도 일리가 있는데, 피고의 말도 일리가 있다니...",
  ui_story_5045_50450301_42_dialog_content = "이건 법전에서도 참고할 만한 법 조항이나 판례를 찾을 수가 없습니다.\n대체 누구 말을 믿어야 하는 거죠?",
  ui_story_5045_50450301_43_dialog_content = "휴우우... 후우... Zzz...",
  ui_story_5045_50450301_44_dialog_content = "안젤, 잘 봤겠지?",
  ui_story_5045_50450301_45_dialog_content = "너는 날 보고 잘 배우도록 해라.\n그렇지 않으면 너도 저 둘처럼 쓸모없는 심판관이 될 테니까.",
  ui_story_5045_50450301_46_dialog_content = "하지만 제가 알기론 마티외 선배님의 업무 평가도\n두 선배님과 별로 차이가 없던데요.",
  ui_story_5045_50450301_47_dialog_content = "<size=32>아니면 이런 새로 생긴 변두리 부서에 배치되진 않았겠죠...</size>",
  ui_story_5045_50450301_48_dialog_content = "너, 너... 어떻게 뢰베 녀석보다도 더 말이 심할 수 있는 거지?",
  ui_story_5045_50450301_49_dialog_content = "거듭 말하지만, 난 개인적인 흥미와 책임감 때문에 자발적으로\n이 부서로 인사이동을 요청한 거란 말이다!",
  ui_story_5045_50450301_50_dialog_content = "아직도 모의 심판에 통과하고 싶은 생각이 있다면,\n얼른 물건 챙겨서 날 따라와라. 조사하러 갈 거니까.",
  ui_story_5045_50450301_51_dialog_content = "네...",
  ui_story_5045_50450301_52_dialog_content = "으음? PlayerName, 무슨 일로 우리 <color=#1875ad>심판소 연애 지부</color>의 입구를 막고 있는 거지?",
  ui_story_5045_50450301_53_dialog_content = "연애 지부도 이렇게 번듯한 사무실이 있었구나...",
  ui_story_5045_50450301_54_dialog_content = "흥, 번듯하긴 무슨.",
  ui_story_5045_50450301_55_dialog_content = "내가 이 지부의 대심판관이 되고 나면, 더 화려한 개인 사무실을 가지게 될 거다.",
  ui_story_5045_50450301_56_dialog_content = "뭐? 대심판관?",
  ui_story_5045_50450301_57_dialog_content = "어허! 미래의 대심판관님께서 지나가셔야 하는데 어서 비키지 못해?",
  ui_story_5045_50450301_58_dialog_content = "......",
  ui_story_5045_50450301_59_dialog_content = "휴, 연애 지부는 세워졌을 때부터 지금까지 대심판관님이 계속 바뀌다 보니\n계류된 사건들이 갈수록 늘어났거든.",
  ui_story_5045_50450301_60_dialog_content = "그래서 연애 지부의 대심판관을 맡겠다고 나서는 사람은 아무도 없어.",
  ui_story_5045_50450301_61_dialog_content = "그래도 여기 선배님들은 조금이라도 성과를 쌓으려고 엄청 노력하고 있어.\n그럼 대심판관 승진에 도움이 될 테니까.",
  ui_story_5045_50450301_62_dialog_content = "<size=45>안젤! 아직도 안 오고 뭐 해?!</size>",
  ui_story_5045_50450301_63_dialog_content = "아, 나중에 다시 얘기하자. 그럼 행운을 빌게, PlayerName!",
  ui_story_5045_50450301_64_dialog_content = "이리돈 씨가 날 새로 생긴 모의 심판 부서로 보내려는 건 줄 알았는데...",
  ui_story_5045_50450301_65_dialog_content = "왜 연애 지부로 보낸 거지...",
  ui_story_5045_50450301_66_dialog_content = "PlayerName 씨?",
  ui_story_5045_50450301_67_dialog_content = "오늘 연애 지부에 온다던 신입이 당신이었습니까?",
  ui_story_5045_50450301_68_option_content = "뭔가 착오가 있었던 것 같아.",
  ui_story_5045_50450301_69_dialog_content = "이리돈 님께서 보내신 건가요?",
  ui_story_5045_50450301_70_dialog_content = "맞아.",
  ui_story_5045_50450301_71_dialog_content = "이리돈 님께서 정하신 일이라면 결코 틀림이 없습니다.",
  ui_story_5045_50450301_72_dialog_content = "역시 당신이 연애 지부의 신입인 거군요!",
  ui_story_5045_50450301_73_option_content = "내가 방해가 안 됐으면 좋겠어.",
  ui_story_5045_50450301_74_dialog_content = "너무 겸손하시군요.",
  ui_story_5045_50450301_75_dialog_content = "이리돈 님께서 직접 파견하신 이상, 분명히 저도 보고 배울 점이 있을 겁니다!",
  ui_story_5045_50450301_76_option_content = "레인 씨가 여기 있어서 다행이야.",
  ui_story_5045_50450301_77_dialog_content = "레인 씨 같은 믿음직한 사람이 있다면 조금 안심할 수 있을 테니까.",
  ui_story_5045_50450301_78_dialog_content = "앞으로 잘 부탁할게!",
  ui_story_5045_50450301_79_dialog_content = "그러지 마십시오. 저도 연애 지부 쪽의 업무 처리 경험은 많지 않습니다.\n엄밀히 말하면 저 역시 신입입니다.",
  ui_story_5045_50450301_80_dialog_content = "Zzz... Zzz...",
  ui_story_5045_50450301_81_dialog_content = "...아, 누가 왔나요?",
  ui_story_5045_50450301_82_dialog_content = "어머? 어제 모의 심판에서 멋진 활약을 보여준 피고 PlayerName 씨잖아요?",
  ui_story_5045_50450301_83_dialog_content = "믿기진 않지만, 설마 당신도 연애 문제로 분쟁이 생긴 건가요?",
  ui_story_5045_50450301_84_dialog_content = "그럼 자세한 경위가 담긴 소장을 적어서 제출해 주세요.\n제가 최대만 빨리 처리해 드릴게요... 하아암.",
  ui_story_5045_50450301_85_option_content = "그런 쪽으로는 전혀 문제없거든?!",
  ui_story_5045_50450301_86_dialog_content = "아, 자신만만하시네요.",
  ui_story_5045_50450301_87_dialog_content = "그럼 당신은 밀당을 잘하는 나쁜 남자인가요? 아니면 둔한 철벽남인가요?\n제가 한 번 맞혀 볼게요.",
  ui_story_5045_50450301_88_dialog_content = "두, 둘 다 아니야. 난 그냥 여기 일을 도와주러 온 거라고.",
  ui_story_5045_50450301_89_dialog_content = "어머, 신입으로 누가 오려나 했는데, 당신이었군요? 그거 잘됐네요!",
  ui_story_5045_50450301_90_option_content = "자는데 깨워서 미안해.",
  ui_story_5045_50450301_91_dialog_content = "네? 시끄러워서 깨고 사과받아 보는 건 오늘이 처음이에요...\n정말 감동이에요...",
  ui_story_5045_50450301_92_dialog_content = "아무튼 전 괜찮으니까 신경 쓰지 마세요.\n어차피 오늘 신입이 온다고 들어서 슬슬 일어나려고 했거든요.",
  ui_story_5045_50450301_93_dialog_content = "그 신입이 왠지... 나인 것 같아.",
  ui_story_5045_50450301_94_dialog_content = "어머, 신입으로 누가 오려나 했는데, 당신이었군요? 그거 잘됐네요!",
  ui_story_5045_50450301_95_option_content = "난 여기 일 도와주러 온 거야.",
  ui_story_5045_50450301_96_dialog_content = "내가 도움이 될진 잘 모르겠지만...",
  ui_story_5045_50450301_97_dialog_content = "어머, 제가 손꼽아 기다려 왔던 최고의 인재가 벌써 제 앞에 와 있었네요.",
  ui_story_5045_50450301_98_dialog_content = "어젯밤엔 PlayerName 씨가 연애 지부에 들어오는 꿈도 꿨었는데,\n오늘 그 꿈이 현실이 될 줄은 정말 몰랐는걸요.",
  ui_story_5045_50450301_99_dialog_content = "역시 잠이 많고, 꿈도 많이 꾸는 게 꼭 나쁜 일인 건 아니라니까요~",
  ui_story_5045_50450301_100_dialog_content = "PlayerName 씨 도움을 받는다면 아마 저도 대심판관으로\n승진할 수 있지 않을까요?",
  ui_story_5045_50450301_101_dialog_content = "티나, 그게 무슨 말입니까?",
  ui_story_5045_50450301_102_dialog_content = "어라? 레인 씨, 아직 모르시겠어요?",
  ui_story_5045_50450301_103_dialog_content = "이 연애 지부라는 골칫덩이 지부의 대심판관을 맡겠다고\n나선 사람은 아직까지 없어요.",
  ui_story_5045_50450301_104_dialog_content = "마티외 씨는 아직 이 지부의 대심판관이 정해지지 않은 틈을 노려\n자기가 첫 번째로 사건을 맡아 판결을 내리려고 움직이기 시작했어요.",
  ui_story_5045_50450301_105_dialog_content = "그렇게 되면 이리돈 님께서도 연애 지부의 대심판관으로\n마티외 씨를 임명하는 걸 고려하실지도 몰라요.",
  ui_story_5045_50450301_106_dialog_content = "마티외 씨가 이 연애 지부의 대심판관이 된다는 겁니까?",
  ui_story_5045_50450301_107_dialog_content = "네, 그렇게 된다면 앞으로 어떻게 되겠어요?\n차라리 우리 둘 중 하나가 이 지부의 대심판관이 되는 게 나아요.",
  ui_story_5045_50450301_108_dialog_content = "레인 씨가 대심판관이 되겠다고 하면 저도 반대는 안 해요.",
  ui_story_5045_50450301_109_dialog_content = "하지만 그렇게 되면 이제 막 세워진 우리 연애 지부를\n무시하는 사람들이 더 많아질 수도 있어요.",
  ui_story_5045_50450301_110_dialog_content = "저 한 사람을 무시하는 건 괜찮습니다만, 연애 지부를 얕보게 둘 순 없습니다!",
  ui_story_5045_50450301_111_dialog_content = "제가 대심판관이 된다면, 반드시 최선을 다해 이 연애 지부를\n존중받아 마땅한 지부로 만들 겁니다.",
  ui_story_5045_50450301_112_dialog_content = "음... 그럼 레인 씨도 대심판관 자리에 관심이 없는 건 아닌 모양이네요.",
  ui_story_5045_50450301_113_dialog_content = "잘됐어요. 그럼 우리 세 사람 다 공평하게 경쟁하도록 해요.",
  ui_story_5045_50450301_114_dialog_content = "대신 PlayerName 씨는 꼭 제 편이 돼 주셔야 해요~",
  ui_story_5045_50450301_115_dialog_content = "PlayerName 씨는 이 부서 전체의 업무를 도우러 온 겁니다.\n어떻게 티나 한 사람만의 편이 될 수 있겠습니까?",
  ui_story_5045_50450301_116_dialog_content = "어머? 레인 씨는 혼자서 일하는 걸 선호하지 않았나요?",
  ui_story_5045_50450301_117_dialog_content = "혹시 제가 PlayerName 씨를 데려간다고 하니까 질투하시는 건가요?",
  ui_story_5045_50450301_118_dialog_content = "근데 그 질투의 대상은 저인가요? 아니면 PlayerName 씨인가요?",
  ui_story_5045_50450301_119_dialog_content = "전 그저 티나가 PlayerName 씨에게 너무 부담을 주진 않을까 걱정한 겁니다.",
  ui_story_5045_50450301_120_dialog_content = "티나가 일할 수 있는 시간은 무척 짧고, 우리의 업무량은 굉장히 많습니다...\n설마 그걸 다 PlayerName 씨에게 맡기려는 건 아니겠죠?",
  ui_story_5045_50450301_121_dialog_content = "레인 씨가 이렇게 배려심이 좋은 줄은 몰랐네요~",
  ui_story_5045_50450301_122_dialog_content = "아무튼 이 일은 신중하게 논의할 필요가 있습니다.",
  ui_story_5045_50450301_123_dialog_content = "저한테 좋은 생각이 있어요.",
  ui_story_5045_50450301_124_dialog_content = "누구 조수가 되고 싶은지 PlayerName 씨한테 고르라고 해요.",
  ui_story_5045_50450301_125_dialog_content = "그것도 좋겠군요.\nPlayerName 씨가 선택한다면 우리 두 사람 모두에게 공평할 테니까요.",
  ui_story_5045_50450301_126_dialog_content = "PlayerName 씨는 어떻게 생각하십니까?",
  ui_story_5045_50450301_127_dialog_content = "그게... 고르기 너무 어려워.",
  ui_story_5045_50450301_128_dialog_content = "그렇게 망설일 거 없어요. 누굴 택해도 손해는 안 볼 테니까요.\n참고로 전 추가 보수도 어느 정도 제공할 생각이에요.",
  ui_story_5045_50450301_129_dialog_content = "윽...",
  ui_story_5045_50450301_130_dialog_content = "전 추가 보수는 제공할 수 없지만, 노동력을 착취하는 일은 절대 없을 겁니다.",
  ui_story_5045_50450301_131_dialog_content = "힘든 일은 다 제가 할 테니, 제가 가장 공정하게 일을 처리할 수 있도록\n옆에서 조언만 해 주시면 됩니다!",
  ui_story_5045_50450301_132_dialog_content = "(두 사람 다 내 도움을 엄청 받고 싶어 하는 것 같은데...)",
  ui_story_5045_50450301_133_dialog_content = "(어떻게 하는 게 좋을까?)",
  ui_story_5045_50450301_134_option_content = "(레인을 선택한다)",
  ui_story_5045_50450301_135_dialog_content = "사실 난 내가 심판관 업무에 무슨 도움을 줄 수 있을지 전혀 모르겠거든.",
  ui_story_5045_50450301_136_dialog_content = "그래도 레인 씨 말대로 옆에서 조언해 주는 정도라면 할 수 있을 것 같아.",
  ui_story_5045_50450301_137_dialog_content = "전 당신이라면 분명히 잘하실 거라 믿습니다!",
  ui_story_5045_50450301_138_option_content = "(티나를 선택한다)",
  ui_story_5045_50450301_139_dialog_content = "티나가 그렇게 도움이 필요하다면 한번 해 볼게.",
  ui_story_5045_50450301_140_dialog_content = "대신 미리 말해 두는데 나 심판에 대한 건 진짜 몰라!",
  ui_story_5045_50450301_141_dialog_content = "걱정하지 마세요.\n절 선택한 이상 제가 다 가르쳐 드릴 테니까요... 하아암.",
  ui_story_5045_50450301_142_dialog_content = "근데 그 전에 전 일단 눈 좀 붙일게요.",
  ui_story_5045_50450301_143_option_content = "(아무도 선택하지 않는다)",
  ui_story_5045_50450301_144_dialog_content = "다들 나보고 연애 지부로 발령 난 신입이라고 하는데,\n그럼 나도 대심판관 경쟁에 뛰어들 수 있는 거 아냐?",
  ui_story_5045_50450301_145_dialog_content = "그건 그렇지만 그 전에 먼저 심판관부터 돼야죠.",
  ui_story_5045_50450301_146_dialog_content = "티나, PlayerName 씨는 혼자서 심판을 내릴 자신이 있는 것 같군요.\n그러니 우리도 강요하지 않는 게 좋겠습니다.",
  ui_story_5045_50450301_147_dialog_content = "어쩌면 마티외 씨처럼 짧은 시간에 어엿한 심판관이 될지 누가 알겠습니까.",
  ui_story_5045_50450301_148_dialog_content = "그래요, 알겠어요... 하아암.",
  ui_story_5045_50450401_1_dialog_content = "<color=#737378>시간: 오후 6시</color>",
  ui_story_5045_50450401_2_dialog_content = "<color=#737378>장소: 백야성 심판소, 연애 지부 사무실</color>",
  ui_story_5045_50450401_3_dialog_content = "레인 씨, 내가 뭐 도와줄 거 있어?",
  ui_story_5045_50450401_4_dialog_content = "아, 항소인이 제출한 소장을 접수해 주시면 됩니다.",
  ui_story_5045_50450401_5_dialog_content = "나머지는 제게 맡기세요.",
  ui_story_5045_50450401_6_dialog_content = "하지만 벌써 시간이 이렇게 됐으니 이제 퇴근하셔도 됩니다.",
  ui_story_5045_50450401_7_dialog_content = "그럼 레인 씨는?",
  ui_story_5045_50450401_8_dialog_content = "오늘도 소장이 또 100건 넘게 들어왔습니다.\n전 일단 한 번씩 꼼꼼히 읽어 보려고 합니다.",
  ui_story_5045_50450401_9_dialog_content = "그리고 내용에 흠이 있는 건들을 추려내 당사자에게 내용을 보정해서\n다시 제출하도록 보정명령을 내려야 합니다.",
  ui_story_5045_50450401_10_dialog_content = "시간이 이렇게 늦었는데, 야근해야 되는 거야?",
  ui_story_5045_50450401_11_dialog_content = "솔직히 말씀드리죠...\n연애 지부의 이 안건들은 제가 처리하기엔 모두 쉽지 않은 일들입니다.",
  ui_story_5045_50450401_12_dialog_content = "어떻게 하면 이런 까다로운 일들을 더 잘 판결할 수 있을지\n전 앞으로도 배워야 할 것들이 많습니다.",
  ui_story_5045_50450401_13_dialog_content = "근데 내가 아까부터 쭉 보니까, 지금 소장들을 전부 다 퇴짜 놓은 것 같았는데?",
  ui_story_5045_50450401_14_dialog_content = "백야성의 관련 최신 개정 법령에 따르면,\n지금까지 제가 검토한 모든 소장에 문제가 있었습니다.",
  ui_story_5045_50450401_15_dialog_content = "전 법과 절차에 따라 업무를 진행했을 뿐입니다.",
  ui_story_5045_50450401_16_dialog_content = "계속 그러면 첫 심리는 언제 하고, 판결은 또 언제 내릴 수 있겠어?",
  ui_story_5045_50450401_17_dialog_content = "저보다 더 급해 보이시는군요.",
  ui_story_5045_50450401_18_dialog_content = "당연하지! 우린 파트너잖아!",
  ui_story_5045_50450401_19_dialog_content = "파트너...?",
  ui_story_5045_50450401_20_dialog_content = "그래!",
  ui_story_5045_50450401_21_dialog_content = "마음은 감사합니다만, 전 노동력 착취는 절대 없을 거라 했던\n제 약속을 지키고 싶습니다.",
  ui_story_5045_50450401_22_dialog_content = "알겠어... 아니면 내가 옆에서 같이 얘기라도 해주는 건 어때?\n그럼 레인 씨도 긴장이 조금 풀리지 않을까?",
  ui_story_5045_50450401_23_dialog_content = "그러죠. 마침 PlayerName 씨의 의견을 듣고 싶던 참이었습니다.",
  ui_story_5045_50450401_24_dialog_content = "사랑이 뭔지 아십니까?",
  ui_story_5045_50450401_25_dialog_content = "사, 사랑...?",
  ui_story_5045_50450401_26_option_content = "알지!",
  ui_story_5045_50450401_27_dialog_content = "두 사람이 서로 좋아하고, 항상 서로의 곁에 있길 바라는 거잖아.",
  ui_story_5045_50450401_28_dialog_content = "그런 것까지 알고 계실 줄이야! 역시 PlayerName 씨입니다!",
  ui_story_5045_50450401_29_dialog_content = "사, 사실 그냥 대충 말해본 거야...",
  ui_story_5045_50450401_30_option_content = "잘 모르겠어...",
  ui_story_5045_50450401_31_dialog_content = "그치만 가끔 어떤 소설들에서 자세히 묘사된 걸 본 적은 있어.",
  ui_story_5045_50450401_32_dialog_content = "아무튼 엄청 심오한 감정 같았어.",
  ui_story_5045_50450401_33_dialog_content = "PlayerName 씨는 연애 소설을 많이 읽어 보셨습니까?\n역시 제가 물어볼 사람을 잘 찾은 것 같군요.",
  ui_story_5045_50450401_34_dialog_content = "그, 그렇게 많이 읽진 않았는데...",
  ui_story_5045_50450401_35_option_content = "안 알려줄래!",
  ui_story_5045_50450401_36_dialog_content = "그건 내 비밀이니까!",
  ui_story_5045_50450401_37_dialog_content = "그렇게까지 비밀스러운 겁니까...",
  ui_story_5045_50450401_38_dialog_content = "그나저나 레인 씨는 인기 많지 않아?",
  ui_story_5045_50450401_39_dialog_content = "그런 건 나보다 더 잘 알 것 같은데...",
  ui_story_5045_50450401_40_dialog_content = "그게...",
  ui_story_5045_50450401_41_dialog_content = "결론만 보자면, 확실히 많은 여성분께서 제게 과한 호감을 표현하긴 합니다.",
  ui_story_5045_50450401_42_dialog_content = "하지만 유감스럽게도 전 그분들의 마음을 받아줄 수 없습니다.",
  ui_story_5045_50450401_43_dialog_content = "어? 왜?",
  ui_story_5045_50450401_44_dialog_content = "저도 모르겠습니다.\n그리고 지금까진 그런 쪽에 대해선 진지하게 생각해 본 적도 없었습니다.",
  ui_story_5045_50450401_45_dialog_content = "하지만 지금 제가 연애 지부로 전출을 오게 된 이상,\n사람들이 관련 분쟁을 해결할 수 있도록 도와야 합니다.",
  ui_story_5045_50450401_46_dialog_content = "그런데 이제야 깨달은 겁니다.\n사실 전 사랑이 뭔지 줄곧 모르고 있었다는 걸 말이죠.",
  ui_story_5045_50450401_47_dialog_content = "결국 전 자신을 의심하기 시작했습니다.\n사랑이 뭔지 느껴본 적도 없는 제가...",
  ui_story_5045_50450401_48_dialog_content = "과연 연애 지부에서 좋은 심판관이 될 수 있을지 말입니다.",
  ui_story_5045_50450401_49_dialog_content = "레인 씨는 당연히 좋은 심판관이 될 수 있지!",
  ui_story_5045_50450401_50_dialog_content = "어떻게 그렇게 확신하십니까?",
  ui_story_5045_50450401_51_dialog_content = "절도 사건을 심의한다고 해서, 자기가 절도를 저질러야 할 필요는 없잖아?",
  ui_story_5045_50450401_52_dialog_content = "난 연애 쪽도 똑같다고 생각해.",
  ui_story_5045_50450401_53_dialog_content = "조금 억지스러운 비유긴 하지만...",
  ui_story_5045_50450401_54_dialog_content = "일리가 없진 않군요!",
  ui_story_5045_50450401_55_dialog_content = "계속 이 소장들을 들여다본다고 문제가 해결되는 건 아니야.\n중요한 건 역시 실전이지!",
  ui_story_5045_50450401_56_dialog_content = "몇몇 사건의 심리를 진행해 보면 경험도 생기고, 노하우도 쌓일 거야.",
  ui_story_5045_50450401_57_dialog_content = "그것도 그렇군요... 확실히 제가 요즘 정신이 없긴 없나 봅니다.",
  ui_story_5045_50450401_58_dialog_content = "그럼 지금 눈앞에 있는 사건부터 시작해 보자!",
  ui_story_5045_50450401_59_dialog_content = "「피고 <color=#1875ad>소피</color>와 원고 <color=#1875ad>퍼렐</color>의 약혼 계약에 대한 유효확인의 소를 청구한다...」?",
  ui_story_5045_50450401_60_dialog_content = "이, 이상한 요청이네... 아무래도 좀 번거로울 것 같으니까 다른 걸로 바꿀까?",
  ui_story_5045_50450401_61_dialog_content = "바꾸지 않아도 됩니다.",
  ui_story_5045_50450401_62_dialog_content = "심판관에게 사건을 고를 권리는 없습니다.\n우린 모든 사건에 책임을 다해야 합니다.",
  ui_story_5045_50450401_63_dialog_content = "게다가...",
  ui_story_5045_50450401_64_dialog_content = "당신에게 고작 소장 정리나 부탁하는 건\n인재를 보잘것없는 일에 쓰는 일입니다.",
  ui_story_5045_50450401_65_dialog_content = "그러니 내일 이 건의 심리를 도와주셨으면 좋겠습니다.",
  ui_story_5045_50450401_66_dialog_content = "어? 나도 같이 심리하는 거야?",
  ui_story_5045_50450401_67_dialog_content = "조금 전에 그러지 않으셨습니까? 당신은 제 파트너라고요.",
  ui_story_5045_50450501_1_dialog_content = "<color=#737378>시간: 오전 9시</color>",
  ui_story_5045_50450501_2_dialog_content = "<color=#737378>장소: 백야성 심판소, 소심판정</color>",
  ui_story_5045_50450501_3_dialog_content = "레인 님이야! 레인 님이 오셨어!",
  ui_story_5045_50450501_4_dialog_content = "......",
  ui_story_5045_50450501_5_dialog_content = "(어째 재판이 아니라 레인 씨를 보려고 온 것 같은 여성분들이 많아 보이는데?)",
  ui_story_5045_50450501_6_dialog_content = "<color=#737378>탕!</color>",
  ui_story_5045_50450501_7_dialog_content = "<size=45>만물은 백야 아래에, 지금부터 재판을 시작하겠습니다!</size>",
  ui_story_5045_50450501_8_dialog_content = "만물은 백야 아래에!",
  ui_story_5045_50450501_9_dialog_content = "......",
  ui_story_5045_50450501_10_dialog_content = "PlayerName 씨, 누구의 발언을 먼저 들어야 하는지 기억하고 계십니까?",
  ui_story_5045_50450501_11_dialog_content = "누구의 발언부터 들어야 하냐고? 음, 원고부터니까...",
  ui_story_5045_50450501_12_option_content = "퍼렐 씨 발언부터 들어야 해.",
  ui_story_5045_50450501_13_dialog_content = "맞습니다. 아주 잘 기억하고 계셨군요!",
  ui_story_5045_50450501_14_option_content = "소피 씨 발언부터 들어야 해.",
  ui_story_5045_50450501_15_dialog_content = "원고는 퍼렐 씨입니다.",
  ui_story_5045_50450501_16_dialog_content = "원고와 피고를 확인하는 것은 심판관 직무의 기본입니다.\n앞으로는 주의해 주십시오.",
  ui_story_5045_50450501_17_dialog_content = "(으... 어떻게 이런 기본적인 걸 잘못 기억하고 있었지?)",
  ui_story_5045_50450501_18_dialog_content = "(다음부턴 중요한 부분은 다 노트에 자세히 적어 둬야겠어!)",
  ui_story_5045_50450501_19_dialog_content = "지금부터 원고 퍼렐 씨의 의견 진술을 청취하겠습니다.",
  ui_story_5045_50450501_20_dialog_content = "존경하는 심판관님, 저는 퍼렐이라고 합니다.",
  ui_story_5045_50450501_21_dialog_content = "원고는 백야성 <color=#1875ad>기사</color>였잖아?!",
  ui_story_5045_50450501_22_dialog_content = "PlayerName, 심판관은 사건 당사자에게 그 어떤 형식의\n주관적 판단도 내려서는 안 됩니다.",
  ui_story_5045_50450501_23_dialog_content = "아, 알겠어...",
  ui_story_5045_50450501_24_dialog_content = "원고는 소의 청구원인을 설명해 주시기 바랍니다.",
  ui_story_5045_50450501_25_dialog_content = "저와 피고 소피는 전에 약속을 하나 했습니다.",
  ui_story_5045_50450501_26_dialog_content = "어떤 약속입니까? 구체적으로 말씀해 주십시오.",
  ui_story_5045_50450501_27_dialog_content = "두 사람은 쌍방의 <color=#1875ad>경제력이 거의 동등해졌을 때</color> 결혼을 하겠다는 약속을 했습니다.",
  ui_story_5045_50450501_28_dialog_content = "저건 흔한 일이잖아? 서로 손해 보는 건 싫으니까 약혼 계약을 하는 거지.",
  ui_story_5045_50450501_29_dialog_content = "저 소피라는 피고, 딱 봐도 가난해 보이는데,\n기사랑 결혼해서 팔자 한 번 펴 볼 생각이었나 보네.",
  ui_story_5045_50450501_30_dialog_content = "이런 시시한 일로 우리 레인 심판관님을 성가시게 만든 거야?",
  ui_story_5045_50450501_31_dialog_content = "<color=#737378>탕!</color>",
  ui_story_5045_50450501_32_dialog_content = "정숙하세요!",
  ui_story_5045_50450501_33_dialog_content = "원고, 그 약속을 증명하는 증거나 증인이 있습니까?",
  ui_story_5045_50450501_34_dialog_content = "이, 있습니다.",
  ui_story_5045_50450501_35_dialog_content = "이건 백야성의 가장 표준적인 양식으로 쓰인 <color=#1875ad>계약서</color>입니다.",
  ui_story_5045_50450501_36_dialog_content = "음... 이 계약서는 확실히 백야성의 법률 기준에 부합하는군요.",
  ui_story_5045_50450501_37_dialog_content = "그렇다면 원고는 무슨 이유로 소를 제기했습니까?",
  ui_story_5045_50450501_38_dialog_content = "이제는 저와 피고의 경제력이 거의 동등해졌습니다.\n따라서 계약대로 피고와의 혼인이 유효함을 인정해 주십시오!",
  ui_story_5045_50450501_39_dialog_content = "뭐? 방금 내가 잘못 들은 거 아니지?",
  ui_story_5045_50450501_40_dialog_content = "평민이 어떻게 기사랑 재력이 비슷해질 수 있어?",
  ui_story_5045_50450501_41_dialog_content = "뻔하지. 저 소피라는 여자가 기사를 속여서 돈을 뜯어낸 거겠지.",
  ui_story_5045_50450501_42_dialog_content = "피고 소피 씨.",
  ui_story_5045_50450501_43_dialog_content = "네, 심판관님.",
  ui_story_5045_50450501_44_dialog_content = "피고는 해당 계약서에 대해 진술할 의견이 있습니까?",
  ui_story_5045_50450501_45_dialog_content = "심판관님, 그 계약서는 제가 서명을 한 게 맞습니다.",
  ui_story_5045_50450501_46_dialog_content = "하지만 원고를 만났을 무렵의 전 세상 물정을 잘 모르는 상태였고,\n사랑이 무엇인지도 전혀 몰랐습니다.",
  ui_story_5045_50450501_47_dialog_content = "원고는 제게 관심을 가지고 보살펴 주었고,\n전 그런 모습을 통해 원고가 제 평생의 반려라고 믿었습니다.",
  ui_story_5045_50450501_48_dialog_content = "그렇게 당시의 전 거짓된 사랑에 눈이 멀어 있었기 때문에\n이러한 계약서에 서명을 한 것입니다.",
  ui_story_5045_50450501_49_dialog_content = "그러나 시간이 지나고, 전 원고와 제가 하나부터 열까지 서로 안 맞는\n사이라는 사실을 깨닫고 원고와 헤어졌습니다.",
  ui_story_5045_50450501_50_dialog_content = "따라서 전 계약서의 내용대로 그와 혼인 관계가 될 수 없습니다.",
  ui_story_5045_50450501_51_dialog_content = "결국 계약 내용을 이행하지 않겠다는 것이 피고의 주장 맞습니까?",
  ui_story_5045_50450501_52_dialog_content = "그렇습니다. 제가 사랑하지 않는 이와 남은 평생을 함께하느니...\n차라리 감옥에 가겠습니다.",
  ui_story_5045_50450501_53_dialog_content = "소피, 부탁이야. 나한테 이러지 마...",
  ui_story_5045_50450501_54_dialog_content = "우리가 파혼하면 기사로서의 내 명예도 바닥에 떨어진다는 거 당신도 알잖아.",
  ui_story_5045_50450501_55_dialog_content = "그리고 내가 당신을 얼마나 사랑하는지 아직도 모르는 거야?",
  ui_story_5045_50450501_56_dialog_content = "그 사랑... 난 감당 못 하겠어...",
  ui_story_5045_50450501_57_dialog_content = "당신이 말하는 사랑은 날 끝없이 감시하고 스토킹하는 거잖아!",
  ui_story_5045_50450501_58_dialog_content = "소피, 그건 다 당신을 지키려고 그런 거야.",
  ui_story_5045_50450501_59_dialog_content = "미안하지만 난 그 누구의 보호도 받을 필요 없어.",
  ui_story_5045_50450501_60_dialog_content = "진짜 희한하네...",
  ui_story_5045_50450501_61_dialog_content = "저 두 사람 대체 무슨 사연인 거지? 이해가 안 돼.",
  ui_story_5045_50450501_62_dialog_content = "(왜 싸우기 시작한 거야? 방청객들도 웅성거리기 시작했잖아.)",
  ui_story_5045_50450501_63_dialog_content = "(레인 씨도 골치가 아픈 건지 한숨을 쉬었고 말이야...)",
  ui_story_5045_50450501_64_dialog_content = "PlayerName, 이제 왜 연애 지부가 사람들이 기피하는\n근무지인지 이해하셨겠죠.",
  ui_story_5045_50450501_65_dialog_content = "이런 사건은 참고할 만한 기존의 법 조항과 판례가 존재하지 않기 때문입니다.",
  ui_story_5045_50450501_66_dialog_content = "쌍방 당사자의 주장이 모두 일리가 있어서,\n심판관으로서도 공정한 심판을 내리기가 무척 힘듭니다.",
  ui_story_5045_50450501_67_dialog_content = "하지만 괜찮습니다.\n이건 제게 있어서 일종의 훈련이니, 최선을 다해서 공정함을 관철할 겁니다!",
  ui_story_5045_50450501_68_dialog_content = "혹시 이번 사건에 관해 찾으신 실마리가 있습니까?",
  ui_story_5045_50450501_69_dialog_content = "아직까진 없어...",
  ui_story_5045_50450501_70_dialog_content = "아, 좋은 생각이 떠올랐어!",
  ui_story_5045_50450501_71_dialog_content = "아무래도 우리 둘 다 차분히 좀 생각을 해 봐야 할 것 같군요.",
  ui_story_5045_50450501_72_dialog_content = "그래...",
  ui_story_5045_50450501_73_dialog_content = "레인, 이것 좀 봐...",
  ui_story_5045_50450501_74_dialog_content = "으음? 아, 정말 그리운 <color=#1875ad>노트</color>로군요.",
  ui_story_5045_50450501_75_dialog_content = "제가 견습 심판관이었을 무렵엔 저도 매일 가지고 다녔었죠.",
  ui_story_5045_50450501_76_dialog_content = "그렇지만 지금은 한가하게 이런 대화를 나눌 때는 아닌 것 같군요.",
  ui_story_5045_50450501_77_dialog_content = "그보다는 이 사건에 대한 견해를 말씀해 주시지 않겠습니까?",
  ui_story_5045_50450501_78_dialog_content = "음...",
  ui_story_5045_50450501_79_dialog_content = "재판의 쟁점은 역시 <color=#1875ad>계약서</color>에 있지 않을까?",
  ui_story_5045_50450501_80_dialog_content = "좋은 의견입니다.",
  ui_story_5045_50450501_81_dialog_content = "어쩌면 저 두 사람 사이의 꼬이고 뒤틀린 감정은\n제가 결코 해결해 줄 수 없는 것일지도 모릅니다.",
  ui_story_5045_50450501_82_dialog_content = "하지만 문서로 남은 계약서는 백야성의 법률에 따라 그 권리를 보호받습니다!",
  ui_story_5045_50450501_83_dialog_content = "그 점을 상기시켜 주셔서 감사합니다. 덕분에 답을 얻었습니다.",
  ui_story_5045_50450501_84_dialog_content = "어떤 답인데?",
  ui_story_5045_50450501_85_dialog_content = "곧 알게 되실 겁니다.",
  ui_story_5045_50450501_86_dialog_content = "<color=#737378>탕!</color>",
  ui_story_5045_50450501_87_dialog_content = "만물은 백야 아래에, 지금부터 판결을 선고하겠습니다!",
  ui_story_5045_50450501_88_dialog_content = "피고 소피는 계약서를 작성할 당시 이미 성인이었으므로,\n자신의 행동에 책임을 져야 합니다.",
  ui_story_5045_50450501_89_dialog_content = "백야성의 관련 법률 규정에 따라...",
  ui_story_5045_50450501_90_dialog_content = "피고 소피와 원고 퍼렐의 약혼 계약은 유효하며,\n피고에게 계약 사항을 이행할 것을 명령합니다.",
  ui_story_5045_50450501_91_dialog_content = "이 판결에 불복하는 경우, 심판소의 규정에 따라 항소할 수 있습니다.",
  ui_story_5045_50450501_92_dialog_content = "<color=#737378>탕!</color>",
  ui_story_5045_50450501_93_dialog_content = "이상으로 재판을 마치겠습니다!",
  ui_story_5045_50450501_94_dialog_content = "원고가 피고에게 한 잘못된 행동을 쟁점으로 삼아야 하지 않을까?",
  ui_story_5045_50450501_95_dialog_content = "그렇습니다, PlayerName.\n이 사건의 중요한 쟁점을 파악하셨군요!",
  ui_story_5045_50450501_96_dialog_content = "피고, 아까 원고로부터 감시와 스토킹을 당했다고 한 발언이 사실입니까?",
  ui_story_5045_50450501_97_dialog_content = "거짓 하나 없는 사실입니다!",
  ui_story_5045_50450501_98_dialog_content = "원고는 자주 일을 핑계로 저희 집 문 앞을 서성였습니다.",
  ui_story_5045_50450501_99_dialog_content = "전 분명히 확실하게 거절했어요.\n하지만 원고는 미련을 못 버렸고, 이젠 저한테 소송까지 걸었죠.",
  ui_story_5045_50450501_100_dialog_content = "심판관님, 저희 집안은 한때는 형편이 괜찮았지만,\n지금은 가세가 기울어 지위도 재산도 없습니다.",
  ui_story_5045_50450501_101_dialog_content = "하지만 가세가 기울었다고 누가 절 마음대로 해도 된다는 건 아니잖아요.",
  ui_story_5045_50450501_102_dialog_content = "제게는 누군가를 사랑할 권리도, 사랑하지 않을 권리도 있습니다!",
  ui_story_5045_50450501_103_dialog_content = "이런 권리를 지켜 주기 위해 존재하는 곳이 바로 심판소 연애 지부 아닌가요?",
  ui_story_5045_50450501_104_dialog_content = "(피고의 말... 굉장히 설득력이 있어!)",
  ui_story_5045_50450501_105_dialog_content = "(생각해 보니까 확실히 그 기사는 왠지 남에게 강요하는 면이 있어 보였어.)",
  ui_story_5045_50450501_106_dialog_content = "피고는 사랑에 관해 무척 독특한 견해를 가지고 있군요.\n저도 덕분에 많이 배웠습니다.",
  ui_story_5045_50450501_107_dialog_content = "심판소 연애 지부는 물론 사랑 앞에서도 정의를 끝까지 관철할 겁니다!",
  ui_story_5045_50450501_108_dialog_content = "<color=#737378>탕!</color>",
  ui_story_5045_50450501_109_dialog_content = "만물은 백야 아래에, 지금부터 판결을 선고하겠습니다!",
  ui_story_5045_50450501_110_dialog_content = "원고와 피고가 체결한 계약 자체는 유효합니다.",
  ui_story_5045_50450501_111_dialog_content = "그러나 피고가 원고와의 혼인을 원하지 않게 되어 계약을 파기한 결과에는\n원고의 귀책사유도 있습니다.",
  ui_story_5045_50450501_112_dialog_content = "본 심판소는 피고가 원고에게 위약금 100만 나이티움을\n규정 기한 내에 지급할 것을 명령합니다.",
  ui_story_5045_50450501_113_dialog_content = "또한 원고는 위약금을 받은 후, 다시는 피고를 스토킹해서는 안 됩니다.",
  ui_story_5045_50450501_114_dialog_content = "이 판결에 불복하는 경우, 심판소의 규정에 따라 항소할 수 있습니다.",
  ui_story_5045_50450501_115_dialog_content = "퍼렐 저 녀석, 기사의 명예에 먹칠을 하다니!",
  ui_story_5045_50450501_116_dialog_content = "역시 우리 레인 심판관님이야~ 정말 과감하고 공정한 판결을 내려 주셨잖아!",
  ui_story_5045_50450501_117_dialog_content = "레인 님! 레인 님! 저희의 사랑할 권리도 레인 님이 지켜 주세요~",
  ui_story_5045_50450501_118_dialog_content = "<color=#737378>탕!</color>",
  ui_story_5045_50450501_119_dialog_content = "이상으로 재판을 마치겠습니다!",
  ui_story_5045_50450601_1_dialog_content = "<color=#737378>시간: 정오 12시</color>",
  ui_story_5045_50450601_2_dialog_content = "<color=#737378>장소: 백야성 심판소, 심판소 로비</color>",
  ui_story_5045_50450601_3_dialog_content = "소피, 소피!",
  ui_story_5045_50450601_4_dialog_content = "가까이 오지 마.",
  ui_story_5045_50450601_5_dialog_content = "나도 알아. 내가 이 재판에서 이긴다 해도, 당신은 나와 결혼하고 싶지 않겠지.",
  ui_story_5045_50450601_6_dialog_content = "그, 그래도 잠깐만 시간을 내줘! 우리 애기 좀 해!",
  ui_story_5045_50450601_7_dialog_content = "할 얘기 있으면 심판소에서 해.",
  ui_story_5045_50450601_8_dialog_content = "<color=#737378>시간: 오후 2시</color>",
  ui_story_5045_50450601_9_dialog_content = "<color=#737378>장소: 백야성 심판소, 연애 지부 사무실</color>",
  ui_story_5045_50450601_10_dialog_content = "레인 씨, 왜 아직도 그 약혼 계약서를 보고 있어?",
  ui_story_5045_50450601_11_dialog_content = "당신은 제가 이 사건에 내린 판결을 어떻게 생각하십니까?",
  ui_story_5045_50450601_12_dialog_content = "잘 모르겠어. 난 백야성 법전에 어떤 규정이 있는지 모르니까.",
  ui_story_5045_50450601_13_dialog_content = "제가 처음에 당신을 조수로 삼을지를 두고 티나와 경쟁했던 이유는,\n제가 반드시 공정하게 판결하도록 당신이 상기시켜 주길 바라서였습니다.",
  ui_story_5045_50450601_14_dialog_content = "그러니 하고 싶은 말이 있다면, 담아 두지 말고 꼭 이야기해 주십시오.",
  ui_story_5045_50450601_15_dialog_content = "음... 난 레인 씨가 이번 사건에 내린 판결이...",
  ui_story_5045_50450601_16_option_content = "아주 공정했다고 생각해.",
  ui_story_5045_50450601_17_dialog_content = "위로해 주셔서 감사합니다.\n그렇지만 저도 은연중에 문제가 조금 있다는 걸 느꼈습니다.",
  ui_story_5045_50450601_18_dialog_content = "아무래도 연애 지부의 사건들은 제 생각보다 더 복잡할 것 같군요.",
  ui_story_5045_50450601_19_option_content = "좀 매정했다고 생각해.",
  ui_story_5045_50450601_20_dialog_content = "확실히 법의 구속력은 두 사람이 계약을 이행하게 만들 순 있어.\n하지만 사람의 마음은 법으로 어쩔 수 있는 게 아니잖아.",
  ui_story_5045_50450601_21_dialog_content = "그렇게 해서 결국 결혼을 한다 해도, 두 사람의 삶은 즐겁지 않았을 거야.",
  ui_story_5045_50450601_22_dialog_content = "아, 미안... 난 레인 씨 판결이 잘못됐다고 하려던 건 아니야...",
  ui_story_5045_50450601_23_dialog_content = "사과하지 마십시오.\n혼란스럽던 제게 길을 제시해 주셨으니, 오히려 제가 감사해야 하는걸요.",
  ui_story_5045_50450601_24_option_content = "어땠는지 딱히 별생각 없어.",
  ui_story_5045_50450601_25_dialog_content = "별 생각이 안 들다니요?",
  ui_story_5045_50450601_26_dialog_content = "그게 가장 안 좋은 겁니다.",
  ui_story_5045_50450601_27_dialog_content = "음, 하지만 당신에게 제 모든 희망을 거는 것도 역시 옳은 일은 아니겠죠.",
  ui_story_5045_50450601_28_dialog_content = "(레인 씨 눈빛에서 나한테 실망했다는 게 느껴지는 것 같은데...)",
  ui_story_5045_50450601_29_dialog_content = "(그냥 내 생각을 사실대로 말할 걸 그랬나...)",
  ui_story_5045_50450601_30_dialog_content = "아무래도 우린 이 사건에 조금 더 힘을 내 봐야 할 것 같습니다.",
  ui_story_5045_50450601_31_dialog_content = "가시죠.",
  ui_story_5045_50450601_32_dialog_content = "응? 어딜?",
  ui_story_5045_50450601_33_dialog_content = "소피 씨가 항소를 제기했습니다.",
  ui_story_5045_50450601_34_dialog_content = "우리에게 보여 줄 증거들이 있다고 하더군요.",
  ui_story_5045_50450601_35_dialog_content = "<color=#737378>시간: 오후 3시</color>",
  ui_story_5045_50450601_36_dialog_content = "<color=#737378>장소: 백야성 다운타운 구역</color>",
  ui_story_5045_50450601_37_dialog_content = "안녕하십니까, 소피 씨의 집이 이 근처가 맞습니까?",
  ui_story_5045_50450601_38_dialog_content = "실례지만 누구시죠?",
  ui_story_5045_50450601_39_dialog_content = "(이 사람, 어디서 많이 본 것 같은데...)",
  ui_story_5045_50450601_40_dialog_content = "저희는...",
  ui_story_5045_50450601_41_dialog_content = "이런, PlayerName 씨. 혹시 저희의 <color=#1875ad>신분</color>을 증명할 만한 물건이 있습니까?",
  ui_story_5045_50450601_42_dialog_content = "이거면 될까?",
  ui_story_5045_50450601_43_dialog_content = "이 물건으로 저희의 신분을 증명하긴 어려울 것 같군요.",
  ui_story_5045_50450601_44_dialog_content = "아... 그, 그래? 그럼...",
  ui_story_5045_50450601_45_dialog_content = "저희는 백야성 심판소의 심판관이에요.",
  ui_story_5045_50450601_46_dialog_content = "오늘은 소피 씨의 의견을 청취하러 왔어요.",
  ui_story_5045_50450601_47_dialog_content = "누구신가 했더니 존경하는 심판관님이셨군요!\n꼭 좀 부탁드리겠습니다. 제발 소피를 도와주세요!",
  ui_story_5045_50450601_48_dialog_content = "소피 씨와 아는 사이입니까?",
  ui_story_5045_50450601_49_dialog_content = "전 소피의 이웃입니다.\n아, 편하게 <color=#1875ad>카를</color>이라고 불러 주시면 됩니다.",
  ui_story_5045_50450601_50_dialog_content = "그동안 퍼렐이라는 기사가 자꾸 소피를 스토킹했고,\n소피는 말도 못 할 만큼 힘들어해 왔습니다.",
  ui_story_5045_50450601_51_dialog_content = "전 이웃으로서 근처에 수상한 사람이 있으면 대신 쫓아내 주곤 했죠.",
  ui_story_5045_50450601_52_dialog_content = "저희 정체에 신경을 쓰셨던 이유가 있었네요.",
  ui_story_5045_50450601_53_dialog_content = "퍼렐 씨가 계속 소피 씨를 스토킹했다는 말씀이십니까?",
  ui_story_5045_50450601_54_dialog_content = "이렇게 제가 한 기사의 명예를 훼손하는 건 좋지 못한 일이겠죠.",
  ui_story_5045_50450601_55_dialog_content = "하지만 퍼렐이 매일 소피의 집 근처를 어슬렁거린 건 사실입니다.",
  ui_story_5045_50450601_56_dialog_content = "소피는 퍼렐과 다시는 상종하고 싶지 않다는 의사를 분명히 밝혔지만,\n그 사람은 그래도 계속 치근거리더군요.",
  ui_story_5045_50450601_57_dialog_content = "계속 그대로 뒀다가는 소피에게 위험한 일이라도 생기진 않을지 걱정입니다.",
  ui_story_5045_50450601_58_dialog_content = "소피 씨가 심판소에서 퍼렐 씨의 행동을 고발했었는데,\n그게 다 사실이었다는 건가요?",
  ui_story_5045_50450601_59_dialog_content = "그렇다면 제가 내린 판결은 결국...",
  ui_story_5045_50450601_60_dialog_content = "앞으로 조금 더 가면 소피의 집이 있습니다. 제가 안내해 드리겠습니다.",
  ui_story_5045_50450601_61_dialog_content = "<color=#737378>시간: 오후 3시 20분</color>",
  ui_story_5045_50450601_62_dialog_content = "<color=#737378>장소: 백야성 다운타운 구역, 소피의 집</color>",
  ui_story_5045_50450601_63_dialog_content = "집이 누추해서 죄송합니다. 두 분께서 불편해하지 않으셨으면 좋겠네요.",
  ui_story_5045_50450601_64_dialog_content = "그럴 리가요. 집을 아주 따듯한 분위기로 꾸며 두셨는데요.\n저도 좀 배우고 싶은 정도입니다.",
  ui_story_5045_50450601_65_dialog_content = "퍼렐 씨가 계속 소피 씨를 스토킹해 왔다고 이웃 사람이 그러더군요.\n그게 정말인가요?",
  ui_story_5045_50450601_66_dialog_content = "아...",
  ui_story_5045_50450601_67_dialog_content = "예전엔 제 뒤를 밟거나, 저희 집 대문 근처를 어슬렁거리는 정도였어요.",
  ui_story_5045_50450601_68_dialog_content = "하지만 <color=#1875ad>오늘 새벽</color>엔 집 안에 이상한 <color=#1875ad>발자국</color>까지 있었어요.\n이젠 너무 무서워요...",
  ui_story_5045_50450601_69_dialog_content = "이 발자국들인가요? 확실히 이상하네요.",
  ui_story_5045_50450601_70_dialog_content = "누군가에게 들키고 싶어 안달이 난 사람처럼,\n일부러 흰 종이 위에도 발자국을 몇 개 냈어요.",
  ui_story_5045_50450601_71_dialog_content = "발뒤꿈치 쪽이 비교적 선명하게 남아 있군요.\n무늬로 봐서는 기사들이 주로 신는 부츠 같습니다.",
  ui_story_5045_50450601_72_dialog_content = "발자국은 창문 쪽에서 쭉 이어져 있군요...",
  ui_story_5045_50450601_73_dialog_content = "소피 씨가 다른 데 신경을 쓰고 있을 때를 노려서,\n퍼렐 씨가 몰래 안으로 들어온 걸까요?",
  ui_story_5045_50450601_74_dialog_content = "소피 씨, 혹시 사라진 물건은 없습니까?",
  ui_story_5045_50450601_75_dialog_content = "없어요. 도둑맞은 물건이 없어서 더 무서운 거예요!",
  ui_story_5045_50450601_76_dialog_content = "틀림없이 퍼렐이 절 겁주고 있는 거예요...\n이젠 정말 어떻게 해야 할지 모르겠어요.",
  ui_story_5045_50450601_77_dialog_content = "제가 심리를 진행할 때 소피 씨의 이야기를 더 자세히 들었어야 했습니다.",
  ui_story_5045_50450601_78_dialog_content = "심판관님 탓이 아닌걸요.",
  ui_story_5045_50450601_79_dialog_content = "전 계약서의 내용을 위반했어요. 부디 절 감옥으로 보내 주세요!",
  ui_story_5045_50450601_80_dialog_content = "자신을 통제할 수 없는 스토커랑 결혼하느니, 차라리 감옥에 가는 게 나아요...",
  ui_story_5045_50450601_81_dialog_content = "소피 씨, 안심하십시오.",
  ui_story_5045_50450601_82_dialog_content = "현재는 퍼렐 씨에게 명백한 잘못이 있는 것으로 보이는 만큼,\n이 부분을 재판에 어떻게 반영할지 다시 고민해 보겠습니다.",
  ui_story_5045_50450601_83_dialog_content = "소피 씨, 저희가 집 안을 조사해 봐도 될까요?",
  ui_story_5045_50450601_84_dialog_content = "...조사야 괜찮지만, 지금 집이 엉망인 건 이해 좀 해 주세요.",
  ui_story_5045_50450601_85_dialog_content = "크흠, 갑자기 이렇게 조사를 하면 소피 씨가 난처해 하실 겁니다.",
  ui_story_5045_50450601_86_dialog_content = "아, 미안... 그 생각은 전혀 못 했어!\n역시 레인 씨는 생각이 깊구나...",
  ui_story_5045_50450601_87_dialog_content = "그치만 기왕 여기까지 왔고, 조사를 더 해 보면 퍼렐 씨가 남긴\n다른 증거를 찾을 수 있을지도 모르잖아.",
  ui_story_5045_50450601_88_dialog_content = "누가 따지면 다 내 생각이었다고 하면 돼.",
  ui_story_5045_50450601_89_dialog_content = "어떻게 당신 한 사람에게만 책임을 묻게 할 수 있겠습니까?",
  ui_story_5045_50450601_90_dialog_content = "조사가 끝나면 제가 당신 대신 소피 씨에게 사과하겠습니다.",
  ui_story_5045_50450601_91_dialog_content = "후훗...",
  ui_story_5045_50450601_92_dialog_content = "저기... 두 분 말씀을 일부러 엿들으려던 건 아니지만...",
  ui_story_5045_50450601_93_dialog_content = "서로 상대를 위해 책임을 지려 하시다니, 사이가 참 좋으시네요.",
  ui_story_5045_50450601_94_dialog_content = "다 절 도와주려고 하시는 일이니까 편하게 조사해 주세요. 전 괜찮아요.",
  ui_story_5045_50450601_95_dialog_content = "...이해해 주셔서 감사합니다.",
  ui_story_5045_50450601_96_dialog_content = "그럼 어딜 <color=#1875ad>조사</color>하는 게 좋겠습니까?",
  ui_story_5045_50450601_97_dialog_content = "생각 좀 해 볼게...",
  ui_story_5045_50450601_98_option_content = "서랍장을 살펴보자.",
  ui_story_5045_50450601_99_dialog_content = "고급스러워 보이는 편지들이 엄청 많아.",
  ui_story_5045_50450601_100_dialog_content = "이건 평범한 편지가 아닙니다.",
  ui_story_5045_50450601_101_dialog_content = "레인 씨가 그걸 어떻게 알아?",
  ui_story_5045_50450601_102_dialog_content = "저도 비슷한 느낌의 편지를 많이 받아 봐서 압니다...",
  ui_story_5045_50450601_103_dialog_content = "레인 씨도 많이 받아 봤다는 거면... 아하! 이거 다 러브레터구나!",
  ui_story_5045_50450601_104_dialog_content = "근데 편지의 글씨체랑 사인이 다 달라...",
  ui_story_5045_50450601_105_dialog_content = "소피 씨는 인기가 아주 많은 모양이군요.\n하지만 이건 어디까지나 소피 씨의 사적인 문제입니다.",
  ui_story_5045_50450601_106_dialog_content = "다른 곳을 살펴보는 게 좋겠습니다.",
  ui_story_5045_50450601_106X1_dialog_content = "그럼 또 어딜 조사해 볼까...",
  ui_story_5045_50450601_107_option_content = "바닥을 살펴보자.",
  ui_story_5045_50450601_108_dialog_content = "창가 쪽 말고 다른 곳에선 발자국을 찾을 수 없었어.",
  ui_story_5045_50450601_109_dialog_content = "음? 이건...",
  ui_story_5045_50450601_110_dialog_content = "카드? 무슨 <color=#1875ad>수강증</color> 같은데?",
  ui_story_5045_50450601_111_dialog_content = "아, 맞아요.\n전 교육 프로그램에 참가해서 가사 업무와 관리를 배우는 중이거든요.",
  ui_story_5045_50450601_112_dialog_content = "그 카드는 그 프로그램의 수강증이에요.",
  ui_story_5045_50450601_113_dialog_content = "부모님이 모두 돌아가시고 가세가 기운 탓에 전 가업을 이을 순 없었지만,\n그래도 인생을 대충 보내고 싶진 않아요.",
  ui_story_5045_50450601_114_dialog_content = "앞으로는 저 스스로 노력해서 살아가 보려고 해요.",
  ui_story_5045_50450601_115_dialog_content = "...분명히 해내실 수 있을 겁니다!",
  ui_story_5045_50450601_116_option_content = "딱히 더 살펴볼 곳은 없는 것 같아.",
  ui_story_5045_50450601_117_dialog_content = "발자국들만 빼면 수상해 보이는 부분도 없고.",
  ui_story_5045_50450601_118_dialog_content = "아무것도 가져가지 않고, 남겨 둔 것도 없다니...",
  ui_story_5045_50450601_119_dialog_content = "퍼렐 씨는 대체 뭘 하려던 걸까?",
  ui_story_5045_50450601_120_dialog_content = "<color=#737378>시간: 오후 5시</color>",
  ui_story_5045_50450601_121_dialog_content = "<color=#737378>장소: 백야성 호위대</color>",
  ui_story_5045_50450601_122_dialog_content = "보, 보기만 해도 무시무시한 곳이네... 진짜 퍼렐 씨가 여기서 일하는 거 맞아?",
  ui_story_5045_50450601_123_dialog_content = "용감하고 두려움을 모르는 귀족만이 이곳에서 일할 자격을 가지고 있지.",
  ui_story_5045_50450601_124_dialog_content = "베벌리?!",
  ui_story_5045_50450601_125_dialog_content = "퍼렐은 지금 외근 중이야. 다른 날에 다시 오도록 해.",
  ui_story_5045_50450601_126_dialog_content = "공작님, 저희는 지금 조사 중인 사건이 있습니다.",
  ui_story_5045_50450601_127_dialog_content = "퍼렐 씨가 공작님의 동료라고 들었습니다만...",
  ui_story_5045_50450601_128_dialog_content = "맞아, 하지만 퍼렐의 사건은 이미 판결이 내려지지 않았었나?",
  ui_story_5045_50450601_129_dialog_content = "피고가 항소를 제기해 이 사건을 재조사하기로 결정했습니다.",
  ui_story_5045_50450601_130_dialog_content = "흐음? 그런 일이 있었나.",
  ui_story_5045_50450601_131_dialog_content = "그렇지만 확실히 제대로 조사해 볼 필요는 있어.\n소피 양을 만난 뒤부터 퍼렐은 전혀 다른 사람처럼 변했으니까.",
  ui_story_5045_50450601_132_dialog_content = "거의 매일 자기 「공주님」을 구하지 않으면 기사 자격을\n잃게 될 거라고 중얼거리고 있거든.",
  ui_story_5045_50450601_133_dialog_content = "아직까지 업무에 지장을 준 적은 없지만, 그래도 더는 못 봐주겠어.",
  ui_story_5045_50450601_134_dialog_content = "진정한 기사는 모든 평민의 마음을 헤아릴 수 있어야 해.\n하지만 퍼렐은 이미 한 사람에게 마음을 빼앗기고 말았어.",
  ui_story_5045_50450601_135_dialog_content = "퍼렐 씨가 얼마 전부터 호위대에서 숙식을 해결한다는 얘기를 들었습니다만,\n그게 사실입니까?",
  ui_story_5045_50450601_136_dialog_content = "맞아. 얼마 전에 자기 전 재산을 움브라톤의 가난한 사람들에게 기부했거든.",
  ui_story_5045_50450601_137_dialog_content = "그 뒤로는 쭉 호위대에서 생활하고 있어.",
  ui_story_5045_50450601_138_dialog_content = "그 사심 없는 선행엔 나도 감탄했어.\n하지만 그게 이번 사건과 무슨 관련이 있지?",
  ui_story_5045_50450601_139_dialog_content = "재산을 전부 다?!",
  ui_story_5045_50450601_140_dialog_content = "퍼렐 씨가 지내는 곳에 저흴 데려가 주실 수 있겠습니까?",
  ui_story_5045_50450601_141_dialog_content = "바로 이 옆이니까 두 사람이 직접 들어가서 확인해 봐.",
  ui_story_5045_50450601_142_dialog_content = "<color=#737378>얼마 후</color>",
  ui_story_5045_50450601_143_dialog_content = "어때? 뭐 좀 알아냈어?",
  ui_story_5045_50450601_144_dialog_content = "발자국의 크기가 집 안에 남아 있던 신발 자국과 일치했습니다.",
  ui_story_5045_50450601_145_dialog_content = "소피 씨 집에 침입한 사람은 퍼렐 씨가 맞나 보네...",
  ui_story_5045_50450601_146_dialog_content = "PlayerName 씨도 뭔가 알아내셨습니까?",
  ui_story_5045_50450601_147_dialog_content = "방 안에 특별해 보이는 물건은 없었어. 이거 하나 빼고.",
  ui_story_5045_50450601_148_dialog_content = "이건... <color=#1875ad>연</color>이군요?",
  ui_story_5045_50450601_149_dialog_content = "위에 「소피」라고 이름도 적혀 있어.",
  ui_story_5045_50450601_150_dialog_content = "퍼렐 씨가 소피 씨의 연을 훔친 걸까요?\n왜 소피 씨는 이 일을 우리에게 알리지 않았을까요?",
  ui_story_5045_50450601_151_dialog_content = "비싼 물건이 아니라서 그런 거 아닐까?",
  ui_story_5045_50450601_152_dialog_content = "조사를 시작한 뒤로 모든 증거들이 퍼렐 씨를 지목하고 있습니다.",
  ui_story_5045_50450601_153_dialog_content = "만약 이게 모두 사실이라면, 퍼렐 씨는 승소할 수 없을 뿐만 아니라,\n더 엄중한 처벌을 받게 될 겁니다.",
  ui_story_5045_50450601_154_dialog_content = "어떤 처벌을 받는데?",
  ui_story_5045_50450601_155_dialog_content = "기사라는 신분을 잃고 평민으로 전락하게 됩니다.",
  ui_story_5045_50450601_156_dialog_content = "귀족에겐 그 무엇보다 중대한 처벌이죠.",
  ui_story_5045_50450601_157_dialog_content = "하지만 난 자꾸 이 사건엔 숨은 사정이 있는 것 같다는 느낌이 들어.",
  ui_story_5045_50450601_158_dialog_content = "동감입니다.",
  ui_story_5045_50450601_159_dialog_content = "그러니 내일 재판에서는 세세한 부분까지 빠짐없이 다뤄야만 할 겁니다.",
  ui_story_5045_50450701_1_dialog_content = "<color=#737378>시간: 오전 9시</color>",
  ui_story_5045_50450701_2_dialog_content = "<color=#737378>장소: 백야성 심판소, 소심판정</color>",
  ui_story_5045_50450701_3_dialog_content = "와! 오늘도 레인 님은 너무 멋지셔!",
  ui_story_5045_50450701_4_dialog_content = "(...레인 씨한테 푹 빠진 아가씨들이 오늘도 또 온 건가.)",
  ui_story_5045_50450701_5_dialog_content = "PlayerName 씨, 무슨 생각을 하고 계십니까?",
  ui_story_5045_50450701_6_dialog_content = "그게...",
  ui_story_5045_50450701_7_option_content = "오늘도 레인 씨는 멋지네!",
  ui_story_5045_50450701_8_dialog_content = "(으악! 실수로 아까 그 아가씨들이 한 말이랑 똑같은 소릴 해 버렸잖아...)",
  ui_story_5045_50450701_9_dialog_content = "크흠... 이제 곧 개정이니 사건에 집중해 주셨으면 좋겠군요.",
  ui_story_5045_50450701_10_option_content = "반드시 공정한 판결을 내려야 한다고 생각했어.",
  ui_story_5045_50450701_11_dialog_content = "네, 다시 한번 상기시켜주셔서 감사합니다.",
  ui_story_5045_50450701_12_dialog_content = "저번 일을 교훈 삼아, 이번엔 결코 독단적으로 결론을 내리지 않을 겁니다.",
  ui_story_5045_50450701_13_option_content = "나도 레인 씨처럼 인기가 많았으면 좋겠어.",
  ui_story_5045_50450701_14_dialog_content = "그보다는 더 숭고한 걸 바라실 줄 알았습니다만...",
  ui_story_5045_50450701_15_dialog_content = "곧 재판이 시작될 겁니다. 부디 그런 엉뚱한 생각은 삼가 주십시오!",
  ui_story_5045_50450701_16_dialog_content = "(이런 「칭찬」을 해 주면 레인 씨가 기뻐할 줄 알았는데...)",
  ui_story_5045_50450701_17_dialog_content = "<color=#737378>탕!</color>",
  ui_story_5045_50450701_18_dialog_content = "<size=45>만물은 백야 아래에, 지금부터 재판을 시작하겠습니다!</size>",
  ui_story_5045_50450701_19_dialog_content = "먼저, 항소인은 항소 취지를 진술해 주시기 바랍니다.",
  ui_story_5045_50450701_20_dialog_content = "존경하는 심판관님, 전 1심 판결을 받아들일 수 없습니다.",
  ui_story_5045_50450701_21_dialog_content = "전 피항소인 퍼렐과 맺은 계약을 취소하고 싶습니다.",
  ui_story_5045_50450701_22_dialog_content = "피항소인은 기사이면서도 자신의 직무를 사적으로 남용해\n절 미행하고 스토킹해 왔습니다.",
  ui_story_5045_50450701_23_dialog_content = "심지어는 <color=#1875ad>1심 판결이 종료된 후</color>에도 제가 사는 집에\n침입해 발자국까지 남겼습니다!",
  ui_story_5045_50450701_24_dialog_content = "(항소인의 발언엔 어딘가 문제가 있어!)",
  ui_story_5045_50450701_25_dialog_content = "그 부분에 무슨 문제라도 있습니까?",
  ui_story_5045_50450701_26_dialog_content = "어? 문제가 없나?",
  ui_story_5045_50450701_26X1_dialog_content = "제대로 못 들으신 거겠죠? 그럼 다시 한번 말씀드릴게요...",
  ui_story_5045_50450701_27_dialog_content = "레인, 이것 좀 봐...",
  ui_story_5045_50450701_28_dialog_content = "으음? 아, 정말 그리운 노트로군요.",
  ui_story_5045_50450701_29_dialog_content = "제가 견습 심판관이었을 무렵엔 저도 매일 가지고 다녔었죠.",
  ui_story_5045_50450701_30_dialog_content = "(이 대화, 어째 좀 익숙한데...?)",
  ui_story_5045_50450701_31_dialog_content = "그래서 무슨 말씀을 하시려는 겁니까?",
  ui_story_5045_50450701_32_dialog_content = "새, 생각 중이야...",
  ui_story_5045_50450701_33_dialog_content = "항소인은 발자국을 <color=#1875ad>1심 당일 새벽</color>에 발견했다고 했었던 걸로 기억하는데요?",
  ui_story_5045_50450701_34_dialog_content = "아! 제, 제가 잘못 기억하고 있었네요.",
  ui_story_5045_50450701_35_dialog_content = "심판관님, 방금 너무 긴장해서 말을 잘못한 것 같아요. 다시 말씀드릴게요!",
  ui_story_5045_50450701_36_dialog_content = "1심 당일 새벽, 전 제 집 안에서 발자국들을 발견했습니다.",
  ui_story_5045_50450701_37_dialog_content = "그렇지만 사라진 물건은 아무것도 없었고, 전 피항소인이 절 겁주기 위해\n일부러 제 집에 침입했다는 걸 알 수 있었습니다!",
  ui_story_5045_50450701_38_dialog_content = "사라진 물건이 아무것도 없었다고요? 하지만...",
  ui_story_5045_50450701_39_dialog_content = "제가 알기로 피항소인은 <color=#1875ad>항소인의 물건</color>을 하나 가지고 있던데요!",
  ui_story_5045_50450701_40_dialog_content = "그 부분에 무슨 문제라도 있습니까?",
  ui_story_5045_50450701_41_dialog_content = "아, 이게 아니지! 내가 하려던 말은 그러니까...",
  ui_story_5045_50450701_42_dialog_content = "이 <color=#1875ad>연</color>에는 항소인의 이름이 적혀 있었어요. 항소인의 물건이 맞죠?",
  ui_story_5045_50450701_43_dialog_content = "그건...",
  ui_story_5045_50450701_44_dialog_content = "심판관님, 그건 저와 항소인의 약혼 예물입니다!",
  ui_story_5045_50450701_45_dialog_content = "그때 전 순찰을 마친 직후였습니다...",
  ui_story_5045_50450701_46_dialog_content = "(음? 지금 심판소에서 연애할 때의 추억을 회상하려는 거야?)",
  ui_story_5045_50450701_47_dialog_content = "기사님...",
  ui_story_5045_50450701_48_dialog_content = "도움이 필요하십니까?",
  ui_story_5045_50450701_49_dialog_content = "저, 저기 제 연이 나무에 걸려 버려서요...\n이런 일로 기사님을 번거롭게 만들면 안 된다는 건 알지만...",
  ui_story_5045_50450701_50_dialog_content = "저 연은 돌아가신 아버지께서 직접 만들어 주신 거라서,\n저한텐 정말 소중한 물건이거든요. 그래서...",
  ui_story_5045_50450701_51_dialog_content = "번거로울리가요. 잠시만 기다려 주십시오.",
  ui_story_5045_50450701_52_dialog_content = "정말 감사해요! 기사님이 아니었다면 정말 어떻게 했을지...",
  ui_story_5045_50450701_53_dialog_content = "그리 힘든 일도 아니었으니 너무 고마워하지 않으셔도 됩니다.",
  ui_story_5045_50450701_54_dialog_content = "저, 저기... 혹시 연 날리는 거 좋아하세요?",
  ui_story_5045_50450701_55_dialog_content = "그날 이후 저희는 가끔씩 만나 연을 날렸고,\n점차 사이가 가까워지기 시작했습니다.",
  ui_story_5045_50450701_56_dialog_content = "그무렵 제 가족들은 제가 비슷한 수준의 가문 사람을\n아내로 맞길 바라고 있었습니다.",
  ui_story_5045_50450701_57_dialog_content = "그러나 전 사랑은 자유로워야 한다고 여겼고,\n가족에게 휘둘리는 결혼을 하고 싶진 않았습니다.",
  ui_story_5045_50450701_58_dialog_content = "그래서 전 가족의 뜻을 거절하고, 항소인에게 청혼했습니다.",
  ui_story_5045_50450701_59_dialog_content = "퍼렐! 우리 연이 저 높이까지 올라갔어!",
  ui_story_5045_50450701_60_dialog_content = "연은 하늘 저 높이까지 올라갈 수 있지만,\n바람이 멈추면 다시 땅으로 돌아오는 법이야.",
  ui_story_5045_50450701_61_dialog_content = "우리가 밖에서 얼마나 분주하게 돌아다닌다 해도,\n결국엔 따뜻한 집으로 돌아가야 하는 것처럼 말이야.",
  ui_story_5045_50450701_62_dialog_content = "무슨 말인지 잘 모르겠어.",
  ui_story_5045_50450701_63_dialog_content = "소피, 나와 행복한 가정을 함께 만들지 않겠어?",
  ui_story_5045_50450701_64_dialog_content = "그...그런 마음을 가져 줘서 정말 너무 고마워.",
  ui_story_5045_50450701_65_dialog_content = "하지만 지금 내 사정은 이렇게 변변치 않은데,\n퍼렐 씨 가족들이 이런 날 받아들여 주실까?",
  ui_story_5045_50450701_66_dialog_content = "소피, 걱정하지 마. 내가 다 해결할게.",
  ui_story_5045_50450701_67_dialog_content = "혹시라도 나 때문에 당신이 가족들이랑 사이가 멀어지기라도 한다면...\n내 마음이 너무 무거울 거야...",
  ui_story_5045_50450701_68_dialog_content = "청혼에 대한 대답은 「좋아요」야. 대신 나한테 시간을 조금 줘.",
  ui_story_5045_50450701_69_dialog_content = "난 우리 가문을 다시 일으키고 싶어...",
  ui_story_5045_50450701_70_dialog_content = "내가 가산을 다시 예전처럼 만든다면 퍼렐 씨 가족들도 날 받아 주시겠지.",
  ui_story_5045_50450701_71_dialog_content = "두 사람은 그래서 약혼 계약서를 작성한 거였군요!",
  ui_story_5045_50450701_72_dialog_content = "이의 있습니다! 피항소인은 사건과 무관한 과거의 일을 언급하고 있습니다.",
  ui_story_5045_50450701_73_dialog_content = "다른 사람의 연애사를 듣고 있는 건 조금 민망하긴 하지만...",
  ui_story_5045_50450701_74_dialog_content = "전 방금 그 이야기도 본 사건과 관련이 있다고 생각합니다!",
  ui_story_5045_50450701_75_dialog_content = "이의를 기각합니다!",
  ui_story_5045_50450701_76_dialog_content = "심판관님, 저와 피항소인이 한때 아름다운 사랑을 했던 건 사실입니다.\n하지만 이미 다 지나간 일입니다.",
  ui_story_5045_50450701_77_dialog_content = "전 이미 한참 전부터 피항소인에게 이별을 요구했습니다.",
  ui_story_5045_50450701_78_dialog_content = "우리에겐 사랑을 할 자유도, 사랑을 하지 않을 자유도 있습니다.",
  ui_story_5045_50450701_79_dialog_content = "한낱 계약서 한 장 때문에 자신이 남은 반평생 누릴 행복을\n포기하게 만들어서는 안 된다고 생각합니다!",
  ui_story_5045_50450701_80_dialog_content = "음, 항소인의 주장은 일리가 있습니다.",
  ui_story_5045_50450701_81_dialog_content = "하지만 피항소인은 제가 이별을 요구한 후에도 여전히 제게 집착하고 있으며,\n걸핏하면 절 미행하고 있습니다...",
  ui_story_5045_50450701_82_dialog_content = "심지어는 제가 무방비한 때를 노려, 제 집에 침입까지 했습니다!",
  ui_story_5045_50450701_83_dialog_content = "음... 항소인은 왜 그 발자국들을 피항소인이 남긴 거라고 확신하는 거지?",
  ui_story_5045_50450701_84_dialog_content = "항소인은 지금까지 피항소인에게 스토킹을 당해 왔습니다.\n그렇기 때문에 무의식적으로 피항소인의 소행이라고 여긴 건 아닐까요?",
  ui_story_5045_50450701_85_dialog_content = "...하지만 이건 제 추측에 불과합니다.\n따라서 피항소인의 말도 들어 봐야 한다고 봅니다.",
  ui_story_5045_50450701_86_dialog_content = "피항소인, 항소인의 진술 내용을 인정하십니까?",
  ui_story_5045_50450701_87_dialog_content = "전...",
  ui_story_5045_50450701_88_dialog_content = "순찰 업무를 마치고 난 다음 가끔 항소인을 만나러 간 것은 사실입니다.\n하지만 다른 의도는 없었고, 그저 피항소인의 마음을 돌리고 싶었을 뿐입니다.",
  ui_story_5045_50450701_89_dialog_content = "만물은 백야 아래에. 기사로서의 명예를 걸고 맹세합니다.\n전 피항소인에게 그 어떤 법도를 벗어난 행위도 하지 않았습니다.",
  ui_story_5045_50450701_90_dialog_content = "소피, 정말 누가 당신 집에 몰래 들어갔단 말이야?",
  ui_story_5045_50450701_91_dialog_content = "...전부 내 잘못이야. 이게 다 내가 당신을 제대로 지키지 못해서...",
  ui_story_5045_50450701_92_dialog_content = "피항소인은 현장의 발자국이 자신의 것임을 인정하지 않는다는 거군요.",
  ui_story_5045_50450701_93_dialog_content = "그게 누구 발자국인지 확인할 방법이 있으면 좋을 텐데...",
  ui_story_5045_50450701_94_dialog_content = "...그렇네요! 지금 이 심판소에서 바로 대조해 보면 되지 않겠습니까!",
  ui_story_5045_50450701_95_dialog_content = "<color=#737378>탕!</color>",
  ui_story_5045_50450701_96_dialog_content = "피항소인, 종이를 밟아서 발자국을 남겨 주시기 바랍니다.",
  ui_story_5045_50450701_97_dialog_content = "아, 알겠습니다...",
  ui_story_5045_50450701_98_dialog_content = "PlayerName 씨, 차이점을 발견하셨습니까?",
  ui_story_5045_50450701_99_dialog_content = "피항소인의 발자국은 발바닥에서 발꿈치까지 대체로 균일하게 찍혔어.",
  ui_story_5045_50450701_100_dialog_content = "게다가 밑창 테두리 쪽엔 갈라진 부분들이 많습니다.\n다시 말해서 오래된 신발이라는 뜻이겠죠.",
  ui_story_5045_50450701_101_dialog_content = "하지만 그날 우리가 찾은 <color=#1875ad>발자국</color>은...",
  ui_story_5045_50450701_102_dialog_content = "그게 무슨 문제라도 있습니까?",
  ui_story_5045_50450701_103_dialog_content = "크흠, 내가 잠깐 착각했어!",
  ui_story_5045_50450701_104_dialog_content = "항소인의 집에 남아 있던 발자국은 선명했어. 새 신발이었던 거지.\n하지만 피항소인의 신발은 헌 신발이야.",
  ui_story_5045_50450701_105_dialog_content = "찍힌 발자국도 확연히 다르고 말이야.",
  ui_story_5045_50450701_106_dialog_content = "네?!",
  ui_story_5045_50450701_107_dialog_content = "잠깐만요, 어쩌면 저 사람이 제 집에 침입했을 때\n다른 새 신발을 신고 있었을 가능성도 있잖아요?",
  ui_story_5045_50450701_108_dialog_content = "음, 그러할 가능성을 부정할 순 없습니다.",
  ui_story_5045_50450701_109_dialog_content = "심판관님, 제가 가지고 있는 신발은 이 한 켤레가 전부입니다...",
  ui_story_5045_50450701_110_dialog_content = "그 말을 어떻게 믿어? 당신이 부츠를 다른 곳에 숨겨 뒀을 수도 있잖아!",
  ui_story_5045_50450701_111_dialog_content = "아니요, 항소인의 집에 침입한 건 피항소인이 아니에요!",
  ui_story_5045_50450701_112_dialog_content = "PlayerName, 그런 결론을 내린 근거가 뭐죠?",
  ui_story_5045_50450701_113_dialog_content = "항소인의 집에 남아 있던 발자국들은... 뒤꿈치 쪽이 비교적 선명했어.",
  ui_story_5045_50450701_114_dialog_content = "그건 자기 발 크기보다 훨씬 더 커다란 신발을 신었을 때 남는 발자국이야.",
  ui_story_5045_50450701_115_dialog_content = "그러니까 항소인의 집에 발자국을 남긴 사람은 절대로 피항소인이 아니야.",
  ui_story_5045_50450701_116_dialog_content = "정말 예리한 관찰력이시군요!",
  ui_story_5045_50450701_117_dialog_content = "그렇다면 일부러 자기의 발 크기보다 큰 신발을 신고,\n항소인의 집에 발자국을 남길 만한 사람이 누가 있을까요?",
  ui_story_5045_50450701_118_dialog_content = "그건...",
  ui_story_5045_50450701_119_dialog_content = "항소인, 설마 「증거」를 남긴 사람이 항소인 본인은 아니겠죠?",
  ui_story_5045_50450701_120_dialog_content = "저, 전...",
  ui_story_5045_50450701_121_dialog_content = "만물은 백야 아래에! 심판소에서는 진실만을 말해야 합니다!",
  ui_story_5045_50450701_122_dialog_content = "...전 1심 판결이 그대로 확정될까 걱정됐어요.\n그래서 이런 현명하지 못한 짓을 꾸민 거예요.",
  ui_story_5045_50450701_123_dialog_content = "심판관님, 제가 잘못했어요.\n하지만 전 진심으로 저 사람과 결혼하고 싶지 않아요!",
  ui_story_5045_50450701_124_dialog_content = "그건 이제 피항소인에게 남은 재산이 없기 때문인가요?",
  ui_story_5045_50450701_125_dialog_content = "......",
  ui_story_5045_50450701_126_dialog_content = "피항소인이 명확히 진술하진 않았지만, 두 사람의 계약서엔\n「쌍방의 경제력이 거의 동등해졌을 때」 결혼한다고 적혀 있었죠.",
  ui_story_5045_50450701_127_dialog_content = "그렇지만 지금은...",
  ui_story_5045_50450701_128_dialog_content = "피항소인의 <color=#1875ad>자산 현황</color>이 계약서 작성 당시와는 아주 많이 달라졌어요.",
  ui_story_5045_50450701_129_dialog_content = "이게 뭡니까?",
  ui_story_5045_50450701_130_dialog_content = "아, 그, 그러니까...",
  ui_story_5045_50450701_131_dialog_content = "피항소인, 본인 명의의 모든 재산을 기부한 이유를 설명해 주실 수 있습니까?",
  ui_story_5045_50450701_132_dialog_content = "그, 그건 기사된 자로서의 책임을 다하기 위해서였습니다.",
  ui_story_5045_50450701_133_dialog_content = "정말 그 이유 때문인가요?",
  ui_story_5045_50450701_134_dialog_content = "만물은 백야 아래에!\n피항소인은 기사로서 정직함이야말로 기사의 기본 소양이라는\n점을 잘 알고 있으리라 믿습니다.",
  ui_story_5045_50450701_135_dialog_content = "윽...",
  ui_story_5045_50450701_136_dialog_content = "알겠습니다. 말씀드리죠.",
  ui_story_5045_50450701_137_dialog_content = "미안해. 또 투자에 실패해 버렸어...",
  ui_story_5045_50450701_138_dialog_content = "하지만 이번엔 달라!",
  ui_story_5045_50450701_139_dialog_content = "퍼렐, 한 번만 더 도와주면 안 될까? 이번엔 꼭 성공할 거야!",
  ui_story_5045_50450701_140_dialog_content = "소피, 좋은 소식을 하나 알려주고 싶어.",
  ui_story_5045_50450701_141_dialog_content = "난 내 재산을 전부 기부했어.",
  ui_story_5045_50450701_142_dialog_content = "왜... 그런 거야?",
  ui_story_5045_50450701_143_dialog_content = "그렇게 하면 우리 둘의 경제력이 같아질 수 있잖아.",
  ui_story_5045_50450701_144_dialog_content = "이제 우린 결혼할 수 있어.",
  ui_story_5045_50450701_145_dialog_content = "항소인은 오랫동안 여러 시도를 했지만, 가문의 재산을 복구하진 못했습니다.",
  ui_story_5045_50450701_146_dialog_content = "그렇지만 전 항소인이 그렇게 힘들어하는 모습은 보고 싶지 않았습니다.",
  ui_story_5045_50450701_147_dialog_content = "돈은 물질일 뿐입니다. 연인 사이에 사랑보다 더 중요한 게 뭐가 있겠습니까!",
  ui_story_5045_50450701_148_dialog_content = "분명한 건 항소인은 그렇게 생각하지 않았다는 거군요.",
  ui_story_5045_50450701_149_dialog_content = "...네, 전 피항소인과는 생각이 달랐습니다.",
  ui_story_5045_50450701_150_dialog_content = "전 가족을 이루기 위해서는 돈이라는 전제 조건이 충족돼야 한다고 생각해요.",
  ui_story_5045_50450701_151_dialog_content = "그래서 전 저 사람의 행동에 공감할 수 없었고,\n서로 가치관이 안 맞는 것 같아서 헤어지자고 한 거예요.",
  ui_story_5045_50450701_152_dialog_content = "그게 무슨 문제라도 되나요?",
  ui_story_5045_50450701_153_dialog_content = "결혼하고 나서 같이 노력해서 천천히 우리 재산을 쌓아도 되잖아!",
  ui_story_5045_50450701_154_dialog_content = "하지만 난 이미 당신을 사랑하지 않아.",
  ui_story_5045_50450701_155_dialog_content = "아니, 처음부터 사랑한 적 없었어.",
  ui_story_5045_50450701_156_dialog_content = "이제 만족해?",
  ui_story_5045_50450701_157_dialog_content = "소피... 아니지? ...거짓말이라고 해 줘!",
  ui_story_5045_50450701_158_dialog_content = "불쌍한 퍼렐 씨...",
  ui_story_5045_50450701_159_dialog_content = "레인, 이번엔 어떤 판결을 내릴 거야?",
  ui_story_5045_50450701_160_dialog_content = "전 한때 모든 사건은 법 조항을 근거로 판결을 내릴 수 있다고 생각했습니다.",
  ui_story_5045_50450701_161_dialog_content = "하지만 연예 지부의 사건은 다르군요...",
  ui_story_5045_50450701_162_dialog_content = "감정이란 건 말로 설명하기엔 너무나도 복잡하고 미묘한 거니까.",
  ui_story_5045_50450701_163_dialog_content = "이대로 가면 두 사람에겐 상처만 남을 거야.",
  ui_story_5045_50450701_164_dialog_content = "부디 우리의 판결이 두 사람을 지켜줄 수 있었으면 좋겠군요.",
  ui_story_5045_50450701_165_dialog_content = "그럼 이미 결론을 내린 거야?",
  ui_story_5045_50450701_166_dialog_content = "네.",
  ui_story_5045_50450701_167_dialog_content = "<color=#737378>탕!</color>",
  ui_story_5045_50450701_168_dialog_content = "만물은 백야 아래에, 지금부터 판결을 선고하겠습니다!",
  ui_story_5045_50450701_169_dialog_content = "먼저, 피항소인 퍼렐과 항소인 소피의 약혼 계약은 적법하며, 유효합니다...",
  ui_story_5045_50450701_170_dialog_content = "하지만 심리 결과 항소인은 이미 피항소인과 관계를\n더는 유지할 수 없음을 확인했습니다.",
  ui_story_5045_50450701_171_dialog_content = "또한, 피항소인이 자신을 스토킹하였다는 항소인의 주장은 사실이 아니며,\n피항소인이 항소인을 미행하거나 거소에 무단 침입한 사실이 없습니다.",
  ui_story_5045_50450701_172_dialog_content = "그러나 일방적인 애정만으로는 원만한 혼인 관계가 성립될 수 없습니다.",
  ui_story_5045_50450701_173_dialog_content = "이에 따라 다음과 같이 판결을 선고합니다!",
  ui_story_5045_50450701_174_dialog_content = "주문. 항소인 소피는 피항소인 퍼렐에게 사과하라.",
  ui_story_5045_50450701_175_dialog_content = "또한, 약혼 취소 사유, 피항소인의 불법 침임이 사실이 아님을 소상히 밝힌다.",
  ui_story_5045_50450701_176_dialog_content = "피항소인 퍼렐은 본 판결의 확정일부터 사적으로 항소인과 접촉할 수 없으며,\n호위대는 이에 대한 내부 감독을 실시한다.",
  ui_story_5045_50450701_177_dialog_content = "<color=#737378>탕!</color>",
  ui_story_5045_50450701_178_dialog_content = "이상으로 재판을 마치겠습니다!",
  ui_story_5045_50450801_1_dialog_content = "<color=#737378>시간: 정오 12시</color>",
  ui_story_5045_50450801_2_dialog_content = "<color=#737378>장소: 백야성 심판소, 소심판정</color>",
  ui_story_5045_50450801_3_dialog_content = "심판관님, 저 대신 소피에게 이걸 전해주실 수 있겠습니까?",
  ui_story_5045_50450801_4_dialog_content = "소피와 함께 다시 연을 날리러 갈 날이 다시 올 줄 알았는데...",
  ui_story_5045_50450801_5_dialog_content = "이젠 불가능한 일이 된 것 같군요.",
  ui_story_5045_50450801_6_dialog_content = "기념으로 가지고 있을까도 생각해 봤습니다만...",
  ui_story_5045_50450801_7_dialog_content = "소피의 아버님께서 생전에 직접 만들어 주신 물건이니,\n저보다는 소피에게 더 필요할 겁니다.",
  ui_story_5045_50450801_8_dialog_content = "안심하십시오. 저희가 꼭 소피 씨에게 전해드리겠습니다.",
  ui_story_5045_50450801_9_dialog_content = "앞으로는 분명히 진정한 사랑을 찾으실 수 있을 겁니다.",
  ui_story_5045_50450801_10_dialog_content = "소피에게 이 말도 전해주시면 감사하겠습니다. 기다리겠다고요.",
  ui_story_5045_50450801_11_dialog_content = "...알겠어요. 이제 가서 좀 쉬세요.",
  ui_story_5045_50450801_12_dialog_content = "휴...",
  ui_story_5045_50450801_13_dialog_content = "소피 씨! 잠시만 기다려 주세요!",
  ui_story_5045_50450801_14_dialog_content = "또 무슨 일 있나요?",
  ui_story_5045_50450801_15_dialog_content = "퍼렐 씨에게 이 연을 전해 달라는 부탁을 받았습니다.",
  ui_story_5045_50450801_16_dialog_content = "이젠 필요 없어요. 그냥 버려 주세요.",
  ui_story_5045_50450801_17_dialog_content = "하지만 이 연은 소피 씨의 아버님께서 직접 만드신 게 아닙니까?",
  ui_story_5045_50450801_18_dialog_content = "...우리 아버지가 만든 연은 아주 많아요. 그러니까 그건 필요 없어요.",
  ui_story_5045_50450801_19_dialog_content = "심판관님께서 그런 일까지 신경 쓰셔야 하는 건가요?",
  ui_story_5045_50450801_20_dialog_content = "......",
  ui_story_5045_50450801_21_dialog_content = "소피 씨한테 마지막으로 물어보고 싶은 게 하나 있어요.",
  ui_story_5045_50450801_22_dialog_content = "그거라면 딱히 드릴 말씀은 없을 것 같네요.",
  ui_story_5045_50450801_23_dialog_content = "다른 사람의 감정도 이런 식으로 속였던 건가요?",
  ui_story_5045_50450801_24_dialog_content = "「속이다」니요? 어떻게 저와 그 사람들의 관계를 그렇게 표현하실 수 있죠?",
  ui_story_5045_50450801_25_dialog_content = "우리가 심판소에 소피 씨의 주변인을 조사해 달라고 하면...",
  ui_story_5045_50450801_26_dialog_content = "소피 씨 문제가 생각만큼 그렇게 단순하진 않다는 게 드러날지도 모르죠.",
  ui_story_5045_50450801_27_dialog_content = "...그 사람들 중엔 저한테 소송을 건 사람도 없잖아요.\n아무리 심판관이라도 이런 식으로 사람을 괴롭히면 안 되죠!",
  ui_story_5045_50450801_28_dialog_content = "확실히 그 사람들은 고소를 안 했겠죠.",
  ui_story_5045_50450801_29_dialog_content = "당신이 목표로 삼은 건 모두 사회적 지위가 꽤 있는 귀족들이었으니까요.",
  ui_story_5045_50450801_30_dialog_content = "그러니 속았다는 걸 알아도 남에게 알려지고 싶어 하지 않을 거예요.",
  ui_story_5045_50450801_31_dialog_content = "그런데 퍼렐 씨가 저렇게 진심일 거라곤 당신도 예상 못 했겠죠.",
  ui_story_5045_50450801_32_dialog_content = "하지만 당신은 끝까지 퍼렐 씨한테 진실을 밝히지 않았어요.",
  ui_story_5045_50450801_33_dialog_content = "퍼렐 씨가 당신을 위해 가진 모든 걸 포기한 걸 알고서도 말이죠...",
  ui_story_5045_50450801_34_dialog_content = "그만 좀 하세요!",
  ui_story_5045_50450801_35_dialog_content = "시간을 너무 많이 허비했네요. 미안하지만 먼저 가 볼게요.",
  ui_story_5045_50450801_36_dialog_content = "그냥 이렇게 휙 가 버리다니...",
  ui_story_5045_50450801_37_dialog_content = "퍼렐 씨에게 반드시 이 연을 전해 주겠다고 약속했는데...",
  ui_story_5045_50450801_38_dialog_content = "역시 연애 지부의 사건은 정말 어려운 것 같습니다.",
  ui_story_5045_50450801_39_dialog_content = "재판이 끝났는데도 마음이 좀처럼 가벼워지질 않는군요.",
  ui_story_5045_50450801_40_dialog_content = "그러게. 이상하게 마음이 무거워.",
  ui_story_5045_50450801_41_option_content = "퍼렐 씨가 우릴 원망하진 않았으면 좋겠는데...",
  ui_story_5045_50450801_42_dialog_content = "우리가 할 수 있는 일은 이미 다 했습니다.\n앞으로의 문제는 법도 우리에게 답을 주진 못할 겁니다.",
  ui_story_5045_50450801_43_dialog_content = "휴, 이런 생각은 그만하고 얼른 돌아가자!",
  ui_story_5045_50450801_44_dialog_content = "그러죠. 차라리 다음 사건에 집중하는 편이 좋겠습니다!",
  ui_story_5045_50450801_45_dialog_content = "어쩌면 이제 우리 사이의 <color=#1875ad>팀워크</color>가 더 좋아져서,\n다음 사건이 아무리 복잡해도 쉽게 해결할 수 있을지도 모릅니다!",
  ui_story_5045_50450801_46_dialog_content = "뭐어?!",
  ui_story_5045_50450801_47_dialog_content = "난 그냥...",
  ui_story_5045_50450801_48_dialog_content = "돌아가서 좀 쉬고 싶단 말이야!",
  ui_story_5045_50450801_49_option_content = "그래도 레인 씨는 최선을 다했잖아!",
  ui_story_5045_50450801_50_dialog_content = "난 이게 최선의 결과였다고 생각해.",
  ui_story_5045_50450801_51_dialog_content = "정말로 그랬으면 좋겠습니다.",
  ui_story_5045_50450801_52_dialog_content = "그러지 말고 우리도 좀 돌아다니면서 쉬자.",
  ui_story_5045_50450801_53_dialog_content = "몸을 조금 움직이면 마음도 한결 나아질 테니까.",
  ui_story_5045_50450801_54_dialog_content = "네, 그렇게 하죠.",
  ui_story_5045_50450801_55_dialog_content = "오늘은 마침 날씨도...",
  ui_story_5045_50450801_56_dialog_content = "<color=#737378>휘이잉──</color>",
  ui_story_5045_50450801_57_dialog_content = "바람이 너무 센데? 날아가 버리는 줄 알았잖아.",
  ui_story_5045_50450801_58_dialog_content = "그래도 연은 내가 손에 잘... 어? 연이 어디 갔지?!",
  ui_story_5045_50450801_59_dialog_content = "저쪽입니다!",
  ui_story_5045_50450801_60_dialog_content = "<color=#737378>휘이잉──</color>",
  ui_story_5045_50450801_61_dialog_content = "(레인 씨?)",
  ui_story_5045_50450801_62_dialog_content = "(우와, 어떻게 순식간에 하늘로 붕 날아서 연을 잡은 거지?!)",
  ui_story_5045_50450801_63_dialog_content = "(잠깐만...)",
  ui_story_5045_50450801_64_dialog_content = "(이거 왠지... 뭔가 익숙한 클리셰 같은데?)",
  ui_story_5045_50450801_65_dialog_content = "(아!)",
  ui_story_5045_50450801_66_dialog_content = "(퍼렐 씨가 소피 씨를 처음 만났을 때도 이런 상황이었을 거잖아...)",
  ui_story_5045_50450801_67_dialog_content = "이 연은 정말이지 도망치는 걸 참 좋아하는군요.",
  ui_story_5045_50450801_68_dialog_content = "아니면 그저 바람을 타고 자유로워지고 싶은 것뿐일까요?",
  ui_story_5045_50450801_69_dialog_content = "(그것도 그렇네. 연은 바람이 있어야만 저 푸른 하늘로 날아오를 수 있잖아.)",
  ui_story_5045_50450801_70_dialog_content = "(왜 우린 꼭 줄을 가지고 연의 자유를 억압하려고 드는 걸까?)",
  ui_story_5045_50450801_71_dialog_content = "PlayerName 씨, 지금 무슨 생각을 하고 계시는지 압니다.",
  ui_story_5045_50450801_72_dialog_content = "하지만 전 제약이 없는 자유는 진정한 자유가 아니라고 생각합니다.",
  ui_story_5045_50450801_73_dialog_content = "줄에 묶이지 않은 연은 얼마 지나지 않아 바람에 휩쓸려서,\n황량한 불모지로 날아가 버리게 됩니다.",
  ui_story_5045_50450801_74_dialog_content = "최근 백야성에는 자유연애의 열풍이 불고 있습니다.\n마치 저 연이 하늘로 날아오르는 걸 갈망하는 것처럼 말이죠.",
  ui_story_5045_50450801_75_dialog_content = "만약 공정함을 상징하는 줄이 연을 이끌어 주지 않는다면...",
  ui_story_5045_50450801_76_dialog_content = "사랑을 할 자유도, 하지 않을 자유도, 그 어떤 것도 보장받지 못할 겁니다.",
  ui_story_5045_50450801_77_dialog_content = "크흠... 역시 레인 씨답다니까.",
  ui_story_5045_50450801_78_dialog_content = "그냥 연 하나 날리는 건데도 그렇게 대단한 이치를 깨달았잖아.",
  ui_story_5045_50450801_79_dialog_content = "아, 죄송합니다.",
  ui_story_5045_50450801_80_dialog_content = "제 시답잖은 이야기에 마음 쓰지 말아 주십시오!",
  ui_story_5045_50450801_81_dialog_content = "전 그저... 이번 사건 심리를 마치고 나니, 앞으로 연애 지부의 다른 사건들을\n어떻게 대해야 할지 조금 이해하게 된 것 같아서 그랬을 뿐입니다.",
  ui_story_5045_50450801_82_dialog_content = "물론 이 모든 게 당신의 도움 덕분입니다.",
  ui_story_5045_50450801_83_option_content = "천만에!",
  ui_story_5045_50450801_84_dialog_content = "사실 대부분 일은 전부 레인 씨가 직접 한 거잖아.",
  ui_story_5045_50450801_85_dialog_content = "난 그냥 옆에서 비전문가의 조언을 조금 했을 뿐인걸.",
  ui_story_5045_50450801_86_dialog_content = "정말 겸손하시군요.",
  ui_story_5045_50450801_87_dialog_content = "하지만 당신이 없었다면, 전 이 첫 사건의 심리도 끝을 볼 수 없었을 겁니다.",
  ui_story_5045_50450801_88_option_content = "혹시 아직도 무슨 고민 있어?",
  ui_story_5045_50450801_89_dialog_content = "역시 PlayerName 씨는 못 속이겠군요.",
  ui_story_5045_50450801_90_dialog_content = "실은... 차라리 이 세상에 사랑이라는 건 없는 게 낫지 않을까...\n그런 생각을 하고 있었습니다.",
  ui_story_5045_50450801_91_dialog_content = "뭐? 연애 지부에서 일하기 싫어진 거야?",
  ui_story_5045_50450801_92_dialog_content = "그, 그건 아닙니다. 이런 기회가 제게 주어져서 무척 감사한 마음입니다.",
  ui_story_5045_50450801_93_dialog_content = "전 그저... 보면 볼수록 사랑은 「독」 같다는 생각이 듭니다.",
  ui_story_5045_50450801_94_dialog_content = "늠름했던 한 명의 기사가 순식간에 그런 구차한 모습이 되다니 말입니다...",
  ui_story_5045_50450801_95_dialog_content = "사랑이라는 건 확실히 이해하기 어려운 것 같아.\n하지만 난 사건 때문에 색안경을 끼고 사랑을 대해선 안 된다고 생각해.",
  ui_story_5045_50450801_96_dialog_content = "이 세상엔 진정한 행복이 가득한 사랑이 훨씬 더 많을 테니까.",
  ui_story_5045_50450801_97_dialog_content = "레인 씨가 지금까지 그런 사랑을 보지 못한 건,\n아마 그런 행복한 연인들은 심판소에 올 일이 없으니까 그런 거 아니겠어?",
  ui_story_5045_50450801_98_dialog_content = "진정한 행복이 가득한 사랑이라... 그런 사랑은 어떤 느낌일까요?",
  ui_story_5045_50450801_99_dialog_content = "두 사람이 서로를 긍정적으로 바라봐 주고, 서로를 믿고,\n상대를 위해 더 나은 사람이 되려고 노력하는 거라고 생각해.",
  ui_story_5045_50450801_100_dialog_content = "아마 그런 게 바로 진짜로 아름다운 사랑 아닐까?",
  ui_story_5045_50450801_101_dialog_content = "그렇습니까...",
  ui_story_5045_50450801_102_dialog_content = "갑자기 또 뭘 그렇게 골똘하게 생각하는데?",
  ui_story_5045_50450801_103_dialog_content = "그런 말을 들으니 갑자기 누군가가 떠올랐습니다.",
  ui_story_5045_50450801_104_dialog_content = "누구? 나도 아는 사람이야?",
  ui_story_5045_50450801_105_dialog_content = "PlayerName 씨, 바로 당신입니다.",
  ui_story_5045_50450801_106_dialog_content = "뭐어어어어어?!",
  ui_story_5045_50450801_107_dialog_content = "이제 보니 연인 사이의 사랑과 파트너 사이의 우정도 비슷한 점이 참 많군요.",
  ui_story_5045_50450801_108_dialog_content = "그, 그것도 그렇긴 하지. 하하하...",
  ui_story_5045_50450801_109_dialog_content = "그렇다면 저도 모두의 사랑을 축복해 줘야 마땅하겠지요.",
  ui_story_5045_50450801_110_dialog_content = "만물은 백야 아래에.\n모든 연인의 사랑이 오래도록 행복하기를.",
  ui_story_5045_50450801_111_dialog_content = "그나저나 이제 이 연은 어떡하지?",
  ui_story_5045_50450801_112_dialog_content = "우리가 잠시 맡아 두도록 하죠.",
  ui_story_5045_50450801_113_dialog_content = "<color=#737378>휘이잉──</color>",
  ui_story_5045_50450801_114_dialog_content = "아, 또 바람이 부는데? 이번엔 연을 잘 잡고 있어야지...",
  ui_story_5045_50450801_115_dialog_content = "차라리 다시 한번 하늘을 날 수 있게 해 주는 게 어떻습니까?",
  ui_story_5045_50450801_116_dialog_content = "뭐?",
  ui_story_5045_50450801_117_dialog_content = "PlayerName 씨, 연 날릴 줄 아십니까?",
  ui_story_5045_50450901_1_dialog_content = "<color=#737378>시간: 오후 3시</color>",
  ui_story_5045_50450901_2_dialog_content = "<color=#737378>장소: 백야성 심판소, 연애 지부 사무실</color>",
  ui_story_5045_50450901_3_dialog_content = "(사건 심리가 이렇게 빨리 끝날 줄은 몰랐네.)",
  ui_story_5045_50450901_4_dialog_content = "(설마 내 감응 능력보다 심판관으로서의 재능이 더 뛰어난 건 아니겠지?)",
  ui_story_5045_50450901_5_dialog_content = "(우리가 일하는 모습을 이리돈 씨가 봤다면, 보수를 좀 더 올려줄지도 몰라.)",
  ui_story_5045_50450901_6_dialog_content = "(그러면... 헤헤, 바이스랑 카렌한테 깜짝 선물도 사 줄 수 있겠네!)",
  ui_story_5045_50450901_7_dialog_content = "(그나저나...)",
  ui_story_5045_50450901_8_dialog_content = "오늘은 왜 소장을 내러 온 사람들이 전보다 더 많아진 거지?!",
  ui_story_5045_50450901_9_dialog_content = "어머? 벌써 심판소 업무에 흥미를 잃은 건가요?",
  ui_story_5045_50450901_10_dialog_content = "아, 아니에요!",
  ui_story_5045_50450901_11_dialog_content = "어이쿠, 공사가 다망하신 이리돈 님께서 무슨 일로 여기까지 행차하신 겁니까?",
  ui_story_5045_50450901_12_dialog_content = "휴우우... 후우... Zzz...",
  ui_story_5045_50450901_13_dialog_content = "티나, 어서 일어나세요!",
  ui_story_5045_50450901_14_dialog_content = "으으음...",
  ui_story_5045_50450901_15_dialog_content = "안젤, 가만히 뭐 하고 있는 거지?\n어서 가서 존경하는 대심판관님께 차라도 좀 내와.",
  ui_story_5045_50450901_16_dialog_content = "...네.",
  ui_story_5045_50450901_17_dialog_content = "번거롭게 그럴 거 없어요.",
  ui_story_5045_50450901_18_dialog_content = "여러분이 아침에 사건 하나를 심리했다고 들었어요.\n그래서 상황을 좀 보러 온 거예요.",
  ui_story_5045_50450901_19_dialog_content = "아, 그 사건 말씀이십니까? 그저 규정대로 적당히 심리했더군요.",
  ui_story_5045_50450901_20_dialog_content = "오히려 내일 제가 맡을 심리는 모든 이를 깜짝 놀라게 만들고,\n후대의 귀감으로 남을 판례가 될 겁니다.",
  ui_story_5045_50450901_21_dialog_content = "그러니 그때 다시 시찰을 나오시는 것도 좋을 것 같습니다만.",
  ui_story_5045_50450901_22_dialog_content = "그 이야기는 나중에 하기로 해요. 제가 내일 시간이 난다면 말이죠.",
  ui_story_5045_50450901_23_dialog_content = "아침의 그 사건이 지금 세간의 화제가 됐다고 하더군요.\n무슨 일이 있었던 거죠?",
  ui_story_5045_50450901_24_dialog_content = "이리돈 님, 오전의 사건은 저와 PlayerName 씨가 심리를 진행했습니다.",
  ui_story_5045_50450901_25_dialog_content = "상세한 쟁점과 재판 과정은 모두 여기 기록해 뒀어요. 한번 보실래요?",
  ui_story_5045_50450901_26_dialog_content = "좋군요. PlayerName 씨.\n업무를 시작한 지 얼마 안 됐는데, 벌써 좋은 습관이 생겼네요.",
  ui_story_5045_50450901_27_dialog_content = "방금 오늘 사건이 세간의 화제가 되었다고 하셨습니까?",
  ui_story_5045_50450901_28_dialog_content = "그래요.",
  ui_story_5045_50450901_29_dialog_content = "여론이 어떻습니까?",
  ui_story_5045_50450901_30_dialog_content = "당신은 어떨 거라 생각하죠?",
  ui_story_5045_50450901_31_dialog_content = "음... 좋지 않겠습니까?",
  ui_story_5045_50450901_32_dialog_content = "대심판관님께서 친히 파견해 주신 훌륭한 조수도 있으니 말입니다.",
  ui_story_5045_50450901_33_dialog_content = "PlayerName의 도움이 있었으니, 레인 심판관도 조금은 공부가 됐겠죠.",
  ui_story_5045_50450901_34_dialog_content = "어쩌면 이제 곧 레인 심판관이 이 연애 지부에서\n두 번째로 우수한 심판관이 될지도 모르겠군요!",
  ui_story_5045_50450901_35_dialog_content = "레인 심판관, PlayerName 씨의 기록은 빠짐없이 잘 이루어졌나요?",
  ui_story_5045_50450901_36_dialog_content = "네, 상세하게 잘 기록돼 있었습니다.",
  ui_story_5045_50450901_37_dialog_content = "...수박 겉핥기식 조사에, 사건 당사자들에게 충분한 해명의 기회도 주지 않다니...",
  ui_story_5045_50450901_38_dialog_content = "당신이 지금까지 담당했던 사건들은 이렇게 허술하지 않았던 것 같은데요.",
  ui_story_5045_50450901_39_dialog_content = "연애 지부의 사건은 저희가 기존에 맡아 온 사건들과는 달랐습니다.",
  ui_story_5045_50450901_40_dialog_content = "저 역시 이런 유형의 사건을 더 적절하게 심리할 방법을 모색하는 중입니다.",
  ui_story_5045_50450901_41_dialog_content = "연애 지부는 이제 막 세워졌으니까, 참고할 판례도 없었겠죠.",
  ui_story_5045_50450901_42_dialog_content = "여러분 모두 중압감을 느끼고 있으리란 것도 이해해요.",
  ui_story_5045_50450901_43_dialog_content = "하지만 우리에겐 사소해 보이는 사건일지라도,\n당사자들에겐 인생이 걸린 문제일 수 있다는 점을 항상 명심하세요.",
  ui_story_5045_50450901_44_dialog_content = "여러분이 맡은 사건을 어떻게 처리하느냐에 따라,\n향후 백야성의 백성들이 사랑을 대하는 태도도 달라지게 돼요.",
  ui_story_5045_50450901_45_dialog_content = "아무래도 오늘 아침 사건에 대한 여론이 그다지 좋지 않은 모양이군요...",
  ui_story_5045_50450901_46_dialog_content = "오늘 판결은 사람들에게 「약혼 계약을 파기해도 그 대가는 미미하다」는\n잘못된 메시지를 주고 말았어요.",
  ui_story_5045_50450901_47_dialog_content = "따라서 앞으로는 약혼 계약을 일방적으로 파기하겠다는\n소장이 더 많이 들어올 수 있어요.",
  ui_story_5045_50450901_48_dialog_content = "다들 마음의 준비를 단단히 해 두도록 하세요.",
  ui_story_5045_50450901_49_dialog_content = "레인 씨의 첫 재판 때문에 오히려 업무가 더 늘어날 거란 얘긴가요?",
  ui_story_5045_50450901_50_dialog_content = "그래도 같은 유형의 사건이라면 빠르게 처리할 수 있을 겁니다.",
  ui_story_5045_50450901_51_dialog_content = "그래? 그럼 앞으로 이런 사건은 다 레인과 PlayerName에게 맡기면 되겠군.",
  ui_story_5045_50450901_52_dialog_content = "어? 하지만 이 소장들...",
  ui_story_5045_50450901_53_dialog_content = "이걸 다 보려면 야근을 얼마나 해야 하는 거야?!",
  ui_story_5045_50451001_1_dialog_content = "<color=#737378>시간: 오후 2시</color>",
  ui_story_5045_50451001_2_dialog_content = "<color=#737378>장소: 백야성 심판소, 연애 지부 사무실</color>",
  ui_story_5045_50451001_3_dialog_content = "하아암~",
  ui_story_5045_50451001_4_dialog_content = "어라? PlayerName 씨, 왜 절 그렇게 유심히 쳐다보시는 거죠?",
  ui_story_5045_50451001_5_dialog_content = "방금 너 진짜로 자고 있던 거 맞아?",
  ui_story_5045_50451001_6_dialog_content = "그럼요.",
  ui_story_5045_50451001_7_dialog_content = "근데 막 신나서 웃었잖아...",
  ui_story_5045_50451001_8_dialog_content = "그러고 보니까 방금 좋은 꿈을 꾸긴 했어요. 헤헤헷~",
  ui_story_5045_50451001_9_dialog_content = "크흠... 아무튼 깼으면 됐어.",
  ui_story_5045_50451001_10_dialog_content = "사실 뭘 어떻게 도와줘야 할지 아직 잘 모르겠거든.",
  ui_story_5045_50451001_11_dialog_content = "티나가 자고 있을 때, 소장을 내러 온 사람 몇 명을 상대하긴 했어.",
  ui_story_5045_50451001_12_dialog_content = "소장을 제출했다구요?",
  ui_story_5045_50451001_13_dialog_content = "어디 좀 볼까요...",
  ui_story_5045_50451001_14_dialog_content = "음, 도와줘서 고마워요, PlayerName 씨.\n하지만 이 소장들은 연애 지부 관할이 아니네요.",
  ui_story_5045_50451001_15_dialog_content = "그, 그래? 미안, 내가 괜한 일만 만들어 버렸네...",
  ui_story_5045_50451001_16_dialog_content = "그런 생각하지 말아요.",
  ui_story_5045_50451001_17_dialog_content = "제가 깨어 있을 때 이야기했어야 했는데,\n그러지 않았으니까 따지자면 제가 잘못한 거예요.",
  ui_story_5045_50451001_18_dialog_content = "걱정하지 마세요.\n전 매일 남들보다 퇴근은 늦게 하지만, 업무 효율은 무척 높거든요.",
  ui_story_5045_50451001_19_dialog_content = "그럼 이따가 저만의 업무 처리 비결을 전수해 드릴게요.",
  ui_story_5045_50451001_20_dialog_content = "오, 그래 주면 고맙지! 그럼 빨리 시작하자!",
  ui_story_5045_50451001_21_dialog_content = "그렇게 서두를 거 없어요. 그 전에 제가 질문을 하나 할 테니까 대답해 주세요.",
  ui_story_5045_50451001_22_dialog_content = "언젠가 사랑하는 사람을 만나게 된다면,\n당신이 먼저 그 사람한테 고백하실 건가요?",
  ui_story_5045_50451001_23_option_content = "응, 내가 먼저 고백할 거야.",
  ui_story_5045_50451001_24_dialog_content = "그 사람을 향한 사랑에 확신이 있다면,\n분명히 상대에게 그 마음을 알리고 싶을 테니까.",
  ui_story_5045_50451001_25_dialog_content = "사랑이라는 감정을 존중하려면 그 마음을 전해야 하는 거잖아.\n설령 거절당한다 해도 말이야.",
  ui_story_5045_50451001_26_dialog_content = "PlayerName 씨가 그런 생각을 가지고 계실 줄은 몰랐네요.",
  ui_story_5045_50451001_27_dialog_content = "앞으로 제가 사랑하게 될 사람도 당신 같았으면 좋겠네요. 헤헷.",
  ui_story_5045_50451001_28_option_content = "아니, 먼저 고백하진 않을 거야.",
  ui_story_5045_50451001_29_dialog_content = "상대가 날 좋아하지 않는다면, 내 고백이 그 사람한텐 상처가 될 수도 있잖아.",
  ui_story_5045_50451001_30_dialog_content = "그러니까 아마 난 경솔하게 내 마음을 전하진 않을 것 같아.",
  ui_story_5045_50451001_31_dialog_content = "헤헷, PlayerName 씨는 역시 제 생각대로 부끄럼쟁이시네요.",
  ui_story_5045_50451001_32_option_content = "잘 모르겠어.",
  ui_story_5045_50451001_33_dialog_content = "지금의 난 미래의 내가 어떤 생각을 할지 알 수 없으니까.",
  ui_story_5045_50451001_34_dialog_content = "그때가 돼 봐야 어떨지 알 수 있을 것 같아.",
  ui_story_5045_50451001_35_dialog_content = "후후, 시시한 답변인걸요.",
  ui_story_5045_50451001_36_dialog_content = "근데 갑자기 그런 건 왜 물어본 거야?",
  ui_story_5045_50451001_37_dialog_content = "우리 업무랑 전혀 상관없는 것 같은데.",
  ui_story_5045_50451001_38_dialog_content = "상관이 없긴요. 당연히 있죠.",
  ui_story_5045_50451001_39_dialog_content = "우리가 어느 지부 소속이죠?",
  ui_story_5045_50451001_40_dialog_content = "연애 지부지.",
  ui_story_5045_50451001_41_dialog_content = "바로 그렇기 때문에 사랑이라는 주제를 더 깊이 탐구할 필요가 있는 거예요.",
  ui_story_5045_50451001_42_dialog_content = "게다가 동료와 연애에 대한 이야기를 나누다 보면,\n사이가 빨리 가까워질 수 있을 거예요.",
  ui_story_5045_50451001_43_dialog_content = "우리가 같이 일하는 동안 즐겁게 협력할 수 있었으면 해서 물어봤던 거예요.",
  ui_story_5045_50451001_44_dialog_content = "그랬구나. 그럼...",
  ui_story_5045_50451001_45_dialog_content = "티나는 그런 상황이 되면 어떻게 할 건데?",
  ui_story_5045_50451001_46_dialog_content = "아하하... 똑같이 반격을 당할 줄은 몰랐네요.\n좋아요, 그럼 당신한테만 살짝 알려드릴게요.",
  ui_story_5045_50451001_47_dialog_content = "절대로 제 쪽에서 먼저 고백하진 않을 거예요. 전 요조숙녀니까요.",
  ui_story_5045_50451001_48_dialog_content = "뭔가 한다면... 아마 그 사람과 마주칠 기회를 살며시 더 늘리겠죠.",
  ui_story_5045_50451001_49_dialog_content = "근데 상대랑 별로 만나지도 않고 이야기도 거의 안 해 본다면,\n그 사람이 네가 좋아하는 타입인지 어떻게 알 수 있어?",
  ui_story_5045_50451001_50_dialog_content = "만약 그 사람이 내 운명의 상대가 아니면 어떡해?",
  ui_story_5045_50451001_51_dialog_content = "그런 생각은 전혀 못 했네요...",
  ui_story_5045_50451001_52_dialog_content = "역시 PlayerName 씨는 레인 씨보다 아는 게 더 많군요!",
  ui_story_5045_50451001_53_dialog_content = "도와달라고 하길 정말 잘한 것 같아요. 앞으로도 잘 부탁해요~",
  ui_story_5045_50451001_54_dialog_content = "그럼 오늘은 일단 소장 접수, 소장 심사, 관련 법률 조항 조사를 도와주시고...",
  ui_story_5045_50451001_55_dialog_content = "사건의 자세한 정보를 정리해서 제게 주시면 돼요~",
  ui_story_5045_50451001_56_dialog_content = "그, 그럼 모든 일을 다 나보고 하라는 거 아냐?",
  ui_story_5045_50451001_57_dialog_content = "전 심판관석에 앉아서 최종 판결을 내려야 하는걸요.\n그게 제일 힘들고 중요한 부분이에요.",
  ui_story_5045_50451001_58_dialog_content = "최종 판결에 관심이 많은 모양이네요? 그럼 이번엔 같이 진행하도록 해요.",
  ui_story_5045_50451001_59_dialog_content = "<size=32>티나가 추가로 보수를 주기로 해서 정말 다행이야...</size>",
  ui_story_5045_50451001_60_dialog_content = "네? 방금 뭐라고 하셨죠?",
  ui_story_5045_50451001_61_dialog_content = "아니, 그러니까... 소장이 이렇게 많은데, 어떤 것부터 시작해야 좋을까?",
  ui_story_5045_50451001_62_dialog_content = "뭘 골라도 비슷할 테니까 굳이 고민에 시간을 쓸 필요는 없어요. 하아아암~",
  ui_story_5045_50451001_63_dialog_content = "지금 손에 들고 있는 그 소장으로 하면 될 것 같네요.",
  ui_story_5045_50451001_64_dialog_content = "「원고 <color=#1875ad>베이컨</color>과 피고 파니의 혼인 관계에 대한 이혼의 소를 청구한다...」?",
  ui_story_5045_50451001_65_dialog_content = "자, 그럼 시작하죠!",
  ui_story_5045_50451001_66_dialog_content = "Zzz... Zzz...",
  ui_story_5045_50451001_67_dialog_content = "대체 업무랑 낮잠 중에서 뭘 시작하자는 건지...",
  ui_story_5045_50451101_1_dialog_content = "<color=#737378>시간: 오전 9시</color>",
  ui_story_5045_50451101_2_dialog_content = "<color=#737378>장소: 백야성 심판소, 소심판정</color>",
  ui_story_5045_50451101_3_dialog_content = "PlayerName 씨, 오늘 심리할 사건이 어떤 사건인지 기억하시나요?",
  ui_story_5045_50451101_4_dialog_content = "응! 원고 <color=#1875ad>베이컨</color>과 피고 <color=#1875ad>파니</color>의...",
  ui_story_5045_50451101_5_option_content = "이혼 분쟁에 관한 건이야!",
  ui_story_5045_50451101_6_dialog_content = "맞아요. 개정 전에 했던 단기 집중 훈련이 효과가 있었나 보네요.",
  ui_story_5045_50451101_7_dialog_content = "얼마 안 있으면 혼자서도 재판을 거뜬히 해내겠는걸요.",
  ui_story_5045_50451101_8_option_content = "파혼 분쟁에 관한 건이야!",
  ui_story_5045_50451101_9_dialog_content = "어머, 개정 전에 했던 단기 집중 훈련이 별 효과가 없었나 보네요.",
  ui_story_5045_50451101_10_dialog_content = "개정 전에 관련 서류의 내용을 검토하고 기억하는 건 기본 중의 기본이에요.",
  ui_story_5045_50451101_11_dialog_content = "그럼 지금부터 진행될 재판에서 많이 보고, 듣고, 배우도록 하세요.",
  ui_story_5045_50451101_12_dialog_content = "아, 확실히 서류에 「이혼 분쟁에 관한 건」이라고 적혀 있었어!",
  ui_story_5045_50451101_13_dialog_content = "그런 간단한 질문 하나도 제대로 대답하지 못하다니...",
  ui_story_5045_50451101_14_dialog_content = "<color=#737378>탕!</color>",
  ui_story_5045_50451101_15_dialog_content = "<size=45>만물은 백야 아래에, 지금부터 재판을 시작하겠습니다!</size>",
  ui_story_5045_50451101_16_dialog_content = "만물은 백야 아래에!",
  ui_story_5045_50451101_17_dialog_content = "(방청객이 엄청 많잖아?! 요즘 연애 지부가 다루는 사건이\n많이 주목받고 있다더니 정말인가 보네.)",
  ui_story_5045_50451101_18_dialog_content = "먼저, 원고의 의견 진술을 청취하겠습니다.",
  ui_story_5045_50451101_19_dialog_content = "시, 심판관님, 저는 베이컨이라고 합니다.",
  ui_story_5045_50451101_20_dialog_content = "원고가 왜 저렇게 겁에 질려 있지?",
  ui_story_5045_50451101_21_dialog_content = "원고, 긴장하거나 무서워할 필요 없어요.",
  ui_story_5045_50451101_22_dialog_content = "심판소는 백야성에서 가장 공정하고 안전한 곳이에요.",
  ui_story_5045_50451101_23_dialog_content = "마음 편히 진술하세요.",
  ui_story_5045_50451101_24_dialog_content = "저, 전 제 아내인 피고 파니와 이혼을 원합니다.",
  ui_story_5045_50451101_25_dialog_content = "당신, 꼭 이렇게까지 해야겠어?",
  ui_story_5045_50451101_26_dialog_content = "이...일단 내 이야기부터 끝까지 들어줄 순 없을까?",
  ui_story_5045_50451101_27_dialog_content = "<color=#737378>탕!</color>",
  ui_story_5045_50451101_28_dialog_content = "피고는 원고의 발언을 끊지 마세요.",
  ui_story_5045_50451101_29_dialog_content = "......",
  ui_story_5045_50451101_30_dialog_content = "원고, 이혼을 청구하는 원인을 설명해 주시겠어요?",
  ui_story_5045_50451101_31_dialog_content = "그건 서...성격 차이 때문입니다!",
  ui_story_5045_50451101_32_dialog_content = "원고와 피고의 혼인지속기간이 어떻게 되죠?",
  ui_story_5045_50451101_33_dialog_content = "7년입니다.",
  ui_story_5045_50451101_34_dialog_content = "그동안엔 제가 생계를 유지할 수 있는 직업을 가지고 있어서,\n저와 원고의 생활 역시 나쁘지 않은 편이었습니다.",
  ui_story_5045_50451101_35_dialog_content = "하지만 제가 작년에 갑자기 해고를 당하면서 수입원을 잃게 되었습니다.",
  ui_story_5045_50451101_36_dialog_content = "그 뒤로 피고는 매일 집에서 제게 불평불만을 늘어놓았고,\n제가 직업이 없는 것을 무척 싫어했습니다.",
  ui_story_5045_50451101_37_dialog_content = "그제서야 전 두 사람 사이에 사랑이라는 감정은 이미\n세월과 함께 사라져 버렸다는 사실을 깨달았습니다.",
  ui_story_5045_50451101_38_dialog_content = "이제 서로의 눈에 보이는 건 그저 서로의 단점뿐이었습니다.",
  ui_story_5045_50451101_39_dialog_content = "전 이런 혼인 관계 속에서 세월을 헛되이 보내고 싶지 않습니다.\n피고와 갈라서서 자유로운 사람이 되고 싶습니다.",
  ui_story_5045_50451101_40_dialog_content = "즉, 원고는 두 사람의 혼인 관계가 이미 파탄에 이르렀다고 주장하는 거군요.",
  ui_story_5045_50451101_41_dialog_content = "피고는 원고의 진술에 동의하시나요?",
  ui_story_5045_50451101_42_dialog_content = "심판관님, 전 동의할 수 없습니다.",
  ui_story_5045_50451101_43_dialog_content = "원고는 고용주로부터 해고당한 뒤부터 의기소침하게 변해 버렸습니다.",
  ui_story_5045_50451101_44_dialog_content = "전 원고가 지금의 어려움을 극복하고 다시 일어나길 바라는 마음에\n계속 원고에게 대화를 하거나 산책을 나가자고 했던 거예요.",
  ui_story_5045_50451101_45_dialog_content = "전 단 한 번도 원고와 헤어지고 싶다는 생각을 해 본 적 없습니다.",
  ui_story_5045_50451101_46_dialog_content = "물론 원고가 실직하고 나서는 저 혼자 일을 해서 생활비를 벌다 보니\n불평을 조금 했을지도 모릅니다.",
  ui_story_5045_50451101_47_dialog_content = "그렇지만 그때...",
  ui_story_5045_50451101_48_dialog_content = "아무튼! 제가 잘못한 부분이 있다면 고칠 거예요!",
  ui_story_5045_50451101_49_dialog_content = "(파니 씨가 방금 뭔가 말하려다가 갑자기 <color=#1875ad>말을 바꾼 것</color> 같은데?)",
  ui_story_5045_50451101_50_dialog_content = "저와 원고 사이에 있었던 일은 이게 전부입니다.",
  ui_story_5045_50451101_51_dialog_content = "그런가요?",
  ui_story_5045_50451101_52_dialog_content = "아무래도 원고가 오랜 시간 직업 없이 시간을 보냈더니,\n감정이 쉽게 격해지게 된 것 같아요.",
  ui_story_5045_50451101_53_dialog_content = "그래서 갑자기 욱하는 마음으로 이혼을 청구한 거라고 생각해요.",
  ui_story_5045_50451101_54_dialog_content = "하지만 전 원고가 점차 나아질 것이라고 믿어요.",
  ui_story_5045_50451101_55_dialog_content = "그러니 무슨 일이 있어도 전 원고와 이혼하지 않을 거예요!",
  ui_story_5045_50451101_56_dialog_content = "그랬군요.",
  ui_story_5045_50451101_57_dialog_content = "그렇다면... 하아아암~",
  ui_story_5045_50451101_58_dialog_content = "티나, 지금은 재판 중이야! 절대 잠들면 안 돼!",
  ui_story_5045_50451101_59_dialog_content = "어머... 앗!",
  ui_story_5045_50451101_60_dialog_content = "고마워요, PlayerName 씨. 덕분에 망신을 면했네요...",
  ui_story_5045_50451101_61_dialog_content = "크흠, 심리 과정이 꽤 어려운 걸 보니,\n역시 PlayerName 씨가 선택한 사건답네요.",
  ui_story_5045_50451101_62_dialog_content = "백야성에 자유연애 열풍이 분 뒤로부터, 이혼 소송도 확실히 증가했어요.",
  ui_story_5045_50451101_63_dialog_content = "이혼 청구를 인용할지 기각할지는 줄곧 우리 연애 지부에서\n검토해야 하는 사안이었죠.",
  ui_story_5045_50451101_64_dialog_content = "PlayerName 씨, 당신은 이번 사건에 대해...",
  ui_story_5045_50451101_65_dialog_content = "어떻게 생각하시나요?",
  ui_story_5045_50451101_66_dialog_content = "보아하니 그다지 유용한 정보는 찾지 못한 모양이네요.",
  ui_story_5045_50451101_67_dialog_content = "이, 이 단서는 어떨까?",
  ui_story_5045_50451101_67X1_dialog_content = "그 외에는...",
  ui_story_5045_50451101_68_dialog_content = "아... 왠지 알 것 같아!",
  ui_story_5045_50451101_69_dialog_content = "티나, 이것 좀 봐!",
  ui_story_5045_50451101_70_dialog_content = "잘했어요. 제가 말하지 않아도 알아서 원고와 피고의 발언을 기록해 뒀군요.",
  ui_story_5045_50451101_71_dialog_content = "당신이 제 조수가 돼 줘서 덕분에 걱정도, 수고도 많이 덜었네요.",
  ui_story_5045_50451101_72_dialog_content = "하지만 기록에만 정신이 팔려 있으면 안 돼요!",
  ui_story_5045_50451101_73_dialog_content = "이번 사건에 대해...",
  ui_story_5045_50451101_74_dialog_content = "난 원고가 설명한 이혼 사유가 너무 제멋대로라고 생각해.",
  ui_story_5045_50451101_75_dialog_content = "하지만 원고가 이미 말했잖아요.\n자신은 두 사람 사이에서 더는 애정을 느낄 수 없다고 말이에요.",
  ui_story_5045_50451101_76_dialog_content = "애정이 없는 결혼은 상상조차 힘든 일이에요.",
  ui_story_5045_50451101_77_dialog_content = "하지만 피고도 해명했잖아.\n자긴 원고를 달래주려고 그랬던 것뿐이라고 말이야.",
  ui_story_5045_50451101_78_dialog_content = "게다가 난 원고가 다시 일어설 수 있도록 돕겠다는 피고의 결의를 느꼈어.",
  ui_story_5045_50451101_79_dialog_content = "그것도 그렇네요. 원고는 지금 직업도 없고, 의기소침한 상태죠...",
  ui_story_5045_50451101_80_dialog_content = "그런데도 피고는 그런 상황에 불만을 품지 않고,\n원고를 곁에서 도우려고 하고 있어요.",
  ui_story_5045_50451101_81_dialog_content = "부부 사이의 이런 마음은 실로 백야성의 귀감이라 할 수 있어요!",
  ui_story_5045_50451101_82_dialog_content = "만약 원고가 순간적으로 감정이 격해져서 벌인 일을 가지고\n쌍방의 이혼을 인용한다면...",
  ui_story_5045_50451101_83_dialog_content = "빛의 신께서 제 애정운을 전부 없애버리지 않으실까요?",
  ui_story_5045_50451101_84_dialog_content = "<color=#737378>탕!</color>",
  ui_story_5045_50451101_85_dialog_content = "만물은 백야 아래에, 지금부터 판결을 선고하겠습니다!",
  ui_story_5045_50451101_86_dialog_content = "본 심판소의 심리 결과, 원고와 피고의 혼인 관계는\n파탄에 이르지 않았다고 판단됩니다.",
  ui_story_5045_50451101_87_dialog_content = "빛의 신께서 증인이 되어 주신 혼인은 이처럼 경솔하게\n부정되어서는 안 됩니다.",
  ui_story_5045_50451101_88_dialog_content = "따라서 원고가 청구한 이혼의 소를 기각합니다.\n부디 두 사람이 관계를 회복하고 혼인 관계를 원만히 지속하길 바랍니다.",
  ui_story_5045_50451101_89_dialog_content = "<color=#737378>탕!</color>",
  ui_story_5045_50451101_90_dialog_content = "이상으로 재판을 마치겠습니다!",
  ui_story_5045_50451101_91_dialog_content = "방금 피고의 진술은 확실히 동정심이 드는 내용이긴 했어.",
  ui_story_5045_50451101_92_dialog_content = "하지만 난 왠지 피고가 의도적으로 뭔가를 숨기고 있다는 느낌이 들어.",
  ui_story_5045_50451101_93_dialog_content = "역시 PlayerName 씨는 무척 예리한 관찰력을 가지고 있네요.",
  ui_story_5045_50451101_94_dialog_content = "그럼 피고가 대체 뭘 숨기고 있는 건지 한번 확인해 보기로 해요.",
  ui_story_5045_50451101_95_dialog_content = "<color=#737378>탕!</color>",
  ui_story_5045_50451101_96_dialog_content = "만물은 백야 아래에.\n피고는 모든 사정을 숨김 없이 사실 그대로 진술했나요?",
  ui_story_5045_50451101_97_dialog_content = "수, 숨긴 건 아마 없을 텐데요...",
  ui_story_5045_50451101_98_dialog_content = "당신이 입을 못 열겠다면... 내가 말하겠어!",
  ui_story_5045_50451101_99_dialog_content = "심판관님, 피고는 지금 저희 수중에 돈이 얼마 없다는\n사실을 잘 알면서도 고액의 채무를 졌습니다.",
  ui_story_5045_50451101_100_dialog_content = "그것도 당신을 위해서였다고 내가 저번에 말했잖아.",
  ui_story_5045_50451101_101_dialog_content = "날 위해서라고?",
  ui_story_5045_50451101_102_dialog_content = "내 의견을... 물어보긴 했어?",
  ui_story_5045_50451101_103_dialog_content = "그게... 난 그저...",
  ui_story_5045_50451101_104_dialog_content = "피고, 피고가 원고 모르게 채무를 졌다는 원고의 진술이 사실인가요?",
  ui_story_5045_50451101_105_dialog_content = "...사실입니다.",
  ui_story_5045_50451101_106_dialog_content = "심판관님, 전 혼인 관계에서 절 기망한 사람과 함께 살 수 없습니다.",
  ui_story_5045_50451101_107_dialog_content = "부디 저와 피고의 이혼을 인용해 주십시오.",
  ui_story_5045_50451101_108_dialog_content = "다만, 재산 분할 문제는 피고와 제가 별도로 협의할 수 있었으면 합니다.",
  ui_story_5045_50451101_109_dialog_content = "피고, 원고의 요구에 동의하시나요?",
  ui_story_5045_50451101_110_dialog_content = "휴, 이제 와서 제가 뭐라고 할 수 있겠어요...",
  ui_story_5045_50451101_111_dialog_content = "...원고의 요구에 동의합니다.",
  ui_story_5045_50451101_112_dialog_content = "<color=#737378>탕!</color>",
  ui_story_5045_50451101_113_dialog_content = "만물은 백야 아래에, 지금부터 판결을 선고하겠습니다!",
  ui_story_5045_50451101_114_dialog_content = "원고와 피고는 혼인 관계를 유지할 수 없을 정도로 파탄에 이르렀습니다.\n따라서 본 심판소는 원고가 제기한 이혼 청구를 인용하겠습니다.",
  ui_story_5045_50451101_115_dialog_content = "원고와 피고의 재산 분할은 쌍방의 요구에 따라\n본 재판상이 아닌 개별 협의를 통해 결정합니다.",
  ui_story_5045_50451101_116_dialog_content = "또한 공증인이 되는 심판관의 입회하에 재산 분할 협의서를 작성하세요.",
  ui_story_5045_50451101_117_dialog_content = "이 판결에 불복하는 경우, 심판소의 규정에 따라 항소할 수 있습니다.",
  ui_story_5045_50451101_118_dialog_content = "<color=#737378>탕!</color>",
  ui_story_5045_50451101_119_dialog_content = "이상으로 재판을 마치겠습니다!",
  ui_story_5045_50451201_1_dialog_content = "<color=#737378>시간: 오전 11시</color>",
  ui_story_5045_50451201_2_dialog_content = "<color=#737378>장소: 백야성 심판소, 소심판정</color>",
  ui_story_5045_50451201_3_dialog_content = "으, 티나는 나만 보내 놓고도 안심이 되는 걸까...",
  ui_story_5045_50451201_4_dialog_content = "오후 2시 전까지는 별일이 없다면 깨우지 말아 주세요.",
  ui_story_5045_50451201_5_dialog_content = "근데 그럼 베이컨 씨랑 파니 씨의 재산 분할 협의는...",
  ui_story_5045_50451201_6_dialog_content = "옆에서 양측이 협의에 이의가 없는지 확인하고,\n마지막엔 두 사람한테 사인하라고 하면 돼요.",
  ui_story_5045_50451201_7_dialog_content = "당신이라면 분명히 잘 하...아아아암~",
  ui_story_5045_50451201_8_dialog_content = "휴우우... 후우... Zzz...",
  ui_story_5045_50451201_9_dialog_content = "야! 잠드는 게 빨라도 너무 빠르잖아?!",
  ui_story_5045_50451201_10_dialog_content = "아무튼 협의서에 서명도 이제 끝냈네. 별일 없이 끝나서 다행이야.",
  ui_story_5045_50451201_11_dialog_content = "어라?!",
  ui_story_5045_50451201_12_dialog_content = "심판관님...",
  ui_story_5045_50451201_13_dialog_content = "파니 씨? 무슨 일로 다시 오셨죠?",
  ui_story_5045_50451201_14_dialog_content = "<color=#737378>시간: 오후 2시</color>",
  ui_story_5045_50451201_15_dialog_content = "<color=#737378>장소: 백야성 심판소, 연애 지부 사무실</color>",
  ui_story_5045_50451201_16_dialog_content = "하~암.",
  ui_story_5045_50451201_17_dialog_content = "PlayerName 씨, 왜 표정이 그렇게 심각해요?",
  ui_story_5045_50451201_18_dialog_content = "드디어 일어났구나...",
  ui_story_5045_50451201_19_dialog_content = "오전에 베이컨 씨랑 파니 씨가 협의서를 작성하고 서명도 끝냈어.",
  ui_story_5045_50451201_20_dialog_content = "근데 얼마 뒤에 파니 씨가 협의서를 가지고 와서는 항소했어.",
  ui_story_5045_50451201_21_dialog_content = "네? 재산 분할 내용에 불만이 있었던 건가요?",
  ui_story_5045_50451201_22_dialog_content = "그렇다고 할 순 있겠지만, 일이 그렇게 간단하진 않은 것 같아.",
  ui_story_5045_50451201_23_dialog_content = "두 사람이 작성한 협의서를 한 번 읽어 봐.",
  ui_story_5045_50451201_24_dialog_content = "「부부의 재산은 모두 파니의 소유로 하며, 모든 채무는 베이컨이 승계한다」?",
  ui_story_5045_50451201_25_dialog_content = "파니 씨가... 베이컨 씨를 압박해서 이런 내용을 적게 만든 걸까요?",
  ui_story_5045_50451201_26_dialog_content = "정 반대야. 그건 베이컨 씨가 적은 거야.\n파니 씨는 이혼 때문에 충격이 너무 컸는지 재산 분할엔 관심도 없었거든.",
  ui_story_5045_50451201_27_dialog_content = "그러다 서명하고 난 다음에야 협의서의 내용이 이렇다는 걸 발견한 거야.",
  ui_story_5045_50451201_28_dialog_content = "베이컨 씨는 왜 이런 내용을 적은 걸까요?\n재판 때는 그렇게나 파니 씨를 싫어했으면서 말이에요.",
  ui_story_5045_50451201_29_dialog_content = "어쨌든 파니 씨는 베이컨 씨가 아직 자기를 사랑하고,\n이 협의서가 그 증거라면서 항소를 제기했어...",
  ui_story_5045_50451201_30_dialog_content = "이혼 판결을 취소해 달래.",
  ui_story_5045_50451201_31_dialog_content = "제가 내린 판결이... 틀렸던 걸까요?",
  ui_story_5045_50451201_32_option_content = "자신을 탓하긴 너무 일러.",
  ui_story_5045_50451201_33_dialog_content = "당사자들이 심판소에서 모든 사실을 얘기하지 않았을 수도 있잖아.",
  ui_story_5045_50451201_34_dialog_content = "티나는 그 상황에서 내릴 수 있는 가장 합당한 판결을 내린 거야.",
  ui_story_5045_50451201_35_dialog_content = "그러니까 지금부턴 이 사건의 진실을 파헤치고, 재심 준비만 잘하면 돼!",
  ui_story_5045_50451201_36_dialog_content = "...마지막엔 당신에게 위로를 받게 될 줄은 몰랐네요.",
  ui_story_5045_50451201_37_dialog_content = "그래도 고마워요, PlayerName 씨.",
  ui_story_5045_50451201_38_dialog_content = "하지만 전 어엿한 심판관이라구요~ 이런 일로 기죽거나 하진 않아요.",
  ui_story_5045_50451201_39_option_content = "아직은 알 수 없어.",
  ui_story_5045_50451201_40_dialog_content = "확실히 베이컨 씨의 재산 분할 협의서 내용은\n「관계가 파탄」 났다고 했던 진술과 모순돼.",
  ui_story_5045_50451201_41_dialog_content = "우린 아직 두 사람 사이에 무슨 일이 있었던 건지 몰라,\n그러니까 이 사건을 판단하기 어려운 거지.",
  ui_story_5045_50451201_42_dialog_content = "맞아요. 이 사건을 제대로 심리하려면 우린 두 사람 사이에\n대체 어떤 일들이 있었는지부터 확실히 파악해야 해요.",
  ui_story_5045_50451201_43_option_content = "틀렸을 수도 있지.",
  ui_story_5045_50451201_44_dialog_content = "그게 아니라면 지금 같은 일이 왜 벌어진 건지 설명할 수 없을 테니까.",
  ui_story_5045_50451201_45_dialog_content = "그런가요...",
  ui_story_5045_50451201_46_dialog_content = "하지만 우린 심판관으로서 사실에 근거해서 판단을 내려야 해요.",
  ui_story_5045_50451201_47_dialog_content = "근데 어떻게 해야 두 사람 사이에 무슨 일이 있었는지 알아낼 수 있을까?",
  ui_story_5045_50451201_48_dialog_content = "일단 가죠!",
  ui_story_5045_50451201_49_dialog_content = "응? 어딜?",
  ui_story_5045_50451201_50_dialog_content = "두 사람의 집에 가서 무슨 일이 있었던 건지 조사해 봐야죠.",
  ui_story_5045_50451201_51_dialog_content = "서두르세요. 2시간 안에 조사를 끝마치지 못하면...",
  ui_story_5045_50451201_52_dialog_content = "절 업고 돌아와야 할 테니까요.",
  ui_story_5045_50451201_53_dialog_content = "그, 그럼 서두르자!",
  ui_story_5045_50451201_54_dialog_content = "<color=#737378>시간: 오후 2시 30분</color>",
  ui_story_5045_50451201_55_dialog_content = "<color=#737378>장소: 백야성 다운타운 구역</color>",
  ui_story_5045_50451201_56_dialog_content = "이 앞이 바로 베이컨 씨와 파니 씨의 집이에요.",
  ui_story_5045_50451201_57_dialog_content = "어? 집 앞에 어떤 남자가 서 있는데?",
  ui_story_5045_50451201_58_dialog_content = "(왠지 어디서 많이 본 사람 같단 말이지...)",
  ui_story_5045_50451201_59_dialog_content = "......",
  ui_story_5045_50451201_60_dialog_content = "안녕하세요. 혹시 베이컨 씨, 피나 씨와 아는 사이신가요?",
  ui_story_5045_50451201_61_dialog_content = "실례지만 누구시죠...?",
  ui_story_5045_50451201_62_dialog_content = "저희는 심판소에서 나온 사람들이에요.",
  ui_story_5045_50451201_63_dialog_content = "PlayerName 씨, 저희의 <color=#1875ad>신분</color>을 증명할 물건을 제시해 주세요.",
  ui_story_5045_50451201_64_dialog_content = "이거면 될까?",
  ui_story_5045_50451201_65_dialog_content = "이거 말고 다른 거요.",
  ui_story_5045_50451201_66_dialog_content = "아... 그, 그래? 그럼...",
  ui_story_5045_50451201_67_dialog_content = "아, 심판관님들이셨군요. 방금 전엔 제가 실례를 범했군요.",
  ui_story_5045_50451201_68_dialog_content = "전 베이컨 부부의 친구인 <color=#1875ad>카를</color>이라고 합니다.",
  ui_story_5045_50451201_69_dialog_content = "베이컨을 만나러 왔는데, 지금은 집에 파니밖에 없더군요.",
  ui_story_5045_50451201_70_dialog_content = "(이 사람은 두 사람이 이혼 소송 중인 걸 아직 모르나?)",
  ui_story_5045_50451201_71_dialog_content = "그럼 한 가지만 좀 여쭤볼게요.\n카를 씨가 보시기에 베이컨 씨와 파니 씨는 평소 사이가 어땠나요?",
  ui_story_5045_50451201_72_dialog_content = "...혹시 두 사람이 무슨 불법적인 일을 저질렀습니까?",
  ui_story_5045_50451201_73_dialog_content = "아뇨, 두 사람은 지금 이...",
  ui_story_5045_50451201_74_dialog_content = "......",
  ui_story_5045_50451201_75_dialog_content = "<size=32>크흠, 이번 사건이 저 사람의 판단에 영향을 주게 해선 안 돼요.</size>",
  ui_story_5045_50451201_76_dialog_content = "사실 이번에 저흰 백야성의 결혼 생활 행복지수를 조사하러 나왔거든요.",
  ui_story_5045_50451201_77_dialog_content = "그러니까 솔직하게 대답해 주시면 돼요.",
  ui_story_5045_50451201_78_dialog_content = "그랬군요. 베이컨과 파니는 항상 금슬 좋은 부부였습니다.\n주변에도 모범적인 부부로 널리 알려져 있었죠.",
  ui_story_5045_50451201_79_dialog_content = "그런데 요즘 베이컨 씨 부부 사이에 뭔가 문제가 생겨서\n자주 다툰다는 이야기를 들었는데, 그게 사실인가요?",
  ui_story_5045_50451201_80_dialog_content = "하하, 그 둘은 백야성이 하늘에서 떨어진다 해도 절대 안 싸울 사람들입니다.",
  ui_story_5045_50451201_81_dialog_content = "그런가요...",
  ui_story_5045_50451201_82_dialog_content = "<color=#737378>시간: 오후 3시</color>",
  ui_story_5045_50451201_83_dialog_content = "<color=#737378>장소: 백야성 다운타운 구역, 베이컨과 파니 부부의 집</color>",
  ui_story_5045_50451201_84_dialog_content = "실례합니다, 계신가요?",
  ui_story_5045_50451201_85_dialog_content = "심판관님들이 여긴 무슨 일로 오신 거죠?",
  ui_story_5045_50451201_86_dialog_content = "파니 씨가 제출하신 항소장은 잘 접수했어요.\n그리고 저희의 1심 판결 과정에 다소 미흡한 점이 있었음을 확인했어요.",
  ui_story_5045_50451201_87_dialog_content = "그래서 자세한 상황을 알아보려고 두 분을 만나러 온 거예요.",
  ui_story_5045_50451201_88_dialog_content = "남편은... 이따가 자기 짐을 가지러 오겠다고 했었어요.",
  ui_story_5045_50451201_89_dialog_content = "아무튼 두 분 다 얼른 들어오세요...",
  ui_story_5045_50451201_90_dialog_content = "바닥에...",
  ui_story_5045_50451201_91_dialog_content = "죄송해요. 겨를이 없어서 미처 치우질 못했네요...",
  ui_story_5045_50451201_92_dialog_content = "왜 <color=#1875ad>접시</color>가...",
  ui_story_5045_50451201_93_dialog_content = "제가 그런 거예요! 어쩌다 보니 실수로 깨 버렸어요.",
  ui_story_5045_50451201_94_dialog_content = "어쩌다 실수로 깨진 걸로는 안 보이는데요?",
  ui_story_5045_50451201_95_dialog_content = "파니 씨, 저희가 찾아온 건 이번 사건의 진상을 명확하게 밝히기 위해서예요.",
  ui_story_5045_50451201_96_dialog_content = "만약 이번에도 저희한테 뭔가 숨기시는 게 있다면,\n이 사건은 영원히 올바른 판결을 받을 수 없게 될 거예요.",
  ui_story_5045_50451201_97_dialog_content = "...알겠어요.",
  ui_story_5045_50451201_98_dialog_content = "이 접시는 어제 우리 남편이 깬 거예요.",
  ui_story_5045_50451201_99_dialog_content = "하지만 전 느꼈어요.\n그 사람은 제가 이혼에 동의하게 만들려고 일부러 화를 내는 거였어요.",
  ui_story_5045_50451201_100_dialog_content = "통 이해가 안 되네요. 베이컨 씨가 파니 씨를 그렇게 대하는데도...\n왜 이혼하지 않으려고 하시는 거죠?",
  ui_story_5045_50451201_101_dialog_content = "심판관님은 가슴 깊이 새겨지는 사랑을 해 본 적이 없으신 모양이네요.",
  ui_story_5045_50451201_102_dialog_content = "언젠가 사랑하는 사람과 가정을 꾸리고 나면...",
  ui_story_5045_50451201_103_dialog_content = "심판관님도 자신의 가정을 지키기 위해 뭐든 다 하게 되실 거예요.",
  ui_story_5045_50451201_104_dialog_content = "베이컨 씨한텐 이 가정을 깨트리겠다는 마음밖에 없다고 해도요?",
  ui_story_5045_50451201_105_dialog_content = "사실 심판소에서 차마 말하지 못한 이야기들이 많이 있어요.\n그랬다면 남편이 다른 사람들한테 비웃음을 샀을 테니까요.",
  ui_story_5045_50451201_106_dialog_content = "비밀은 지켜드릴 테니 안심하세요.",
  ui_story_5045_50451201_107_dialog_content = "하실 이야기가 있으면 편하게 말씀하시면 돼요.",
  ui_story_5045_50451201_108_dialog_content = "어느 날 전 남편을 데리고 산책을 하러 나갔고,\n마침 의료 봉사를 하고 있는 의사를 만났어요.",
  ui_story_5045_50451201_109_dialog_content = "그분은 우리 남편이 「<color=#1875ad>마음의 병</color>」을 앓고 있다고 하더군요.",
  ui_story_5045_50451201_110_dialog_content = "그 병 때문에 남편이 잠을 통 못 자고, 꿈도 많이 꾸고,\n의기소침해 있고, 행동이 굼떠진 거라고 했어요...",
  ui_story_5045_50451201_111_dialog_content = "전 그제서야 남편이 일을 하기 싫어했던 게 아니라,\n마음의 병 때문에 그런다는 사실을 깨달았어요.",
  ui_story_5045_50451201_112_dialog_content = "그걸 알고 나서부턴 두 번 다시 남편을 닦달하지 않았죠.",
  ui_story_5045_50451201_113_dialog_content = "전 남편이 열심히 치료를 받으면서 마음의 병이 조금씩 낫기만을 바랐어요.",
  ui_story_5045_50451201_114_dialog_content = "갑자기 심판소에 이혼 소송을 제기할 줄은 정말 상상도 못 했죠.",
  ui_story_5045_50451201_115_dialog_content = "분명히 남편에게 무슨 일이 있었으니까 그러는 것 같은데...\n제겐 말을 안 해 주려고 해요.",
  ui_story_5045_50451201_116_dialog_content = "베이컨 씨한테 무슨 일이 있었던 걸까?",
  ui_story_5045_50451201_117_dialog_content = "우리가 물어봐도 대답은 안 해 줄 것 같네요. 차라리 방에서 단서를 찾아보죠.",
  ui_story_5045_50451201_118_dialog_content = "어딜 조사해 볼까요?",
  ui_story_5045_50451201_119_dialog_content = "생각 좀 해 볼게...",
  ui_story_5045_50451201_120_option_content = "벽 주변을 살펴보자.",
  ui_story_5045_50451201_121_dialog_content = "벽에 걸려 있는 저 <color=#1875ad>사진</color>을 좀 볼 수 있을까요?",
  ui_story_5045_50451201_122_dialog_content = "그럼요. 제가 내려 드릴게요.",
  ui_story_5045_50451201_123_dialog_content = "이 사진의 두 사람은 파니 씨랑 베이컨 씨겠죠?",
  ui_story_5045_50451201_124_dialog_content = "네, 하지만 벌써 7년 전 일이에요.",
  ui_story_5045_50451201_125_dialog_content = "그땐 결혼한지 얼마 안 돼서 저나 남편이나 가진 게 하나도 없었죠.",
  ui_story_5045_50451201_126_dialog_content = "근데 남편이 뭘 어떻게 설득한 건지,\n사진사가 돈도 안 받고 그 사진을 찍어 줬었어요...",
  ui_story_5045_50451201_127_dialog_content = "그러고 보니 저희 부부가 나온 사진은 이게 처음이자 마지막이네요.",
  ui_story_5045_50451201_128_dialog_content = "사진 뒷면에 <color=#1875ad>주소</color>가 적혀 있는데, 이 사진을 찍은 곳인가요?",
  ui_story_5045_50451201_129_dialog_content = "어머? 이상하네요. 이런 걸 적어 뒀던 기억은 없는데...",
  ui_story_5045_50451201_130_dialog_content = "이건 남편의 글씨예요.",
  ui_story_5045_50451201_131_dialog_content = "조금 수상하군요. 우선 기록해 두는 게 좋겠어요.",
  ui_story_5045_50451201_132_dialog_content = "그 외에 또...",
  ui_story_5045_50451201_133_option_content = "탁자를 살펴보자.",
  ui_story_5045_50451201_134_dialog_content = "음? 탁자 위의 이 <color=#1875ad>카드</color>는 뭐죠?",
  ui_story_5045_50451201_135_dialog_content = "...그건 「<color=#1875ad>마인드 아카데미</color>」의 <color=#1875ad>수강증</color>이에요.",
  ui_story_5045_50451201_136_dialog_content = "카를이란 친구가 저한테 거기가 좋다고 추천해 줬었거든요.",
  ui_story_5045_50451201_137_dialog_content = "마음을 단련시켜 두려움 없이 삶의 어려움을 마주하도록 돕는 교육이에요.",
  ui_story_5045_50451201_138_dialog_content = "많은 사람들이 그 교육을 듣고 전보다 더 나은 삶을\n살게 됐다는 이야기도 들었어요.",
  ui_story_5045_50451201_139_dialog_content = "백야성에 저런 교육기관도 있었어?",
  ui_story_5045_50451201_140_dialog_content = "그런 사설 교육기관엔 가 본 적 없지만, 수강료가 무척 비싸다는 얘긴 들었어요.",
  ui_story_5045_50451201_141_dialog_content = "...전 정말 진심으로 남편의 상태가 호전되길 바랐어요.\n그래서 돈을 빌려서 그 아카데미에 남편을 등록해 줬어요.",
  ui_story_5045_50451201_142_dialog_content = "하지만 남편은 뭐라고 해도 도통 가려고 하질 않았어요.\n게다가 「마인드 아카데미」의 수강료는 환불이 안 돼요.",
  ui_story_5045_50451201_143_dialog_content = "그래서 전 남편이 돌아와서, 한 번만이라도 가서 수업을 들었으면 좋겠어요...",
  ui_story_5045_50451201_144_dialog_content = "파니 씨가 돈을 빌린 이유는 베이컨 씨를 위해서였군요...",
  ui_story_5045_50451201_145_dialog_content = "그 외에 또...",
  ui_story_5045_50451201_146_option_content = "딱히 더 살펴볼 곳은 없는 것 같아.",
  ui_story_5045_50451201_147_dialog_content = "확실히 다른 유의미한 단서는 없어 보이네요.",
  ui_story_5045_50451201_148_dialog_content = "근데 이 <color=#1875ad>유리병</color>이 좀 신경 쓰인단 말이지...",
  ui_story_5045_50451201_149_dialog_content = "<color=#737378>달그락 달그락...</color>",
  ui_story_5045_50451201_150_dialog_content = "안에 든 건 무슨 조미료 같은 건가?",
  ui_story_5045_50451201_151_dialog_content = "아! 이건 남편의 <color=#1875ad>약병</color>이에요!",
  ui_story_5045_50451201_152_dialog_content = "남편은 줄곧 의료 봉사를 나온 의사에게 치료를 받아 왔어요.\n그리고 이 약을 매일 먹어야 해요.",
  ui_story_5045_50451201_153_dialog_content = "근데 오늘은 약을 먹었는지 모르겠네요...",
  ui_story_5045_50451201_154_dialog_content = "휴, 베이컨 씨는 여러모로 걱정을 끼치는 사람이구나.",
  ui_story_5045_50451201_155_dialog_content = "<color=#737378>시간: 오후 4시</color>",
  ui_story_5045_50451201_156_dialog_content = "<color=#737378>장소: 백야성 다운타운 구역, 무료 진료소 앞</color>",
  ui_story_5045_50451201_157_dialog_content = "베이컨 씨네 집을 조사하고 나니까 오히려 뭐가 어떻게 된 건지 더 모르겠잖아.",
  ui_story_5045_50451201_158_dialog_content = "여기선 뭔가 유용한 정보를 얻을 수 있었으면 좋겠네요.",
  ui_story_5045_50451201_159_dialog_content = "어? PlayerName하고 티나 심판관이네!",
  ui_story_5045_50451201_160_dialog_content = "라파엘, 네가 여긴 웬일이야?",
  ui_story_5045_50451201_161_dialog_content = "그건 라파엘이 할 말 아냐? 여긴 라파엘이 일하는 곳이라구.",
  ui_story_5045_50451201_162_dialog_content = "안녕하세요. 저희가 맡은 사건의 당사자가 여기 환자인 것 같거든요.\n그래서 사정을 조사하러 와 봤어요.",
  ui_story_5045_50451201_163_dialog_content = "혹시 「베이컨」이란 사람을 기억하고 계신가요?",
  ui_story_5045_50451201_164_dialog_content = "베이컨 씨? 그 사람 내 <color=#1875ad>환자</color> 맞아!",
  ui_story_5045_50451201_165_dialog_content = "정말? 이런 우연이 다 있네.",
  ui_story_5045_50451201_166_dialog_content = "응, 베이컨 씨는 라파엘이 의료 봉사를 할 때 담당한 환자야.",
  ui_story_5045_50451201_167_dialog_content = "치료를 해도 계속 차도가 없어서 진짜 난감했었다구.",
  ui_story_5045_50451201_168_dialog_content = "근데 진료받으러 안 온 지 꽤 돼서 정말 걱정돼...",
  ui_story_5045_50451201_169_dialog_content = "잠깐만! 베이컨 씨가 사건 당사자라고 했었지?\n베이컨 씨한테 무슨 일 생겼어? 설마 감옥 가는 건 아니지?",
  ui_story_5045_50451201_170_dialog_content = "안심하세요. 그렇게 심각한 일은 아니거든요.",
  ui_story_5045_50451201_171_dialog_content = "그래? 그럼 빨리 회진받으러 오고, 와서 약도 타 가라고 말 좀 전해 줘.",
  ui_story_5045_50451201_172_dialog_content = "날짜를 보니까 저번에 타 간 약은 진작에 다 먹었겠더라구.",
  ui_story_5045_50451201_173_dialog_content = "어라? 하지만 저희가 베이컨 씨 집에서 발견한 유리병엔\n알약이 꽤 많이 남아 있었는걸요...",
  ui_story_5045_50451201_174_dialog_content = "뭐? 그럴 리가 없는데?",
  ui_story_5045_50451201_175_dialog_content = "라파엘이 매번 소량으로만 처방해 줬단 말이야.\n받야간 걸 다 복용하고 다음 약을 받아 가게 말이야.",
  ui_story_5045_50451201_176_dialog_content = "설마 파니 씨가 잘못 알고 있는 걸까요?",
  ui_story_5045_50451201_177_dialog_content = "<color=#737378>시간: 오후 5시</color>",
  ui_story_5045_50451201_178_dialog_content = "<color=#737378>장소: 백야성 다운타운 구역, 베이컨과 파니 부부의 집</color>",
  ui_story_5045_50451201_179_dialog_content = "<size=45>뭐야?!</size>",
  ui_story_5045_50451201_180_dialog_content = "쉿! 파니 씨가 자기 남편의 담당 의사도 와 있는 걸 보면 엄청 걱정할 거라고.",
  ui_story_5045_50451201_181_dialog_content = "라파엘 씨, 뭔가 발견하셨나요?",
  ui_story_5045_50451201_182_dialog_content = "이 약들은 라파엘이 베이컨 씨한테 처방해 줬던 수면 유도제야.",
  ui_story_5045_50451201_183_dialog_content = "왜 하나도 안 먹고 다 유리병 안에 넣어둔 거지?",
  ui_story_5045_50451201_184_dialog_content = "그럼 이 약들은 베이컨 씨가 일부러 모아 뒀다는 거군요.",
  ui_story_5045_50451201_185_dialog_content = "가면 갈수록 대체 베이컨 씨가 무슨 생각인 건지 모르겠어...",
  ui_story_5045_50451201_186_dialog_content = "라파엘 씨, 만약에, 어디까지나 만약에 말인데요...",
  ui_story_5045_50451201_187_dialog_content = "이 약들을 한 번에 모두 복용한다면, 어떻게 되나요?",
  ui_story_5045_50451201_188_dialog_content = "<size=45>뭐라구?!</size>",
  ui_story_5045_50451201_189_dialog_content = "그런 생각은 하지도 마!",
  ui_story_5045_50451201_190_dialog_content = "PlayerName 씨, 뭔가 불길한 예감이 들어요...",
  ui_story_5045_50451201_191_dialog_content = "나도 그래.",
  ui_story_5045_50451201_192_dialog_content = "재판을 서둘러야겠어요.",
  ui_story_5045_50451201_193_dialog_content = "하지만 그 전에 PlayerName 씨한테 부탁할 일이 하나 있어요.",
  ui_story_5045_50451201_194_dialog_content = "부탁? 말만 해!",
  ui_story_5045_50451201_195_dialog_content = "잠들 것... 같아요... 저 좀 업어서... 데리고 돌아가 주세요...",
  ui_story_5045_50451201_196_dialog_content = "휴우우... 후우... Zzz...",
  ui_story_5045_50451201_197_dialog_content = "......",
  ui_story_5045_50451301_1_dialog_content = "<color=#737378>시간: 오전 9시</color>",
  ui_story_5045_50451301_2_dialog_content = "<color=#737378>장소: 백야성 심판소, 소심판정</color>",
  ui_story_5045_50451301_3_dialog_content = "어? 오늘은 심판소가 썰렁하네...?",
  ui_story_5045_50451301_4_dialog_content = "심사숙고해서 내린 결정이에요.\n방청객이 있으면 이번 사건의 당사자들한테 영향을 줄 것 같아서요.",
  ui_story_5045_50451301_5_dialog_content = "그래서 이번 심리는 방청객 없이 진행하기로 했어요.",
  ui_story_5045_50451301_6_dialog_content = "어? 그건 또 언제 생각한 거야?",
  ui_story_5045_50451301_7_dialog_content = "어제저녁에 당신 등에 업혀서 돌아갈 때부터였을 거예요.",
  ui_story_5045_50451301_8_dialog_content = "뭐? 그럼 티나 너...",
  ui_story_5045_50451301_9_option_content = "잠을 자도 쉬는 게 아니었구나?",
  ui_story_5045_50451301_10_dialog_content = "맞아요. 전 꿈을 많이 꾸거든요.",
  ui_story_5045_50451301_11_dialog_content = "깨어 있을 땐 어떻게 해야 좋을지 막막했던 일인데,\n꿈에서 곰곰이 생각하다 보면 답이 나오는 경우도 가끔 있어요.",
  ui_story_5045_50451301_12_dialog_content = "그럼 자는 게 자는 게 아니잖아... 엄청 피곤하지 않아?",
  ui_story_5045_50451301_13_dialog_content = "헤헷, 역시 PlayerName 씨는 다정한 사람이네요.",
  ui_story_5045_50451301_14_dialog_content = "레인 씨는 저한테 그렇게 신경 써 준 적 없거든요.",
  ui_story_5045_50451301_15_dialog_content = "그, 그래...?",
  ui_story_5045_50451301_16_option_content = "엄청 성실한 사람이었구나.",
  ui_story_5045_50451301_17_dialog_content = "우후후, 당연하죠.",
  ui_story_5045_50451301_18_dialog_content = "심판관에게 있어서 성실은 가장 기본적인 소양이랍니다.",
  ui_story_5045_50451301_19_dialog_content = "...잠깐만요! 그럼 설마 지금까지는 절 불성실한 사람이라고\n생각하고 계셨던 건가요?",
  ui_story_5045_50451301_20_dialog_content = "아, 그게, 그러니까...",
  ui_story_5045_50451301_21_option_content = "자는 척하는 거였어?",
  ui_story_5045_50451301_22_dialog_content = "하아... 아무래도 PlayerName 씨는 파트너에 대한 배려심이\n레인 씨보다도 더 부족한 것 같네요.",
  ui_story_5045_50451301_23_dialog_content = "(착각인가... 방금 티나가 날 엄청 싫은 눈빛으로 쳐다본 것 같았는데...?)",
  ui_story_5045_50451301_24_dialog_content = "(괜히 대답 한 번 잘못해서 날 향한 티나의 믿음이 흔들리고 있잖아...)",
  ui_story_5045_50451301_25_dialog_content = "일단 지금은 그것보다 재판이 더 중요하니까, 얼른 시작해 볼까요?",
  ui_story_5045_50451301_26_dialog_content = "<color=#737378>탕!</color>",
  ui_story_5045_50451301_27_dialog_content = "<size=45>만물은 백야 아래에, 지금부터 재판을 시작하겠습니다!</size>",
  ui_story_5045_50451301_28_dialog_content = "먼저, 항소인은 항소 취지를 진술해 주세요.",
  ui_story_5045_50451301_29_dialog_content = "존경하는 심판관님. 전 1심의 이혼 판결을 받아들일 수 없습니다.",
  ui_story_5045_50451301_30_dialog_content = "전 저와 피항소인의 관계가 파탄에 이르지 않았다고 생각합니다.\n따라서 피항소인과 이혼하고 싶지 않습니다.",
  ui_story_5045_50451301_31_dialog_content = "파니, 그만 좀 해...",
  ui_story_5045_50451301_32_dialog_content = "제발 부탁이니까 이젠 날 좀 놔 줘.",
  ui_story_5045_50451301_33_dialog_content = "피항소인은 여전히 원심의 진술과 동일하게\n항소인과의 관계가 파탄에 이르렀다고 주장하시나요?",
  ui_story_5045_50451301_34_dialog_content = "예, 심판관님.",
  ui_story_5045_50451301_35_dialog_content = "하지만...",
  ui_story_5045_50451301_36_dialog_content = "피항소인은 줄곧 <color=#1875ad>항소인의 이익을 지키는</color> 행위를 해 왔습니다!",
  ui_story_5045_50451301_37_dialog_content = "PlayerName 씨, 갑자기 그 얘기는 왜 하는 거죠?",
  ui_story_5045_50451301_38_dialog_content = "이, 이런... 내가 잘못 말한 거야!",
  ui_story_5045_50451301_39_dialog_content = "그러니까...",
  ui_story_5045_50451301_40_dialog_content = "티나, 이것 좀 봐!",
  ui_story_5045_50451301_41_dialog_content = "으음, 아주 상세히 잘 기록해 두셨네요.",
  ui_story_5045_50451301_42_dialog_content = "근데 아까부터 자꾸 이 상황을 겪어 본 것만 같은 기분이 들어요.\n설마 제가 아직 꿈을 꾸고 있는 걸까요?",
  ui_story_5045_50451301_43_dialog_content = "요즘은 딱히 악몽을 꾸진 않았으니까...\n오늘 재판은 성공적으로 마무리할 수 있겠죠!",
  ui_story_5045_50451301_44_dialog_content = "그나저나 갑자기 그 기록은 왜 보여주신 거죠? 혹시 칭찬받고 싶으신 건가요?",
  ui_story_5045_50451301_45_dialog_content = "아, 아니야. 그러니까...",
  ui_story_5045_50451301_46_dialog_content = "피항소인이 모든 재산을 항소인에게 넘기고, 모든 채무는 자신이 승계한 것이\n그 사실을 가장 잘 증명해 줍니다.",
  ui_story_5045_50451301_47_dialog_content = "그, 그건 저희 사이가 파탄에 이른 것과는 관계가 없는 일입니다.",
  ui_story_5045_50451301_48_dialog_content = "모든 재산을 항소인에게 넘긴 건 저 사람이 7년간 해온\n가사노동 기여분에 대한 보상이었습니다.",
  ui_story_5045_50451301_49_dialog_content = "전 그렇게라도 해서 제 자유를 되찾고 싶었을 뿐입니다... 다른 이유는 없습니다.",
  ui_story_5045_50451301_50_dialog_content = "정말 그게 다야?",
  ui_story_5045_50451301_51_dialog_content = "이제 정말... 날 사랑하지 않는 거야...?",
  ui_story_5045_50451301_52_dialog_content = "맞아. 그러니까 이제 집착 좀 그만해.",
  ui_story_5045_50451301_53_dialog_content = "흑흑흑... 당신이 어떻게 나한테 그래? 대체 나한테 왜 그러는 거냐고!",
  ui_story_5045_50451301_54_dialog_content = "항소인, 아직 심리가 끝나지 않았으니 슬퍼하기는 일러요.",
  ui_story_5045_50451301_55_dialog_content = "심판관님, 저 사람이 저렇게까지 말한 이상, 저도 더는 집착하고 싶지 않아요.",
  ui_story_5045_50451301_56_dialog_content = "이 재판을 계속하는 게 무슨 의미가 있겠어요?",
  ui_story_5045_50451301_57_dialog_content = "있습니다! 당연히 있죠!",
  ui_story_5045_50451301_58_dialog_content = "어라? PlayerName 씨, 갑자기 왜 그렇게 흥분한 거죠?",
  ui_story_5045_50451301_59_dialog_content = "난 아무리 봐도 두 사람이 여전히 서로 사랑하고 있다는 생각이 들어...",
  ui_story_5045_50451301_60_dialog_content = "그럼 이제 어떻게 할 생각인가요?",
  ui_story_5045_50451301_61_dialog_content = "그, 그건 잘 모르겠어.",
  ui_story_5045_50451301_62_dialog_content = "후훗, 그럼 제가 하는 걸 잘 보세요.",
  ui_story_5045_50451301_63_dialog_content = "크흠, 본 심판소는 최근 조사를 통해 이상한 물건들을 발견할 수 있었습니다.",
  ui_story_5045_50451301_64_dialog_content = "만약 양측이 이에 제대로 해명하지 못한다면, 이 사건은 더는 연애 지부에서\n다룰 수 없는 심각한 사안으로 발전할 수도 있습니다.",
  ui_story_5045_50451301_65_dialog_content = "티나가 말한 그 「이상한 물건」...\n어제 <color=#1875ad>라파엘이 우리한테 보여줬던 그 물건</color> 말하는 거지?",
  ui_story_5045_50451301_66_dialog_content = "그게 아니에요. 다시 잘 생각해 보세요, PlayerName 씨.",
  ui_story_5045_50451301_67_dialog_content = "이제 알았어!",
  ui_story_5045_50451301_68_dialog_content = "피항소인, 이 물건을 알아보시겠어요?",
  ui_story_5045_50451301_69_dialog_content = "그, 그건...",
  ui_story_5045_50451301_70_dialog_content = "피항소인, 이 유리병 안에 어떤 약이 들어 있는지 진술하세요.",
  ui_story_5045_50451301_71_dialog_content = "제, 제가 의사에게 처방받은... 수면 유도제입니다.",
  ui_story_5045_50451301_72_dialog_content = "저희는 이미 피항소인을 진료했던 의사 라파엘 씨를 어제 만났습니다.",
  ui_story_5045_50451301_73_dialog_content = "라파엘 씨의 증언에 따르면, 피항소인이 진찰을 받으러 올 때마다\n라파엘 씨는 수면 유도제를 소량으로만 처방해 왔다고 하더군요.",
  ui_story_5045_50451301_74_dialog_content = "그러나 이 유리병에 든 수면 유도제의 양을 보면,\n피항소인은 의사 몰래 약을 모아 왔다는 것을 알 수 있어요.",
  ui_story_5045_50451301_75_dialog_content = "이렇게 다량의 수면 유도제를 모은 건... 항소인을 해치기 위해서인가요?",
  ui_story_5045_50451301_76_dialog_content = "<size=45>뭐라고요?!</size>",
  ui_story_5045_50451301_77_dialog_content = "여보! 아니야! 그렇지 않아! 난 당신을 해치겠다는 생각 같은 건 한 적 없어...!",
  ui_story_5045_50451301_78_dialog_content = "그렇다면 일부러 수면 유도제를 모아 둔 이유는 무엇인가요?",
  ui_story_5045_50451301_79_dialog_content = "......",
  ui_story_5045_50451301_80_dialog_content = "...그 부분은 이혼 사건과는 관계가 없습니다.",
  ui_story_5045_50451301_81_dialog_content = "당신 정말 변했구나... 이젠 정말 내가 알던 당신이 아닌 것 같아.",
  ui_story_5045_50451301_82_dialog_content = "여보...",
  ui_story_5045_50451301_83_dialog_content = "티나, 이제 어떡하지?",
  ui_story_5045_50451301_84_dialog_content = "피항소인이 입을 열지 않는다면, 저희도 어쩔 수가 없어요.",
  ui_story_5045_50451301_85_dialog_content = "우리가 밝혀내지 못한 의문점을 더 찾을 수 있겠어요?",
  ui_story_5045_50451301_86_dialog_content = "이 사건은 그 자체로 이미 의문투성이잖아!",
  ui_story_5045_50451301_87_dialog_content = "어라, 잠깐만, 갑자기 생각난 게 하나 있어...",
  ui_story_5045_50451301_88_dialog_content = "그 <color=#1875ad>주소</color>!",
  ui_story_5045_50451301_89_dialog_content = "어디에 무슨 주소가 있다는 거죠?",
  ui_story_5045_50451301_90_dialog_content = "아, 이게 아니고... 이, 이거야!",
  ui_story_5045_50451301_91_dialog_content = "이 사진 뒷면엔 주소가 하나 적혀 있었잖아.\n근데 우린 아직 그 주소가 어디인지 알아내지 못했어.",
  ui_story_5045_50451301_92_dialog_content = "아! 그렇네요. 덕분에 제가 증인을 한 명 소환했다는 사실도 기억났어요!",
  ui_story_5045_50451301_93_dialog_content = "대체 증인을 언제 부른 건데? 그것도 꿈에서 부른 건 아니지?",
  ui_story_5045_50451301_94_dialog_content = "<color=#737378>탕!</color>",
  ui_story_5045_50451301_95_dialog_content = "그럼 증인 <color=#1875ad>미제니</color> 씨는 증인석으로 나와 주세요.",
  ui_story_5045_50451301_96_dialog_content = "여러분, 좋은 아침입니다. 전 세무관 미제니입니다.",
  ui_story_5045_50451301_97_dialog_content = "이 사진 뒷면엔 주소가 수기로 적혀 있습니다만,\n증인은 이 주소가 가리키는 장소를 알고 있나요?",
  ui_story_5045_50451301_98_dialog_content = "그건 <color=#1875ad>보험 서비스</color>를 제공하는 한 신설 기관의 주소예요.",
  ui_story_5045_50451301_99_dialog_content = "본건의 당사자 베이컨 씨는 자신을 피보험자로 하는 <color=#1875ad>생명보험</color>에 가입했어요.",
  ui_story_5045_50451301_100_dialog_content = "만약 베이컨 씨가 뜻밖의 사고로 인해 사망할 경우,\n해당 기관에 <color=#1875ad>거액의 보험금</color>을 청구할 수 있어요.",
  ui_story_5045_50451301_101_dialog_content = "그런 상황이 발생했을 때 보험금을 수령할 보험수익자는 누구로 되어 있죠?",
  ui_story_5045_50451301_102_dialog_content = "해당 기관에서는 보험수익자에 관한 정보가 기밀 사항이라고 하더군요.",
  ui_story_5045_50451301_103_dialog_content = "하지만 이와 관련한 중대 사건이 발생한 경우, 법률에 따라 조사할 수 있어요.",
  ui_story_5045_50451301_104_dialog_content = "알겠습니다, 증인. 수고하셨습니다.",
  ui_story_5045_50451301_105_dialog_content = "그럼 먼저 실례하겠습니다.",
  ui_story_5045_50451301_106_dialog_content = "심판관님, 바, 방금 그게... 대체 무슨 뜻이죠?",
  ui_story_5045_50451301_107_dialog_content = "설마... 베이컨 씨가 저 약을 자기한테 쓰려고 준비했다는 거야?",
  ui_story_5045_50451301_108_dialog_content = "누군가한테 거액의 보험금을 남겨 주려고?",
  ui_story_5045_50451301_109_dialog_content = "피항소인은 자신의 행위가 징역형에 처할 수 있는 범죄임을 알고 있나요?",
  ui_story_5045_50451301_110_dialog_content = "백야성의 감옥은 살아도 산 게 아닌 곳이라고 들었는데요.",
  ui_story_5045_50451301_111_dialog_content = "......",
  ui_story_5045_50451301_112_dialog_content = "전...",
  ui_story_5045_50451301_113_dialog_content = "안심하세요. 지금 솔직하게 말씀하시면 정상 참작의 여지가 있어요.",
  ui_story_5045_50451301_114_dialog_content = "당신... 대체 뭘 꾸미고 있었던 거야?",
  ui_story_5045_50451301_115_dialog_content = "어서 심판관님한테 말씀드려.\n당신 부인이었던 사람으로서 하는 마지막 부탁이야.",
  ui_story_5045_50451301_116_dialog_content = "...여보, 미안해.",
  ui_story_5045_50451301_117_dialog_content = "오랫동안 날 속이고, 심지어는 당신까지 속여 가면서 준비했는데...\n결국 실패해 버렸네.",
  ui_story_5045_50451301_118_dialog_content = "대체 무슨 짓을 하려던 거야...",
  ui_story_5045_50451301_119_dialog_content = "심판관님, 전 원래 한 귀족의 정원사로 일하고 있었습니다.",
  ui_story_5045_50451301_120_dialog_content = "하지만 실수로 그분이 아끼는 도자기를 깨 버리는 바람에 직업을 잃게 됐죠.",
  ui_story_5045_50451301_121_dialog_content = "그렇게 쫓겨난 후, 모든 고용인들이 제 실직 이유를 가지고 절 비웃기 시작했고,\n절 받아 주겠다는 곳은 아무 데도 없었습니다...",
  ui_story_5045_50451301_122_dialog_content = "전 집 안에 틀어박혀 버렸고, 갈수록 밖으로 나가는 게 겁이 났습니다.\n그러다 보니 앞으로 제가 뭘 할 수 있을지도 모르게 되어 버렸습니다.",
  ui_story_5045_50451301_123_dialog_content = "결국 빚은 갈수록 늘어났고, 제 아내는 점점 더 힘들어졌습니다.",
  ui_story_5045_50451301_124_dialog_content = "전 아내를 지키고, 가정을 지켰어야 했지만,\n막상 전 아무것도 할 수가 없었습니다...",
  ui_story_5045_50451301_125_dialog_content = "그리고 바로 그때, 저희 집 근처에 세워진 보험 기관을 보았습니다.",
  ui_story_5045_50451301_126_dialog_content = "그리고 전 그런 생각이 들었습니다.\n이대로 아내의 짐이 되느니, 차라리...",
  ui_story_5045_50451301_127_dialog_content = "이 바보야! 난 당신을 짐이라고 생각한 적 한 번도 없었어!",
  ui_story_5045_50451301_128_dialog_content = "...모두 제 욕심 탓입니다.",
  ui_story_5045_50451301_129_dialog_content = "전 채무를 제가 전부 떠안은 다음 아내와 이혼하면...",
  ui_story_5045_50451301_130_dialog_content = "제 죽음과 함께 빚들도 사라질 거라 생각했습니다.",
  ui_story_5045_50451301_131_dialog_content = "하지만 이런 일 하나도 제대로 못 할 만큼 제가 무능할 줄은 몰랐습니다...",
  ui_story_5045_50451301_132_dialog_content = "피항소인, 그거 아시나요?",
  ui_story_5045_50451301_133_dialog_content = "피보험자가 스스로 목숨을 끊을 경우, 보험사는 보험금을 지급하지 않아요.",
  ui_story_5045_50451301_134_dialog_content = "그, 그게 정말입니까?!",
  ui_story_5045_50451301_135_dialog_content = "만약 피항소인이 정말 그 계획을 실행했다면,\n피항소인은 항소인에게 막대한 빚에 끝없는 슬픔까지 안겨줬을 겁니다.",
  ui_story_5045_50451301_136_dialog_content = "세상에... 내가 지금까지 해 온 일들은 대체...",
  ui_story_5045_50451301_137_dialog_content = "여보, 미안해... 정말 미안해...",
  ui_story_5045_50451301_138_dialog_content = "결국 난 어떻게 해도 당신을 행복하게 해 줄 수 없는 사람이야...",
  ui_story_5045_50451301_139_dialog_content = "무슨 소리야...",
  ui_story_5045_50451301_140_dialog_content = "난 언제나 행복했는걸.",
  ui_story_5045_50451301_141_dialog_content = "......",
  ui_story_5045_50451301_142_dialog_content = "우리가 직접 만들었던 그 접시 기억나?",
  ui_story_5045_50451301_143_dialog_content = "기억나요! 그 <color=#1875ad>접시</color>!",
  ui_story_5045_50451301_144_dialog_content = "PlayerName 씨, 이럴 땐 가만히 계세요.",
  ui_story_5045_50451301_145_dialog_content = "미안... 근데 아무리 생각해도...",
  ui_story_5045_50451301_146_dialog_content = "이 깨진 접시 말씀이시죠?",
  ui_story_5045_50451301_147_dialog_content = "기억납니다. 저희가 이제 막 결혼했을 때였죠...",
  ui_story_5045_50451301_148_dialog_content = "뭐야, 심판소에서 신혼 때 추억 이야기를 꺼내려는 건가?",
  ui_story_5045_50451301_149_dialog_content = "쉿!",
  ui_story_5045_50451301_150_dialog_content = "미안해...",
  ui_story_5045_50451301_151_dialog_content = "무슨 소리야, 여보. 뭘 미안해하고 그래.",
  ui_story_5045_50451301_152_dialog_content = "근사한 저녁 식사로 당신을 깜짝 놀라게 주고 싶었는데,\n실수로 우리 접시를 다 깨 버렸잖아...",
  ui_story_5045_50451301_153_dialog_content = "하하하, 안 다쳤으면 된 거야. 자책하지 마.",
  ui_story_5045_50451301_154_dialog_content = "어차피 언제 샀는지 기억도 안 나는 오래된 것들이었으니까,\n이참에 새 걸로 바꾸면 돼.",
  ui_story_5045_50451301_155_dialog_content = "하지만... 우린 돈이 없잖아...",
  ui_story_5045_50451301_156_dialog_content = "우리가 직접 만들면 되지.",
  ui_story_5045_50451301_157_dialog_content = "우리가? 우리가 접시를 어떻게 만들어?",
  ui_story_5045_50451301_158_dialog_content = "자, 따라와 봐!",
  ui_story_5045_50451301_159_dialog_content = "후훗, 그때 전 남편이 도자기 가게에 아는 사람이라도 있는 줄 알았어요.",
  ui_story_5045_50451301_160_dialog_content = "근데 정작 절 황량한 교외의 들판에 데려갔던 거예요.",
  ui_story_5045_50451301_161_dialog_content = "그리곤 강물 아래의 진흙바닥을 가리키더니 제게 마술을 보여 주겠다고 했죠.",
  ui_story_5045_50451301_162_dialog_content = "이 진흙을 우리가 원하는 모양으로 빚은 다음에, 불로 구워내면...",
  ui_story_5045_50451301_163_dialog_content = "우리만의 접시를 만들 수 있어.",
  ui_story_5045_50451301_164_dialog_content = "우와, 우리 남편 정말 대단해!",
  ui_story_5045_50451301_165_dialog_content = "헤헤, 근데 내가 만든 건 좀 비뚤비뚤하네.",
  ui_story_5045_50451301_166_dialog_content = "내가 만든 것도 썩 예쁘진 않은걸.",
  ui_story_5045_50451301_167_dialog_content = "하지만 이건 세상에 둘도 없는 우리 두 사람만의 접시야!\n귀족들이 가지고 싶어도 못 가질 거잖아!",
  ui_story_5045_50451301_168_dialog_content = "그때 우린 아무것도 가진 게 없었지만 그렇게 행복했어.",
  ui_story_5045_50451301_169_dialog_content = "그리고 이젠 우리 명의로 집도 있잖아. 대출도 있긴 하지만...",
  ui_story_5045_50451301_170_dialog_content = "당신과 둘이 건강하고 즐겁게 지낼 수만 있다면,\n그건 나이티움 얼마를 줘도 바꿀 수 없는 행복이야.",
  ui_story_5045_50451301_171_dialog_content = "여보...",
  ui_story_5045_50451301_172_dialog_content = "다 좋아질 거야.",
  ui_story_5045_50451301_173_dialog_content = "이건 당신이 나한테 가르쳐 주고, 행동으로 내게 믿음을 준 진리야.",
  ui_story_5045_50451301_174_dialog_content = "그러니까... 이번엔 당신이 날 믿어 주지 않을래?",
  ui_story_5045_50451301_175_dialog_content = "...그래.",
  ui_story_5045_50451301_176_dialog_content = "이 사건도 이제 결론이 나온 것 같네.",
  ui_story_5045_50451301_177_dialog_content = "<color=#737378>탕!</color>",
  ui_story_5045_50451301_178_dialog_content = "만물은 백야 아래에, 지금부터 판결을 선고하겠습니다!",
  ui_story_5045_50451301_179_dialog_content = "먼저, 피항소인 베이컨과 항소인 파니는 심리 과정 중\n두 사람의 사랑이 굳건하다는 사실을 보여주었습니다.",
  ui_story_5045_50451301_180_dialog_content = "또한, 피항소인은 보험 사기를 저지르려 했으나 미수에 그쳤으며,\n범행을 깊이 반성하고 있는 점을 참작하였습니다.",
  ui_story_5045_50451301_181_dialog_content = "이에 따라 다음과 같이 판결을 선고합니다!",
  ui_story_5045_50451301_182_dialog_content = "주문. 원심판결을 파기한다.\n피항소인 베이컨과 항소인 파니는 혼인 관계를 유지한다.",
  ui_story_5045_50451301_183_dialog_content = "피항소인이 수집한 약물을 몰수한다.\n피항소인은 향후 지정 시일에 진찰을 받고 처방에 따라 약을 복용한다.",
  ui_story_5045_50451301_184_dialog_content = "<color=#737378>탕!</color>",
  ui_story_5045_50451301_185_dialog_content = "이상으로 재판을 마치겠습니다!",
  ui_story_5045_50451401_1_dialog_content = "<color=#737378>시간: 오후 2시</color>",
  ui_story_5045_50451401_2_dialog_content = "<color=#737378>장소: 백야성 심판소, 연애 지부 사무실</color>",
  ui_story_5045_50451401_3_dialog_content = "하아암~",
  ui_story_5045_50451401_4_dialog_content = "깼구나?",
  ui_story_5045_50451401_5_dialog_content = "몇몇 사건의 개요를 정리해 뒀으니까, 읽어 보고 어떤 것부터 살펴볼지 알려 줘.",
  ui_story_5045_50451401_6_dialog_content = "잘하셨네요, PlayerName 씨.",
  ui_story_5045_50451401_7_dialog_content = "업무에 굉장히 적극적이시네요.\n앞으로도 그냥 여기 남아서 제 조수를 맡아 주시는 건 어때요?",
  ui_story_5045_50451401_8_dialog_content = "그건...",
  ui_story_5045_50451401_9_dialog_content = "심판관님.",
  ui_story_5045_50451401_10_dialog_content = "앗?!",
  ui_story_5045_50451401_11_dialog_content = "베이컨 씨? 파니 씨? 왜 다시 돌아오신 거죠?",
  ui_story_5045_50451401_12_dialog_content = "설마 또 무슨 문제가 있는 건 아니죠?",
  ui_story_5045_50451401_13_dialog_content = "그게 아니라, 두 심판관님께 감사 인사를 드리고 싶어서 찾아왔습니다.",
  ui_story_5045_50451401_14_dialog_content = "재판이 끝나고 나니 전 마치 꿈에서 깬 것만 같았습니다...",
  ui_story_5045_50451401_15_dialog_content = "전 제가 하마터면 얼마나 큰 잘못을 저지를 뻔했는지 깨달았습니다.\n게다가 두 분까지 말려들게 만들고 말았죠.",
  ui_story_5045_50451401_16_dialog_content = "그렇게 마음 쓰지 않으셔도 돼요.\n두 분께 도움이 되었다니 저희로서도 영광인걸요.",
  ui_story_5045_50451401_17_dialog_content = "게다가 전 하나도 안 힘들답니다~",
  ui_story_5045_50451401_18_dialog_content = "(힘든 일은 다 내가 했으니까 그렇지...)",
  ui_story_5045_50451401_19_dialog_content = "PlayerName 씨, 베이컨 씨한테 할 말이 있지 않았나요?",
  ui_story_5045_50451401_20_dialog_content = "아, 그렇지! <color=#1875ad>당부</color>할 말이 있어서요...",
  ui_story_5045_50451401_21_dialog_content = "사건도 다 종료됐는데, 그 얘긴 또 왜 꺼내는 건가요?",
  ui_story_5045_50451401_22_dialog_content = "라파엘이 베이컨 씨를 걱정하고 있어요.",
  ui_story_5045_50451401_23_dialog_content = "라파엘이 생긴 건 아이 같고, 치료 방식도 많이 거칠긴 하지만...",
  ui_story_5045_50451401_24_dialog_content = "그래도 실력은 정말 대단한 의사예요!",
  ui_story_5045_50451401_25_dialog_content = "알겠습니다... 라파엘 선생님도 찾아뵙고 사과드리겠습니다.",
  ui_story_5045_50451401_26_dialog_content = "라파엘 선생님께서 제게 다시 한번 기회를 주신다면,\n이번엔 꼭 착실하게 선생님께 치료를 받겠습니다.",
  ui_story_5045_50451401_27_dialog_content = "그럼 지금부터 두 분은 어떻게 하실 생각인가요?",
  ui_story_5045_50451401_28_dialog_content = "아직은 잘 모르겠습니다.\n일단은 아내와 함께 날품이라도 팔면서 천천히 빚을 갚아볼까 합니다.",
  ui_story_5045_50451401_29_dialog_content = "그리고 「<color=#1875ad>마인드 아카데미</color>」에도 나가 볼 생각입니다.\n어쩌면 새로운 인생의 방향을 찾을 수 있을지도 모르죠.",
  ui_story_5045_50451401_30_dialog_content = "아주 충실한 생활이 될 것 같네요!",
  ui_story_5045_50451401_31_dialog_content = "근데 짐을 잔뜩 챙기셨는데, 혹시 이사 가시는 건가요?",
  ui_story_5045_50451401_32_dialog_content = "아, 이건 전부 도자기를 만들 때 쓰는 도구들입니다.",
  ui_story_5045_50451401_33_dialog_content = "교외에 가서 새 접시를 몇 개 만들려고요.",
  ui_story_5045_50451401_34_dialog_content = "어머, 다시 한번 신혼 때 분위기를 내시려는 건가요?",
  ui_story_5045_50451401_35_dialog_content = "크흠, 무슨 그런 낯간지러운 말씀을...",
  ui_story_5045_50451401_36_dialog_content = "다 제 탓입니다. 저희한테 가장 소중한 기념품을 제가 깨버렸으니까요.",
  ui_story_5045_50451401_37_dialog_content = "잘못을 했으면 보상을 해야겠죠.",
  ui_story_5045_50451401_38_dialog_content = "정말 다정하시네요~",
  ui_story_5045_50451401_39_option_content = "두 사람이 부러운가 보네?",
  ui_story_5045_50451401_40_dialog_content = "음... 아름다운 사랑을 동경하는 건 당연한 일이잖아요~",
  ui_story_5045_50451401_41_dialog_content = "두 분만 괜찮으시다면 가는 김에 접시를 몇 개 더 만들어서 선물로 드릴게요!",
  ui_story_5045_50451401_42_dialog_content = "정말 감사한 말씀이지만, 심판관으로서 사건 당사자에게 선물을 받을 순 없어요.",
  ui_story_5045_50451401_43_dialog_content = "저희가 진흙으로 만든 접시가 무슨 가치가 있겠어요...",
  ui_story_5045_50451401_44_dialog_content = "마음만 감사히 잘 받을게요.\n하지만 전 두 분의 접시가 돈으로 살 수 없는 소중한 보물이라 생각해요.",
  ui_story_5045_50451401_45_dialog_content = "정말 감사해요, 심판관님...\n그, 그럼 바쁘실 테니 저희는 이만 가 볼게요.",
  ui_story_5045_50451401_46_dialog_content = "휴, 언젠간 제 마음속 상대도 저한테 저런 로맨틱한 일을 해 줬으면 좋겠네요.",
  ui_story_5045_50451401_47_dialog_content = "하지만 아직 업무 시간이잖아요?\n그럼 PlayerName 씨, 얼른 일을 시작하죠~",
  ui_story_5045_50451401_47X1_dialog_content = "파트너로서 우리 사이의 <color=#1875ad>팀워크</color>는 아직 더 향상될 여지가 있으니까요!",
  ui_story_5045_50451401_48_dialog_content = "티나 넌?",
  ui_story_5045_50451401_49_dialog_content = "전 당연히... 수면을 보충해야죠.\n기분이 좋을 때 잠에 들면 좋은 꿈을 꿀 수도 있잖아요~",
  ui_story_5045_50451401_50_dialog_content = "뭐어어?!",
  ui_story_5045_50451401_51_option_content = "우리도 같이 가자!",
  ui_story_5045_50451401_52_dialog_content = "어머?",
  ui_story_5045_50451401_53_dialog_content = "아, 미안... 아직 업무 시간이란 걸 깜빡했네.",
  ui_story_5045_50451401_54_dialog_content = "그럼 얼른 출발하죠!",
  ui_story_5045_50451401_55_dialog_content = "알겠어. 지금 바로...",
  ui_story_5045_50451401_56_dialog_content = "뭐?! 출발하자고?",
  ui_story_5045_50451401_57_dialog_content = "<color=#737378>시간: 오후 9시</color>",
  ui_story_5045_50451401_58_dialog_content = "<color=#737378>장소: 백야성 교외</color>",
  ui_story_5045_50451401_59_dialog_content = "모양을 거의 다 내셨다면, 이제 모닥불 속에 넣어 구우면 됩니다.",
  ui_story_5045_50451401_60_dialog_content = "티나, 넌 뭘 만들었어?",
  ui_story_5045_50451401_61_dialog_content = "조금 이따가 보여 드릴게요.",
  ui_story_5045_50451401_62_dialog_content = "괜찮아. 나라고 잘 만든 것도 아니니까, 네 거 보고 안 웃을게.",
  ui_story_5045_50451401_63_dialog_content = "전 제 작품에 충분히 만족하고 있는걸요.\n아까 그건 마무리만 좀 잘못됐을...",
  ui_story_5045_50451401_64_dialog_content = "푸훕... 아하하!",
  ui_story_5045_50451401_65_dialog_content = "왜, 왜 그래?",
  ui_story_5045_50451401_66_dialog_content = "PlayerName 씨, 못난이 접시를 만든 건 그렇다 치고,\n얼굴이 온통 진흙투성이네요.",
  ui_story_5045_50451401_67_dialog_content = "자길 조각상으로 만들려던 건 아니죠?",
  ui_story_5045_50451401_68_dialog_content = "그, 그 정도야? 진흙이 그렇게 많이 묻은 줄은 몰랐는데...",
  ui_story_5045_50451401_69_dialog_content = "근데 얼굴이 엉망인 건 티나 너도 똑같은데?",
  ui_story_5045_50451401_70_dialog_content = "네에?!",
  ui_story_5045_50451401_71_dialog_content = "뭐, 그래도 괜찮아요.\n작품을 위해서라면 얼굴이 얼룩덜룩해지는 정도는 아무렇지도 않아요~",
  ui_story_5045_50451401_72_dialog_content = "지금 손에 들고 있는 그게... 작품이야?",
  ui_story_5045_50451401_73_dialog_content = "맞아요, 헤헷.",
  ui_story_5045_50451401_74_dialog_content = "내가 잘 몰라서 그러는데, 무슨 모양이야?",
  ui_story_5045_50451401_75_dialog_content = "이것도 모르시겠어요? 자세히 좀 보세요...",
  ui_story_5045_50451401_76_dialog_content = "이건 소년이고, 이건 소녀예요.",
  ui_story_5045_50451401_77_dialog_content = "서로를 깊이 사랑하는 두 사람은 애정 어린 눈빛으로 서로를 바라보며,\n이 세상에서 가장 달콤한 입맞춤을...",
  ui_story_5045_50451401_78_dialog_content = "...크흠, 이건 제가 연애 지부를 위해 특별히 만든 작은 장식품이에요.",
  ui_story_5045_50451401_79_dialog_content = "뭔가 했더니 인형이었구나...",
  ui_story_5045_50451401_80_dialog_content = "정말 귀여운 인형들이네요.\n전 왜 지금까지 장식품을 만들 생각을 못 했을까요?",
  ui_story_5045_50451401_81_dialog_content = "근데 인형의 모습이 어딘지 낯이 익군요.",
  ui_story_5045_50451401_82_dialog_content = "후훗, 두 심판관님이랑 닮았지?",
  ui_story_5045_50451401_83_dialog_content = "네?!",
  ui_story_5045_50451401_84_option_content = "별로 안 닮았는데요.",
  ui_story_5045_50451401_85_dialog_content = "안 닮은 게 정상인걸요.",
  ui_story_5045_50451401_86_dialog_content = "이건 제가 그냥 아무렇게나 만든 소년과 소녀거든요.",
  ui_story_5045_50451401_87_dialog_content = "빛의 신께서 백야성의 모든 연인을 굽어살펴 주시길 바라면서 만든 거예요.",
  ui_story_5045_50451401_88_dialog_content = "그러면 우리 연애 지부의 업무량도 지금보다 많이 줄어들 테니까요...",
  ui_story_5045_50451401_89_dialog_content = "그럼 일이 많은 걸 알면서 왜 날 데리고 놀러 나온 건데?",
  ui_story_5045_50451401_90_dialog_content = "그건...",
  ui_story_5045_50451401_91_dialog_content = "응? 그건 뭐?",
  ui_story_5045_50451401_92_option_content = "진짜 좀 닮은 것 같네요.",
  ui_story_5045_50451401_93_dialog_content = "에?",
  ui_story_5045_50451401_94_dialog_content = "닮긴요! 아, 안 닮았거든요!",
  ui_story_5045_50451401_95_dialog_content = "그럼 누굴 본떠 만든 건데?",
  ui_story_5045_50451401_96_dialog_content = "특별히 누구 모습을 본뜬 건 아니에요.",
  ui_story_5045_50451401_97_dialog_content = "이 인형들은 서로 사랑하는 남녀의 모습을 추상적으로 형상화한 거라구요!",
  ui_story_5045_50451401_98_dialog_content = "전 그냥 모든 사람이 아름다운 사랑을 할 수 있길 바랄 뿐이에요.",
  ui_story_5045_50451401_99_dialog_content = "그리고 그 모든 연인들이 오래오래 행복했으면 좋겠어요.",
  ui_story_5045_50451401_100_dialog_content = "티나는 연애 지부 일을 정말 많이 좋아하는구나.",
  ui_story_5045_50451401_101_dialog_content = "사실 어디서 일하든 저한텐 다 똑같아요.",
  ui_story_5045_50451401_102_dialog_content = "하지만 요즘 연애 지부의 일이 전보다 훨씬 재미있어진 건 사실이에요.",
  ui_story_5045_50451401_103_dialog_content = "만약 당신이 제 곁에서 도와주지 않았다면...",
  ui_story_5045_50451401_104_dialog_content = "전 아마 제가 어떤 마음가짐으로 연애 지부의 사건을\n심리해야 할지 지금도 몰랐을 거예요.",
  ui_story_5045_50451401_105_dialog_content = "왜 그렇게 생각하는 거야? 티나는 원래도 충분히 뛰어난 심판관이었잖아.",
  ui_story_5045_50451401_106_dialog_content = "하지만 예전의 전 사랑에 대한 상상력이 너무나도 빈약했거든요.",
  ui_story_5045_50451401_107_dialog_content = "전 줄곧 영문도 모르게 누군가를 좋아하곤 했어요.\n하지만 제가 좋아했던 건 결국 제 상상 속 그 사람의 모습일 뿐이었어요.",
  ui_story_5045_50451401_108_dialog_content = "지금 와서 생각해 보면 그저 애들 장난 같은 감정이었죠.",
  ui_story_5045_50451401_109_dialog_content = "진정한 사랑은...",
  ui_story_5045_50451401_110_dialog_content = "서로 힘들 때, 비록 미력하더라도 서로를 끝까지 도우면서\n평범한 삶 속의 난관에 맞서는 것이고...",
  ui_story_5045_50451401_111_dialog_content = "상대방이 자신을 위해 굴복하길 바라는 게 아니라,\n서로가 자신보다 상대방을 먼저 생각해 주는 거예요.",
  ui_story_5045_50451401_112_dialog_content = "맞아. 우리한테 그런 사실을 깨닫게 해 준\n파니 씨랑 베이컨 씨한테 고맙다고 해야겠는걸.",
  ui_story_5045_50451401_113_dialog_content = "전 PlayerName 씨한테도 고맙다고 하고 싶어요.",
  ui_story_5045_50451401_114_dialog_content = "당신 덕분에 전 확실하게 깨달을 수 있었어요...",
  ui_story_5045_50451401_115_dialog_content = "응? 뭘 깨달았는데?",
  ui_story_5045_50451401_116_dialog_content = "휴우우... 후우... Zzz...",
  ui_story_5045_50451401_117_dialog_content = "뭐야, 잠들었어?",
  ui_story_5045_50451401_118_dialog_content = "...티나는 무슨 말을 하려던 걸까?",
  ui_story_5045_50451401_119_dialog_content = "휴, 아무래도 오늘 그 답을 듣는 건 무리겠네. 잘 자, 티나.",
  ui_story_5045_50451401_120_dialog_content = "......",
  ui_story_5045_50451401_121_dialog_content = "벌써 꿈나라로 떠난 모양이네.",
  ui_story_5045_50451401_122_dialog_content = "PlayerName 씨! 제 작품들을 잘 챙겨 주세요!",
  ui_story_5045_50451401_123_dialog_content = "아, 알겠어!",
  ui_story_5045_50451401_124_dialog_content = "뭐야? 잠꼬대였나?",
  ui_story_5045_50451401_125_dialog_content = "티나도 참, 꿈에서도 쉬질 못하는구나...",
  ui_story_5045_50451501_1_dialog_content = "<color=#737378>시간: 오후 3시</color>",
  ui_story_5045_50451501_2_dialog_content = "<color=#737378>장소: 백야성 심판소, 연애 지부 사무실</color>",
  ui_story_5045_50451501_3_dialog_content = "(사건 심리가 이렇게 빨리 끝날 줄은 몰랐네.)",
  ui_story_5045_50451501_4_dialog_content = "(설마 내 감응 능력보다 심판관으로서의 재능이 더 뛰어난 건 아니겠지?)",
  ui_story_5045_50451501_5_dialog_content = "(우리가 일하는 모습을 이리돈 씨가 봤다면, 보수를 좀 더 올려줄지도 몰라.)",
  ui_story_5045_50451501_6_dialog_content = "(그러면... 헤헤, 바이스랑 카렌한테 깜짝 선물도 사 줄 수 있겠네!)",
  ui_story_5045_50451501_7_dialog_content = "(그나저나...)",
  ui_story_5045_50451501_8_dialog_content = "오늘은 왜 소장을 내러 온 사람들이 왜 전보다 더 많아진 거지?!",
  ui_story_5045_50451501_9_dialog_content = "어머? 벌써 심판소 업무에 흥미를 잃은 건가요?",
  ui_story_5045_50451501_10_dialog_content = "아, 아니에요!",
  ui_story_5045_50451501_11_dialog_content = "어이쿠, 공사가 다망하신 이리돈 님께서 무슨 일로 여기까지 행차하신 겁니까?",
  ui_story_5045_50451501_12_dialog_content = "휴우우... 후우... Zzz...",
  ui_story_5045_50451501_13_dialog_content = "티나, 어서 일어나세요!",
  ui_story_5045_50451501_14_dialog_content = "으으음...",
  ui_story_5045_50451501_15_dialog_content = "안젤, 가만히 뭐 하고 있는 거지?\n어서 가서 존경하는 대심판관님께 차라도 좀 내와.",
  ui_story_5045_50451501_16_dialog_content = "...네.",
  ui_story_5045_50451501_17_dialog_content = "번거롭게 그럴 거 없어요.",
  ui_story_5045_50451501_18_dialog_content = "여러분이 아침에 사건 하나를 심리했다고 들었어요.\n그래서 상황을 좀 보러 온 거예요.",
  ui_story_5045_50451501_19_dialog_content = "아, 그 사건 말씀이십니까? 그저 규정대로 적당히 심리했더군요.",
  ui_story_5045_50451501_20_dialog_content = "오히려 내일 제가 맡을 심리는 모든 이를 깜짝 놀라게 만들고,\n후대의 귀감으로 남을 판례가 될 겁니다.",
  ui_story_5045_50451501_21_dialog_content = "그러니 그때 다시 시찰을 나오시는 것도 좋을 것 같습니다만.",
  ui_story_5045_50451501_22_dialog_content = "그 이야기는 나중에 하기로 해요. 제가 내일 시간이 난다면 말이죠.",
  ui_story_5045_50451501_23_dialog_content = "아침의 그 사건이 지금 세간의 화제가 됐다고 하더군요.\n무슨 일이 있었던 거죠?",
  ui_story_5045_50451501_24_dialog_content = "이리돈 님... 오전 사건은 저와 PlayerName 씨가 심리를 맡았어요.",
  ui_story_5045_50451501_25_dialog_content = "상세한 쟁점과 재판 과정은 모두 여기 기록해 뒀어요. 한번 보실래요?",
  ui_story_5045_50451501_26_dialog_content = "좋군요. PlayerName 씨.\n업무를 시작한 지 얼마 안 됐는데, 벌써 좋은 습관이 생겼네요.",
  ui_story_5045_50451501_27_dialog_content = "방금 오늘 사건이 세간의 화제가 되었다고 하셨습니까?",
  ui_story_5045_50451501_28_dialog_content = "그래요.",
  ui_story_5045_50451501_29_dialog_content = "여론이 어떻습니까?",
  ui_story_5045_50451501_30_dialog_content = "당신은 어떨 거라 생각하죠?",
  ui_story_5045_50451501_31_dialog_content = "음... 좋지 않겠습니까?",
  ui_story_5045_50451501_32_dialog_content = "대심판관님께서 친히 파견해 주신 훌륭한 조수도 있으니 말입니다.",
  ui_story_5045_50451501_33_dialog_content = "PlayerName의 도움이 있었으니, 티나 심판관도 조금은 공부가 됐겠죠.",
  ui_story_5045_50451501_34_dialog_content = "어쩌면 이제 곧 티나 심판관이 이 연애 지부에서\n두 번째로 우수한 심판관이 될지도 모르겠군요!",
  ui_story_5045_50451501_35_dialog_content = "티나 심판관, PlayerName 씨의 기록은 빠짐없이 잘 이루어졌나요?",
  ui_story_5045_50451501_36_dialog_content = "네, PlayerName 씨에게 사건 관련 내용을 모두\n상세히 기록해 달라고 했어요.",
  ui_story_5045_50451501_37_dialog_content = "...수박 겉핥기식 조사에, 사건 당사자들에게 충분한 해명의 기회도 주지 않다니...",
  ui_story_5045_50451501_38_dialog_content = "티나, 설마 재판 도중에 잠들어 버렸던 건 아니겠죠?",
  ui_story_5045_50451501_39_dialog_content = "자, 잠들지 않았어요... 하아아암~",
  ui_story_5045_50451501_40_dialog_content = "오전엔 계속해서 잠이 오는 걸 꾹 참았는걸요.\n그래서 재판이 끝나고 지금까지 쭉 잠을 보충하고 있었어요.",
  ui_story_5045_50451501_41_dialog_content = "연애 지부는 이제 막 세워졌으니까, 참고할 판례도 없었겠죠.",
  ui_story_5045_50451501_42_dialog_content = "여러분 모두 중압감을 느끼고 있으리란 것도 이해해요.",
  ui_story_5045_50451501_43_dialog_content = "하지만 우리에겐 사소해 보이는 사건일지라도,\n당사자들에겐 인생이 걸린 문제일 수 있다는 점을 항상 명심하세요.",
  ui_story_5045_50451501_44_dialog_content = "여러분이 맡은 사건을 어떻게 처리하느냐에 따라,\n향후 백야성의 백성들이 사랑을 대하는 태도도 달라지게 돼요.",
  ui_story_5045_50451501_45_dialog_content = "아무래도 오늘 아침 사건에 대한 여론이 그다지 좋지 않은 모양이군요...",
  ui_story_5045_50451501_46_dialog_content = "자유로운 연애와 결혼을 주장하는 사람들은 그 재판 결과에 불만을 품고 있어요.",
  ui_story_5045_50451501_47_dialog_content = "이제부터 심판소에 보복성 소송을 제기할 가능성도 있겠죠.",
  ui_story_5045_50451501_48_dialog_content = "다들 마음의 준비를 단단히 해 두도록 하세요.",
  ui_story_5045_50451501_49_dialog_content = "보복성 소송이요?",
  ui_story_5045_50451501_50_dialog_content = "심판소를 골탕 먹일 심산으로 일부러 결혼한 다음 이혼 소송을 거는 거지.",
  ui_story_5045_50451501_51_dialog_content = "결국 이게 다 티나 덕분이잖아?\n그럼 앞으로 이런 종류의 소송은 티나에게 맡기면 되겠지.",
  ui_story_5045_50451501_52_dialog_content = "휴우우... 후우... Zzz...",
  ui_story_5045_50451501_53_dialog_content = "음, 아무 말 없는 거 보니 티나도 동의한 모양이군.",
  ui_story_5045_50451501_54_dialog_content = "어? 자, 잠깐만...",
  ui_story_5045_50451501_55_dialog_content = "그럼 결국 나보고 모든 이혼 사건을 다 처리하라는 거잖아?",
  ui_story_5045_50451501_56_dialog_content = "그걸 다 끝내려면 아근을 얼마나 해야 하는 거야?!",
  ui_story_5045_50451601_1_dialog_content = "<color=#737378>시간: 오후 3시</color>",
  ui_story_5045_50451601_2_dialog_content = "<color=#737378>장소: 백야성 심판소, 소심판정</color>",
  ui_story_5045_50451601_3_dialog_content = "<color=#737378>탕!</color>",
  ui_story_5045_50451601_4_dialog_content = "<size=45>지금부터 재판을 시작하겠습니다!</size>",
  ui_story_5045_50451601_5_dialog_content = "먼저, 원고의 의견 진술을 청취하겠습니다.",
  ui_story_5045_50451601_6_dialog_content = "뭐야? 처음 보는 얼굴인데?",
  ui_story_5045_50451601_7_dialog_content = "정말 내 사건을 제대로 재판할 수 있겠어?",
  ui_story_5045_50451601_8_dialog_content = "정숙하세요!",
  ui_story_5045_50451601_9_dialog_content = "사건과 무관한 질문은 삼가 주시기 바랍니다.",
  ui_story_5045_50451601_10_dialog_content = "...무엄하다!",
  ui_story_5045_50451601_11_dialog_content = "내가 누군지 알아? 어디 일개 심판관 주제에 감히 나한테 그런 말을 해?",
  ui_story_5045_50451601_12_dialog_content = "내가 대심판관한테 널 고발 못 할 것 같냐?",
  ui_story_5045_50451601_13_dialog_content = "전 이리돈 대심판관님께서 직접 선발하신 견습 심판관입니다.",
  ui_story_5045_50451601_14_dialog_content = "심판소의 질서 유지에 협조해 주시죠.",
  ui_story_5045_50451601_15_dialog_content = "흥, 어디 잘 봐라!",
  ui_story_5045_50451601_16_dialog_content = "어라? 원고? 어디 가시는 거죠?",
  ui_story_5045_50451601_17_dialog_content = "<color=#737378>시간: 오후 4시</color>",
  ui_story_5045_50451601_18_dialog_content = "<color=#737378>장소: 심판소 로비</color>",
  ui_story_5045_50451601_19_dialog_content = "이리돈 씨, 찾으셨어요?",
  ui_story_5045_50451601_20_dialog_content = "PlayerName 씨, 당신 고발당한 거 알고 있나요?",
  ui_story_5045_50451601_21_dialog_content = "네? 아까 그 사람이 정말 절 고발한 건가요?",
  ui_story_5045_50451601_22_dialog_content = "그렇지만 전 딱히 잘못한 게 없는데요?\n그 사람이 먼저 심판소의 규율을 무시했어요!",
  ui_story_5045_50451601_23_dialog_content = "그 사람에게 문제가 있다는 점은 저도 물론 알고 있어요.",
  ui_story_5045_50451601_24_dialog_content = "하지만 당신은요?",
  ui_story_5045_50451601_25_dialog_content = "제가 당신에게 부탁한 일은 연애 지부의 일을 돕는 거였어요.\n단독으로 개정해 사건을 심리할 권한은 주지 않았죠.",
  ui_story_5045_50451601_26_dialog_content = "벼, 별로 어려워 보이지 않아서 저 혼자서도 할 수 있겠다고 생각했어요...",
  ui_story_5045_50451601_27_dialog_content = "정식 심판관이 되는 게 그렇게 간단한 일이었다면,\n안젤도 이미 오래전에 모의 심판에 통과했을 거예요.",
  ui_story_5045_50451601_28_dialog_content = "당신에게 심판관이 될 자질이 있다는 건 인정해요.",
  ui_story_5045_50451601_29_dialog_content = "그렇지만 자질이 있다고 해서 배움의 단계를 건너뛰고\n바로 심판관이 될 수 있는 건 아니에요.",
  ui_story_5045_50451601_30_dialog_content = "대대로 심판관을 배출한 가문에서 태어난 천재라 해도,\n심판관의 조수 업무부터 시작해야 하는 법이에요.",
  ui_story_5045_50451601_31_dialog_content = "죄송해요...",
  ui_story_5045_50451601_32_dialog_content = "그, 그럼 지금 바로 조수 역할을 하러 돌아갈게요!",
  ui_story_5045_50451601_33_dialog_content = "......",
  ui_story_5045_50451601_34_dialog_content = "그럴 필요 없어요.",
  ui_story_5045_50451601_35_dialog_content = "네?",
  ui_story_5045_50451601_36_dialog_content = "이 문제가 불거져 심판소가 대중의 오해를 사는 일이 없도록...",
  ui_story_5045_50451601_37_dialog_content = "PlayerName 씨에게는 정말 미안하게 됐지만,\n당신은 이제 더는 심판소에서 일할 수 없어요.",
  ui_story_5045_50451601_38_dialog_content = "알겠어요. 그러면 제 보수는 어떻게 되는 건가요...?",
  ui_story_5045_50451601_39_dialog_content = "심판소는 합의를 위해 고발인에게 거액의 배상금을 지급했어요.",
  ui_story_5045_50451601_40_dialog_content = "당신이 받을 보수는 그 보상금의 액수에 훨씬 미치지 못하고요.",
  ui_story_5045_50451601_41_dialog_content = "물론 이번 일엔 제 책임도 있으니까, 당신에게 손해 배상을 청구하진 않을 거예요.",
  ui_story_5045_50451601_42_dialog_content = "비록 당신은 심판소에서 일할 순 없게 됐지만,\n사건 방청을 하고 싶다면 심판소의 문은 언제나 열려 있을 거예요.",
  ui_story_5045_50451601_43_dialog_content = "아...",
  ui_story_5045_50451601_44_dialog_content = "내, 내 보수...",
  ui_story_5045_50451601_45_dialog_content = "이럴 줄 알았으면 그냥 얌전히 조수 일이나 할걸!",
  ui_story_5045_50451601_46_dialog_content = "그리고 이 노트도 더는 당신이 가지고 있을 수 없어요.",
  ui_story_5045_50451601_47_dialog_content = "따라서 제가 회수할게요.",
  ui_story_5045_50451601_48_dialog_content = "이리돈 씨, 자, 잠깐만요! 가지 마세요...",
  ui_story_5045_50451601_49_dialog_content = "이번엔...",
  ui_story_5045_50451601_50_dialog_content = "진짜 확실하게 망해버렸네...",
  ui_story_5045_50451701_1_dialog_content = "<color=#737378>시간: 오전 8시</color>",
  ui_story_5045_50451701_2_dialog_content = "<color=#737378>장소: 백야성 심판소, 연애 지부 사무실</color>",
  ui_story_5045_50451701_3_dialog_content = "결혼은 가문에서 정해 준 대로 해야 하는 거다. 그게 바로 귀족으로서의 책임이다!",
  ui_story_5045_50451701_4_dialog_content = "만약 가문에서 마티외 선배님한테 지저분하고, 잘 씻지도 않는 사람과\n결혼하라고 하면요? 그래도 가문의 뜻을 따르실 건가요?",
  ui_story_5045_50451701_5_dialog_content = "나는 내 가문이 절대로 내게 그런 아내를 찾아 주지 않을 거라 믿는다.",
  ui_story_5045_50451701_6_dialog_content = "그거야 모르는 일이죠.",
  ui_story_5045_50451701_7_dialog_content = "그러니까 결국 당사자의 감정은 중요하지 않고,\n물질적 이익만 극대화하겠다는 생각이잖아요!",
  ui_story_5045_50451701_8_dialog_content = "이 사건의 담당 심판관은 나다! 그러니 모두 내 판결을 존중해야 해!",
  ui_story_5045_50451701_9_dialog_content = "선배님이 판결을 잘못 내리면 저한테도 불똥이 튀니까 그러죠...",
  ui_story_5045_50451701_10_dialog_content = "마티외 씨랑 안젤은 왜 저러는 거야?",
  ui_story_5045_50451701_11_dialog_content = "지금 심리 중인 사건에 대해 서로 의견이 맞지 않는 모양입니다.",
  ui_story_5045_50451701_12_dialog_content = "아직도 싸우고 있단 말이에요? 잠 좀 제대로 자고 싶은데. 하아아암~",
  ui_story_5045_50451701_13_dialog_content = "누가 안 말렸다간 밤까지 싸우게 생겼는데...",
  ui_story_5045_50451701_14_dialog_content = "가서 어떻게 된 건지 좀 들어볼까? 우리가 도움을 줄 수 있을지도 모르잖아.",
  ui_story_5045_50451701_15_dialog_content = "PlayerName 씨가 그렇게 말씀하신다면야...",
  ui_story_5045_50451701_16_dialog_content = "우리도 가만히 보고만 있을 순 없겠죠.",
  ui_story_5045_50451701_17_dialog_content = "저기... 마티외 씨, 안젤, 대체 무슨 사건이길래 그래?",
  ui_story_5045_50451701_18_dialog_content = "다들 마침 잘 왔군. 너희도 내 판결이 합리적인지 아닌지 잘 들어봐라.",
  ui_story_5045_50451701_19_dialog_content = "한 대귀족의 외동딸이 연애의 자유를 침해당했다며 자기 친부모를 고소했다.",
  ui_story_5045_50451701_20_dialog_content = "난 시작부터 이 사건이 까다로울 것 같다고 생각했지.\n그래서 안젤을 데리고 가서 증거를 수집했다.",
  ui_story_5045_50451701_21_dialog_content = "그러다 이 아가씨가 사랑하게 된 사람이 제대로 된 직업도 없는\n가난뱅이라는 사실을 발견했던 거다.",
  ui_story_5045_50451701_22_dialog_content = "그게 아니죠! 그 귀족 아가씨의 부모가 그 사람을 실직자로 만든 거라니까요!\n그전까지만 해도 그 사람은 솜씨 좋은 요리사였어요!",
  ui_story_5045_50451701_23_dialog_content = "이건 조사를 통해 사실로 밝혀진 부분이잖아요! 아닌가요?",
  ui_story_5045_50451701_24_dialog_content = "하지만 그 남자는 어쨌든 평민이다.\n평민이 귀족의 딸에게 좋은 의도로 접근했을 리가 없다!",
  ui_story_5045_50451701_25_dialog_content = "전 그 의견에 동의 못 해요!",
  ui_story_5045_50451701_26_dialog_content = "귀족 아가씨는 그 남자를 위해 모든 재산을 포기할 마음이었어요...",
  ui_story_5045_50451701_27_dialog_content = "그리고 그 남자는 귀족 아가씨의 미래를 위해 먼저 이별을 고했고요.",
  ui_story_5045_50451701_28_dialog_content = "이 얼마나 순수한 사랑인가요?",
  ui_story_5045_50451701_29_dialog_content = "너도 말했듯이 그 가난뱅이는 결국 현실의 벽을 느끼고 마음을 접은 거다.",
  ui_story_5045_50451701_30_dialog_content = "그래서 난 귀족 아가씨의 부모에게 잘못이 없다는 판결을 내렸다.\n이 판결에 무슨 문제라도 있나?",
  ui_story_5045_50451701_31_dialog_content = "확실히 엄청 복잡한 사건 같네...",
  ui_story_5045_50451701_32_dialog_content = "어? 바닥에 이건 뭐지?",
  ui_story_5045_50451701_33_dialog_content = "어디서 본 적 있는 것 같은데?",
  ui_story_5045_50451701_34_dialog_content = "음, 이게 아니지... 분명히...",
  ui_story_5045_50451701_35_dialog_content = "조사가 끝나고 나서 소피 씨한테 돌려줬던 걸로 기억하는데...",
  ui_story_5045_50451701_36_dialog_content = "뭐야, 그러고 보니까 이거... 베이컨 씨가 갖고 있던 <color=#1875ad>수강증</color>이랑 똑같잖아?!",
  ui_story_5045_50451701_37_dialog_content = "조사가 끝나고 나서 베이컨 씨한테 돌려줬던 걸로 기억하는데...",
  ui_story_5045_50451701_38_dialog_content = "뭐야, 그러고 보니까 이거... 소피 씨가 갖고 있던 <color=#1875ad>수강증</color>이랑 똑같잖아?!",
  ui_story_5045_50451701_39_dialog_content = "이상한데...",
  ui_story_5045_50451701_40_dialog_content = "아, 그건 내가 수집한 증거야! 떨어진 줄도 모르고 있었네...",
  ui_story_5045_50451701_41_dialog_content = "고마워, PlayerName. 다른 사람이 주웠으면 난처해질 뻔했어.",
  ui_story_5045_50451701_42_dialog_content = "안젤, 넌 일단 네 일부터 잘할 필요가 있어.\n나와 재판에 대해 논의하는 건 그다음이다.",
  ui_story_5045_50451701_43_dialog_content = "......",
  ui_story_5045_50451701_44_dialog_content = "안젤, 그 수강증은 누구 거야?",
  ui_story_5045_50451701_45_dialog_content = "어? PlayerName 너 정말 대단하네. 이 카드가 뭔지 한눈에 알아본 거야?",
  ui_story_5045_50451701_46_dialog_content = "이건 나랑 마티외 선배님이 <color=#1875ad>카를</color> 씨 집에서 발견한 거야.\n이 아카데미에서 법학 공부를 하고 있다고 하더라고...",
  ui_story_5045_50451701_47_dialog_content = "그 사람은 열심히 노력해서 자기 현실을 바꾸고 심판관이 되겠다는 것 같았어.",
  ui_story_5045_50451701_48_dialog_content = "역시 뭔가 이상해...",
  ui_story_5045_50451701_49_dialog_content = "카드? 무슨 수강증 같은데?",
  ui_story_5045_50451701_50_dialog_content = "아, 맞아요.\n전 교육 프로그램에 참가해서 가사 업무와 관리를 배우는 중이거든요.",
  ui_story_5045_50451701_51_dialog_content = "음? 탁자 위의 이 카드는 뭐죠?",
  ui_story_5045_50451701_52_dialog_content = "...그건 「<color=#1875ad>마인드 아카데미</color>」의 수강증이에요.",
  ui_story_5045_50451701_53_dialog_content = "마음을 단련시켜 두려움 없이 삶의 어려움을 마주하도록 돕는 교육이에요.",
  ui_story_5045_50451701_54_dialog_content = "많은 사람들이 거기서 교육을 듣고 백야성의 신흥 부자가 됐다고 들었어요.",
  ui_story_5045_50451701_55_dialog_content = "왜 이 아카데미에 대한 설명이 전부 다른 거지?",
  ui_story_5045_50451701_56_dialog_content = "설마...",
  ui_story_5045_50451701_57_dialog_content = "<size=45>!!!</size>",
  ui_story_5045_50451701_58_dialog_content = "저기, 두 사람이 맡은 사건에서 귀족 아가씨가 사랑에 빠진 사람 이름이 혹시...",
  ui_story_5045_50451701_59_dialog_content = "카를이다.\n쳇, 왜 내가 평민의 이름 따위를 말해야 하는 건지.",
  ui_story_5045_50451701_60_dialog_content = "나 왠지 어디선가 그 <color=#1875ad>카를</color>이란 사람을 만난 적 있는 것 같은데?",
  ui_story_5045_50451701_61_dialog_content = "아니지! 분명히...",
  ui_story_5045_50451701_62_dialog_content = "소피 씨의 이웃 이름이 카를이었어!",
  ui_story_5045_50451701_63_dialog_content = "그리고 베이컨 씨 부부의 친구도 카를이란 이름이었고...",
  ui_story_5045_50451701_64_dialog_content = "베이컨 씨 부부의 친구 이름이 카를이었어!",
  ui_story_5045_50451701_65_dialog_content = "그리고 소피 씨의 이웃도 카를이란 이름이었고...",
  ui_story_5045_50451701_66_dialog_content = "우연이라기엔 너무 공교롭잖아?",
  ui_story_5045_50451701_67_dialog_content = "PlayerName 씨, 아까부터 계속 혼자서 뭐라고 중얼거리고 계신 거죠?",
  ui_story_5045_50451701_68_dialog_content = "마티외 씨의 사건에 저희가 딱히 도움이 될 것 같진 않습니다.",
  ui_story_5045_50451701_69_dialog_content = "차라리 저희 수중에 있는 사건부터 처리하는 게 좋겠습니다.",
  ui_story_5045_50451701_70_dialog_content = "PlayerName 씨, 이번엔 저랑 레인 씨 중에서 누굴 도와주시겠어요?",
  ui_story_5045_50451701_71_dialog_content = "며칠 전처럼 번갈아 가며 도와주시는 게 좋지 않겠습니까?",
  ui_story_5045_50451701_72_dialog_content = "그렇게 하면 공평하니까요.",
  ui_story_5045_50451701_73_dialog_content = "미안한데 나 지금 따로 조사하고 싶은 일이 하나 있어...",
  ui_story_5045_50451701_74_dialog_content = "어라? 사건은 놔두고 뭘 조사하려는 건데요?",
  ui_story_5045_50451701_75_dialog_content = "저 「마인드 아카데미」라는 곳에 가볼까 해...\n별일 아닐 거야. 그냥 내가 괜한 생각을 한 거면 좋겠는데...",
  ui_story_5045_50451701_76_dialog_content = "<color=#737378>시간: 오전 9시</color>",
  ui_story_5045_50451701_77_dialog_content = "<color=#737378>장소: 백야성, 다운타운 구역</color>",
  ui_story_5045_50451701_78_dialog_content = "카를 씨!",
  ui_story_5045_50451701_79_dialog_content = "음? 누구셨죠...?",
  ui_story_5045_50451701_80_dialog_content = "저 기억 안 나세요? 백야성 견습 심판관 PlayerName입니다.",
  ui_story_5045_50451701_81_dialog_content = "전에 두 번 만난 적 있는데요.",
  ui_story_5045_50451701_82_dialog_content = "아, 심판소에서 나오신 분이었군요!\n제게 무슨 볼일이라도 있으십니까?",
  ui_story_5045_50451701_83_dialog_content = "네, 혹시 「마인드 아카데미」가 어디 있는지 아시나요?",
  ui_story_5045_50451701_84_dialog_content = "그걸 왜 제게 물으시는 거죠?",
  ui_story_5045_50451701_85_dialog_content = "파니 씨가 카를 씨한테 마인드 아카데미를 소개받았다고 했었거든요.\n그래서 카를 씨라면 잘 알고 계실 것 같아서요.",
  ui_story_5045_50451701_86_dialog_content = "그랬군요. 하지만 저도 다른 사람들 얘기를 들은 게 전부라서요.",
  ui_story_5045_50451701_87_dialog_content = "제 생각에 거긴 아마 뜬구름 잡는 인생 강의나 하는 곳일 겁니다.",
  ui_story_5045_50451701_88_dialog_content = "하지만 삶에서 절망을 느끼고 있는 사람들에겐\n그런 게 지푸라기라도 되는 법 아니겠습니까.",
  ui_story_5045_50451701_89_dialog_content = "...그렇군요. 혹시 다른 정보는 더 없나요?",
  ui_story_5045_50451701_90_dialog_content = "죄송합니다. 제가 알고 있는 건 이게 전부입니다.",
  ui_story_5045_50451701_91_dialog_content = "알겠습니다. 실례했습니다.",
  ui_story_5045_50451701_92_dialog_content = "그럼 전 먼저 가 보겠습니다. 하시는 일이 순조롭길 바라겠습니다.",
  ui_story_5045_50451701_93_dialog_content = "(저 카를이란 사람, 분명히 뭔가 있어.)",
  ui_story_5045_50451701_94_dialog_content = "(어딜 가는지 쫓아가 보자. 뭔가 단서를 찾을 수 있을지도 몰라.)",
  ui_story_5045_50451701_95_dialog_content = "(근데...)",
  ui_story_5045_50451701_96_dialog_content = "대체 어디 간 거야?! 순식간에 사라져 버렸잖아!",
  ui_story_5045_50451701_97_dialog_content = "<color=#737378>시간: ??\n장소: ??</color>",
  ui_story_5045_50451701_98_dialog_content = "뭘 멍하니 있는 겁니까? 어서 목표 대상을 찾으러 가란 말입니다.",
  ui_story_5045_50451701_99_dialog_content = "하, 하지만 전...",
  ui_story_5045_50451701_100_dialog_content = "그런 일은 하고 싶지 않습니다!",
  ui_story_5045_50451701_101_dialog_content = "죄송합니다... 마인드 마스터님! 정말 죄송합니다!",
  ui_story_5045_50451701_102_dialog_content = "좋습니다. 저도 강요하는 건 아니니까요.",
  ui_story_5045_50451701_103_dialog_content = "그럼... 저 이제 그만 돌아가도 될까요?",
  ui_story_5045_50451701_104_dialog_content = "잠깐 기다리세요. 그렇게 서두를 거 없습니다.",
  ui_story_5045_50451701_105_dialog_content = "비록 당신이 여기 온 지는 반나절밖에 안 됐지만, 그래도 제 학생이잖아요?\n그러니 절 위해 다른 일을 하나 해 줬으면 좋겠군요.",
  ui_story_5045_50451701_106_dialog_content = "그렇지 않으면 당신 아내가 무척 힘들어할 겁니다.",
  ui_story_5045_50451801_1_dialog_content = "<color=#737378>시간: 오후 4시</color>",
  ui_story_5045_50451801_2_dialog_content = "<color=#737378>장소: 백야성 심판소, 연애 지부 사무실</color>",
  ui_story_5045_50451801_3_dialog_content = "PlayerName 씨, 돌아오셨군요.",
  ui_story_5045_50451801_4_dialog_content = "조사한다던 일은 뭔가 찾았나요?",
  ui_story_5045_50451801_5_dialog_content = "아니, 단서가 끊겼어. 역시 좀 걱정돼.",
  ui_story_5045_50451801_6_dialog_content = "참, 마티외 씨랑 안젤은?",
  ui_story_5045_50451801_7_dialog_content = "마티외 씨는 그 사건을 잠시 접어 두기로 한 모양입니다.",
  ui_story_5045_50451801_8_dialog_content = "안젤 씨는 마티외 씨를 따라 다른 사건을 조사하러 갔어요.\n그러니까 일단 두 사람 생각은 나중에 하고...",
  ui_story_5045_50451801_9_dialog_content = "오늘은 누구의 조수가 되어 줄 거죠?",
  ui_story_5045_50451801_10_dialog_content = "난...",
  ui_story_5045_50451801_11_dialog_content = "혹시 여기 PlayerName 님 계신가요?",
  ui_story_5045_50451801_12_dialog_content = "에이미구나? 나한테 무슨 볼일 있어?",
  ui_story_5045_50451801_13_dialog_content = "저...전 당신을 <color=#1875ad>체포</color>하러 왔어요!",
  ui_story_5045_50451801_14_dialog_content = "날 체포한다고?! 왜?",
  ui_story_5045_50451801_15_dialog_content = "누군가 당신이 백야성에서 사기 범죄 조직을 결성했다고\n최고심판소에 고발했어요!",
  ui_story_5045_50451801_16_dialog_content = "사기로 인한 피해가 광범위하고, 죄질이 무척 악랄해서...",
  ui_story_5045_50451801_17_dialog_content = "심판소에선 당신을 체포해서 내일 당장 재판을 진행하기로 했어요!",
  ui_story_5045_50451801_18_dialog_content = "뭔가 착오가 있는 게 아닙니까?",
  ui_story_5045_50451801_19_dialog_content = "PlayerName 씨는 며칠 동안 계속 우리 업무를 돕고 있었어요.",
  ui_story_5045_50451801_20_dialog_content = "틀림없어요. 피고발인은 심판소에서 일하고 있는 아이테르라고 했거든요.",
  ui_story_5045_50451801_21_dialog_content = "당신 말고 아이테르가 또 있는 건 아닐 거잖아요.",
  ui_story_5045_50451801_22_dialog_content = "......",
  ui_story_5045_50451801_23_dialog_content = "<color=#737378>시간: 다음 날, 오전 9시</color>",
  ui_story_5045_50451801_24_dialog_content = "<color=#737378>장소: 백야성 심판소, 대심판정</color>",
  ui_story_5045_50451801_25_dialog_content = "(심판소의 방청석엔 서로 귓속말을 주고받는 사람들이 가득 앉아 있었다.)",
  ui_story_5045_50451801_26_dialog_content = "(혐오가 가득한 눈빛들이 날 꿰뚫어 버릴 것만 같았다.)",
  ui_story_5045_50451801_27_dialog_content = "(며칠 전까지만 해도 나는 심판석에 서 있는 견습 심판관이었지만, 오늘은...)",
  ui_story_5045_50451801_28_dialog_content = "(레인 씨랑 티나... 둘 다 안 온 건가?)",
  ui_story_5045_50451801_29_dialog_content = "<color=#737378>탕!</color>",
  ui_story_5045_50451801_30_dialog_content = "<size=45>만물은 백야 아래에, 지금부터 재판을 시작하겠습니다!</size>",
  ui_story_5045_50451801_31_dialog_content = "만물은 백야 아래에.",
  ui_story_5045_50451801_32_option_content = "만물은 백야 아래에...",
  ui_story_5045_50451801_33_dialog_content = "어떻게 뻔뻔히 저 말을 입에 담을 수 있는 거지?",
  ui_story_5045_50451801_34_option_content = "이건 누명이에요!",
  ui_story_5045_50451801_35_dialog_content = "<color=#737378>탕!</color>",
  ui_story_5045_50451801_36_dialog_content = "피고발인, 심판소의 질서를 지켜주세요.",
  ui_story_5045_50451801_37_dialog_content = "주의하세요. 본 심판소에서 경고를 3회 받게 될 경우,\n피고발인은 자신을 변호할 기회를 잃게 될 겁니다.",
  ui_story_5045_50451801_38_dialog_content = "(맞아, 쟁점도 질문하기 전에 변론을 하면 안 되지.\n분명히 알고 있었는데, 방금 전엔 왜 깜빡한 거지?!)",
  ui_story_5045_50451801_39_option_content = "이의 있습니다!",
  ui_story_5045_50451801_40_dialog_content = "피고발인은 최근 심판소에서 적지 않은 시간을 일해 왔습니다.",
  ui_story_5045_50451801_41_dialog_content = "그럼에도 본 대심판관이 피고발인에게 심판소의 절차와 규정을 교육해야 하나요?",
  ui_story_5045_50451801_42_dialog_content = "(맞아, 쟁점도 질문하기 전에 변론을 하면 안 되지.\n분명히 알고 있었는데, 고발을 당하니까 당황해서 잊어버렸잖아...)",
  ui_story_5045_50451801_43_dialog_content = "자, 그럼 먼저 고발인 <color=#1875ad>베이컨</color> 씨의 의견 진술을 청취하겠습니다.",
  ui_story_5045_50451801_44_dialog_content = "대심판관님, 저, 전 베이컨이라고 합니다.",
  ui_story_5045_50451801_45_dialog_content = "(베이컨 씨잖아?! 설마 나랑 티나의 판결에 불만이 있었던 건가?)",
  ui_story_5045_50451801_46_dialog_content = "(하지만 재판이 끝나고 다 같이 교외에도 갔었고, 그땐 다 괜찮아 보였는데...)",
  ui_story_5045_50451801_47_dialog_content = "전 오늘... 수천 명에 달하는 백야성의 피해자들을 대표해\nPlayerName의 범죄를 고발하려 합니다.",
  ui_story_5045_50451801_48_dialog_content = "그 내용은...",
  ui_story_5045_50451801_49_dialog_content = "피고발인은 「<color=#1875ad>마인드 아카데미</color>」라는 직업 능력 훈련 기관을 설립했습니다.",
  ui_story_5045_50451801_50_dialog_content = "하지만 그 실체는 원생들을 모아서...",
  ui_story_5045_50451801_51_dialog_content = "타인의 감정을 이용해 부자들의 재산을 편취하는 방법을 가르치는 곳이었습니다!",
  ui_story_5045_50451801_52_dialog_content = "<size=45>뭐라고요?!</size>",
  ui_story_5045_50451801_53_dialog_content = "도저히 믿을 수가 없군. 백야성에 저런 파렴치한 인간이 있었다니!",
  ui_story_5045_50451801_54_dialog_content = "한탕을 노리고 백야성에 숨어 들어온 인간쓰레기겠지!",
  ui_story_5045_50451801_55_dialog_content = "피고발인, 고발인의 고발 내용을 인정하십니까?",
  ui_story_5045_50451801_56_dialog_content = "전 그런 짓을 한 적도 없고,\n그 「마인드 아카데미」란 곳이 어디에 있는지도 모릅니다!",
  ui_story_5045_50451801_57_dialog_content = "베이컨 씨, 누가 절 고발하라고 사주한 게 아닌가요?",
  ui_story_5045_50451801_58_dialog_content = "그, 그건...",
  ui_story_5045_50451801_59_dialog_content = "아닙니다!",
  ui_story_5045_50451801_60_dialog_content = "<color=#737378>탕!</color>",
  ui_story_5045_50451801_61_dialog_content = "피고발인, 심판소에서 고발인을 오도하는 발언은 삼가시길 바랍니다.",
  ui_story_5045_50451801_62_dialog_content = "(하지만 지금 베이컨 씨는 분명히 뭔가를 걱정하고 있어.)",
  ui_story_5045_50451801_63_dialog_content = "(난 어제 카를 씨를 만났고, 그리고 오늘 체포됐어... 이건 절대 우연이 아니야!)",
  ui_story_5045_50451801_64_dialog_content = "고발인, 주장을 증명해 줄 증인이 두 명 있다고 하셨지요?",
  ui_story_5045_50451801_65_dialog_content = "네, 대심판관님.",
  ui_story_5045_50451801_66_dialog_content = "<color=#1875ad>증인</color>은 증인석으로 나와 주십시오.",
  ui_story_5045_50451801_67_dialog_content = "만물은 백야 아래에.",
  ui_story_5045_50451801_68_dialog_content = "(소피 씨잖아?!)",
  ui_story_5045_50451801_69_dialog_content = "(역시... 내 생각이 맞았어.)",
  ui_story_5045_50451801_70_option_content = "이의 있습니다!",
  ui_story_5045_50451801_71_dialog_content = "<color=#737378>탕!</color>",
  ui_story_5045_50451801_72_dialog_content = "지금은 증인신문 절차를 진행하는 중입니다.\n피고발인, 심판소의 질서를 지켜주세요.",
  ui_story_5045_50451801_73_dialog_content = "말씀드렸을 텐데요. 본 심판소에서 경고를 3회 받게 될 경우,\n피고발인은 자신을 변호할 기회를 잃게 됩니다.",
  ui_story_5045_50451801_74_dialog_content = "(으... 너무 긴장해서 그런지 역시 제대로 생각을 못 하겠어.)",
  ui_story_5045_50451801_75_dialog_content = "(이제 더는 경고를 받으면 안 돼!)",
  ui_story_5045_50451801_76_option_content = "(침묵한다)",
  ui_story_5045_50451801_77_dialog_content = "(소피 씨가 뭐라고 하는지 일단 들어 봐야겠어.)",
  ui_story_5045_50451801_78_dialog_content = "대심판관님, 전 소피라고 합니다.\n전 고발인의 진술이 모두 사실임을 증언합니다.",
  ui_story_5045_50451801_79_dialog_content = "전 「마인드 아카데미」의 초기 원생 중 하나입니다.",
  ui_story_5045_50451801_80_dialog_content = "피고발인은 자신이 아이테르이며, 사람의 마음을 조종할 줄 안다고 했습니다.",
  ui_story_5045_50451801_81_dialog_content = "그래서 절 비롯한 원생들은 피고발인을 마인드 마스터라고 불렀습니다.",
  ui_story_5045_50451801_82_dialog_content = "그러나 마인드 마스터는 저희에게 공갈, 협박 등을 가해서,\n저희가 다른 사람을 속여 돈을 편취하게 했어요.",
  ui_story_5045_50451801_83_dialog_content = "그리고 저희가 편취해 온 돈은 전부 마인드 마스터에게 상납했습니다.",
  ui_story_5045_50451801_84_dialog_content = "지금 증인 본인도 사기 범죄에 가담했다는 사실을 인정하는 겁니까?",
  ui_story_5045_50451801_85_dialog_content = "네.",
  ui_story_5045_50451801_86_dialog_content = "그렇다면 증인 역시 그에 따른 심판을 받게 된다는 점을 이해하고 있습니까?",
  ui_story_5045_50451801_87_dialog_content = "네. 전 계속 양심의 가책을 느껴 왔어요.\n이제 더는 사람들이 상처받는 모습을 보고 싶지 않아요.",
  ui_story_5045_50451801_88_dialog_content = "남은 삶을 계속 이렇게 휘둘리느니, 한 번쯤은 맞서 싸우고 싶었어요.",
  ui_story_5045_50451801_89_dialog_content = "(누가 들어도 진심처럼 들리겠어...\n날 모함하는 것만 아니었으면 나까지 믿었겠는데?!)",
  ui_story_5045_50451801_90_dialog_content = "피고발인, 증인의 진술에 대해 반박할 의견이 있습니까?",
  ui_story_5045_50451801_91_dialog_content = "(어떤 증거를 제시해야 <color=#1875ad>소피 씨의 말이 거짓</color>이라는 걸 증명할 수 있을까...?)",
  ui_story_5045_50451801_92_dialog_content = "지금 그 이야기를 꺼내는 이유가 뭐죠?",
  ui_story_5045_50451801_93_dialog_content = "(이런! 이게 아닌가?)",
  ui_story_5045_50451801_94_dialog_content = "대심판관님! 아직 기억하십니까?\n이건 대심판관님이 직접 제게 주셨던 심판관의 노트입니다!",
  ui_story_5045_50451801_95_dialog_content = "음? 비록 당신이 심판관의 노트를 가지고 있더라도,\n당신은 현재 피고발인으로서 이 심판소에 서 있는 겁니다.",
  ui_story_5045_50451801_96_dialog_content = "그 노트를 보여 준다고 해서 당신에게 도움이 될 일은 전혀 없습니다.",
  ui_story_5045_50451801_97_dialog_content = "전 이 심판관의 노트를 걸고 맹세할 수 있습니다!\n전 정말로 그 마인드 마스터인지 뭔지가 아니에요!",
  ui_story_5045_50451801_98_dialog_content = "미안합니다, PlayerName 씨.",
  ui_story_5045_50451801_99_dialog_content = "그런 맹세가 정말 효과가 있었다면, 애초에 심판소가 필요할 일도 없었을 겁니다.",
  ui_story_5045_50451801_100_dialog_content = "(역시 이거 가지곤 안 되는 건가?)",
  ui_story_5045_50451801_101_dialog_content = "대심판관님, 증인은 이전 재판에서 증거를 조작했던 전력이 있습니다!",
  ui_story_5045_50451801_102_dialog_content = "그렇습니까? 증인, 피고발인의 발언이 사실입니까?",
  ui_story_5045_50451801_103_dialog_content = "그, 그땐 저도 어쩔 수 없었어요.",
  ui_story_5045_50451801_104_dialog_content = "그때 전 해당 사건의 고발인이 「마인드 아카데미」의 정체를\n알게 될까 두려웠습니다...",
  ui_story_5045_50451801_105_dialog_content = "그렇게 되면 제가 마인드 마스터에게 처벌을 받게 될 테니까요.",
  ui_story_5045_50451801_106_dialog_content = "하지만 마인드 마스터는 이미 붙잡혔으니, 이제 더는 두렵지 않아요!",
  ui_story_5045_50451801_107_dialog_content = "음, 정상 참작이 가능한 상황이군요.",
  ui_story_5045_50451801_108_dialog_content = "그렇다면 두 번째 증인, 증인석으로 나와 주십시오.",
  ui_story_5045_50451801_109_dialog_content = "대심판관님, 전 카를이라고 합니다.",
  ui_story_5045_50451801_110_dialog_content = "전 어제 고발인과 식사를 하기로 했습니다.\n그러나 고발인은 한참 동안 약속 장소에 오지 않았습니다.",
  ui_story_5045_50451801_111_dialog_content = "다행히 고발인이 제게 미리 행선지를 말해주었고,\n전 한참 동안 찾은 끝에 그 장소를 찾아낼 수 있었습니다.",
  ui_story_5045_50451801_112_dialog_content = "그곳은 바로 소문이 무성하던 「마인드 아카데미」였습니다.",
  ui_story_5045_50451801_113_dialog_content = "하지만 그때 고발인은 마인드 마스터가 맡긴 임무를 수행하고 싶지 않다고 했고\n한사코 절 따라가겠다고 했습니다.",
  ui_story_5045_50451801_114_dialog_content = "전 상황이 심상치 않다는 것을 느꼈고, 급한 마음에 그곳에 불을 질렀습니다.\n그렇게 해서 겨우 고발인을 데리고 거기서 탈출할 수 있었습니다.",
  ui_story_5045_50451801_115_dialog_content = "소문의 그 마인드 마스터는 불길 속에서 빠져나오려고 망토를 벗었고,\n바로 그때 전 그 사람의 진짜 모습을 보았습니다.",
  ui_story_5045_50451801_116_dialog_content = "그렇다면 증인은 마인드 마스터의 생김새를 알고 있다는 겁니까?",
  ui_story_5045_50451801_117_dialog_content = "그렇습니다.",
  ui_story_5045_50451801_118_dialog_content = "지금 이 심판소에 증인이 목격한 그 마인드 마스터가 있습니까?",
  ui_story_5045_50451801_119_dialog_content = "네. 마인드 마스터는 바로 지금 피고발인석에 서 있는 저 사람입니다.",
  ui_story_5045_50451801_120_dialog_content = "(어째서 이런... 카를 저 사람, 대체 무슨 생각이지?)",
  ui_story_5045_50451801_121_dialog_content = "(...그래! 역시 그 방법을 쓸 수밖에 없겠어!)",
  ui_story_5045_50451801_122_option_content = "(감응!)",
  ui_story_5045_50451801_123_dialog_content = "(역시 아이테르의 이름을 걸고 「마인드 아카데미」를\n세운 건 현명한 선택이었어.)",
  ui_story_5045_50451801_124_dialog_content = "(다들 마인드 마스터는 아이테르라고 알고 있고, 내 진짜 정체는 아무도 몰라.)",
  ui_story_5045_50451801_125_dialog_content = "(하지만 「마인드 아카데미」도 여기까지라는 건 좀 아깝게 됐잖아.\n그래도 돈은 이미 충분히 챙겼으니 다행이라고 할 수 있겠지.)",
  ui_story_5045_50451801_126_dialog_content = "(큭... 진짜 마인드 마스터는 역시 이 사람이었어!)",
  ui_story_5045_50451801_127_dialog_content = "(PlayerName 씨, 아마 당신은 지금 내 마음의 소리를 듣고 있겠죠.)",
  ui_story_5045_50451801_128_dialog_content = "(뭐야?! 이 사람, 어떻게 안 거지?)",
  ui_story_5045_50451801_129_dialog_content = "(당신은 아마 태어날 때부터 다른 사람의 마음속 생각을 들을 수 있었겠죠.)",
  ui_story_5045_50451801_130_dialog_content = "(하지만 전 당신의 동작만 보고도 당신이 무슨 생각을 하는지 알 수 있습니다.)",
  ui_story_5045_50451801_131_dialog_content = "(그렇다면 우리 둘 중에서 누가 더 대단한 걸까요?)",
  ui_story_5045_50451801_132_dialog_content = "대심판관님!",
  ui_story_5045_50451801_133_dialog_content = "마인드 마스터는 카를입니다! 감응을 통해 알아낸 사실입니다!",
  ui_story_5045_50451801_134_dialog_content = "역시 저 사람은 남의 마음을 조종할 수 있었어!",
  ui_story_5045_50451801_135_dialog_content = "저런 사람이 하는 말을 어떻게 믿어?!",
  ui_story_5045_50451801_136_dialog_content = "(역시 이 방법도 안 되겠네...)",
  ui_story_5045_50451801_137_dialog_content = "(하지만 <color=#1875ad>카를</color>의 발언엔 반드시 허점이 있을 거야.)",
  ui_story_5045_50451801_138_dialog_content = "무슨 말씀을 하고 싶으신 거죠?",
  ui_story_5045_50451801_139_dialog_content = "아, 전 그러니까...",
  ui_story_5045_50451801_140_dialog_content = "어제 증인은 제게 분명히 자신은 「마인드 아카데미」에 가본 적도 없고,\n어디에 있는지도 모른다고 말했습니다!",
  ui_story_5045_50451801_141_dialog_content = "하지만 방금 증인은 고발인이 자신에게 「마인드 아카데미」의\n주소를 가르쳐 주었다고 증언했습니다!",
  ui_story_5045_50451801_142_dialog_content = "그건 제가 당신을 만난 뒤에 고발인과 식사 약속을 잡았기 때문입니다.",
  ui_story_5045_50451801_143_dialog_content = "아하, 그런가요?\n고발인, 증인과 식사 약속을 잡은 게 몇 시였죠?",
  ui_story_5045_50451801_144_dialog_content = "저흰 오전 10시에 약속을 잡았습니다만...",
  ui_story_5045_50451801_145_dialog_content = "전 지금 고발인에게 질문했습니다.\n두 사람은 몇 시에 식사 약속을 잡았죠?",
  ui_story_5045_50451801_146_dialog_content = "저흰 어제 아침 10시에 만났고, 오후 6시에 같이 저녁을 먹자고 약속했습니다...",
  ui_story_5045_50451801_147_dialog_content = "그건 이상하군요. 왜냐하면 전 어제 오후 4시에 이미 체포된 상태였거든요.",
  ui_story_5045_50451801_148_dialog_content = "그런 제가 어떻게 마인드 아카데미에 나타날 수 있었을까요?",
  ui_story_5045_50451801_149_dialog_content = "고발인이 어제 많이 놀라서 시간을 제대로 기억하지 못한 겁니다!",
  ui_story_5045_50451801_150_dialog_content = "저흰 12시에 점심 식사를 하기로 약속했었습니다.\n고발인, 그렇지 않습니까?",
  ui_story_5045_50451801_151_dialog_content = "마, 맞아요... 제가 어제 너무 놀라서 기억을 잘못했네요...",
  ui_story_5045_50451801_152_dialog_content = "피해자가 큰 충격을 받으면 기억이 혼란스러워지는 일이 확실히 종종 있습니다.",
  ui_story_5045_50451801_153_dialog_content = "그것보다...",
  ui_story_5045_50451801_154_dialog_content = "피고발인, 심판기사가 당신의 임시 주소지를 수색한 결과,\n아직 제작하지 않은 다수의 수강증을 발견했습니다.",
  ui_story_5045_50451801_155_dialog_content = "이에 대해 어떻게 해명하시겠습니까?",
  ui_story_5045_50451801_156_option_content = "전 정말 억울합니다!",
  ui_story_5045_50451801_157_dialog_content = "모든 증거가 마인드 마스터의 정체는 피고발인이라고 말해주고 있습니다.\n제대로 해명하는 게 좋을 겁니다.",
  ui_story_5045_50451801_158_dialog_content = "하지만 제가 지내던 곳에 왜 그 수강증이 있었던 건지 전 정말 모르겠습니다.",
  ui_story_5045_50451801_159_dialog_content = "설마 저한테 몽유병이라도 있는 걸까요?",
  ui_story_5045_50451801_160_option_content = "이의 있습니다!",
  ui_story_5045_50451801_161_dialog_content = "어떻게 멋대로 제 거주지를 수색할 수가 있죠?",
  ui_story_5045_50451801_162_dialog_content = "피고발인은 본건의 제1 용의자입니다.\n따라서 피고발인의 거주지를 수색하는 것은 합법적이며 합리적인 행위입니다.",
  ui_story_5045_50451801_163_dialog_content = "윽...",
  ui_story_5045_50451801_164_option_content = "티나 심판관과 레인 심판관은 지금 어디 있죠?",
  ui_story_5045_50451801_165_dialog_content = "그 두 사람을 증인으로 신청합니다!",
  ui_story_5045_50451801_166_dialog_content = "그 두 사람은 지금 각자의 사건을 조사하느라 바쁩니다.\n저도 두 사람이 지금 어디에 있는지 모릅니다.",
  ui_story_5045_50451801_167_dialog_content = "어떻게 그런...",
  ui_story_5045_50451801_168_dialog_content = "하고 싶은 말은 그게 다입니까?",
  ui_story_5045_50451801_169_dialog_content = "저, 전...",
  ui_story_5045_50451801_170_dialog_content = "<color=#737378>탕!</color>",
  ui_story_5045_50451801_171_dialog_content = "만물은 백야 아래에, 지금부터...",
  ui_story_5045_50451801_172_dialog_content = "잠시만 기다려 주십시오!",
  ui_story_5045_50451801_173_dialog_content = "어?",
  ui_story_5045_50451801_174_dialog_content = "대심판관님, 아직 출석하지 않은 증인이 있습니다!",
  ui_story_5045_50451801_175_dialog_content = "미안해요, PlayerName 씨. 우리가 늦진 않았죠?",
  ui_story_5045_50451801_176_dialog_content = "레인 씨, 티나...",
  ui_story_5045_50451801_177_dialog_content = "재판은 아직 끝나지 않았습니다.\n출석한 증인은 증인석으로 나와 주십시오.",
  ui_story_5045_50451801_178_dialog_content = "대심판관님, 전 파니라고 합니다...",
  ui_story_5045_50451801_179_dialog_content = "여, 여보...? 괜찮아?!",
  ui_story_5045_50451801_180_dialog_content = "......?!",
  ui_story_5045_50451801_181_dialog_content = "난 괜찮아, 걱정 안 해도 돼.\n그러니까 이제 대심판관님께 진실을 알려드리자.",
  ui_story_5045_50451801_182_dialog_content = "두려워하지 마세요. 심판소는 모든 증인의 안전을 보장할 것입니다.",
  ui_story_5045_50451801_183_dialog_content = "전 어제 갑자기 한 무리의 사람들에게 <color=#1875ad>납치</color>를 당했습니다.",
  ui_story_5045_50451801_184_dialog_content = "그 사람들은 절 인질로 잡고는, 아무 죄도 없는 사람을 고발하라고\n제 남편을 협박했습니다.",
  ui_story_5045_50451801_185_dialog_content = "네! 그렇습니다!\n제가 아까 한 모든 진술은 전부 마인드 마스터가 지시한 겁니다!",
  ui_story_5045_50451801_186_dialog_content = "제 아내는 마인드 마스터의 부하들 손에 붙잡혀 있었고,\n전 아내를 지키기 위해 다른 선택의 여지가 없었습니다...",
  ui_story_5045_50451801_187_dialog_content = "다행히 레인 심판관님과 티나 심판관님께서 절 찾아서 구해 주셨어요.",
  ui_story_5045_50451801_188_dialog_content = "덕분에 심판소에 출석해 증언할 수 있게 되었습니다.",
  ui_story_5045_50451801_189_dialog_content = "두 사람은 지금 피고발인이 무고하다고 확신하는 겁니까?",
  ui_story_5045_50451801_190_dialog_content = "네, 대심판관님.",
  ui_story_5045_50451801_191_dialog_content = "진짜 마인드 마스터는 언제나 가면을 쓰고 있었습니다.\n하지만 전 그 사람의 목소리를 기억하고 있습니다...",
  ui_story_5045_50451801_192_dialog_content = "카를, 우린 널 친구라고 여겼는데, 왜 이런 짓을 한 거야?",
  ui_story_5045_50451801_193_dialog_content = "......",
  ui_story_5045_50451801_194_dialog_content = "대심판관님, 이건 다 오해입니다! 오해예요!",
  ui_story_5045_50451801_195_dialog_content = "대심판관님, 저흰 카를의 자택에서 비밀 지하실 입구를 발견했습니다.",
  ui_story_5045_50451801_196_dialog_content = "그 안을 조사한다면, 분명히 더 많은 증거를 찾아낼 수 있을 겁니다.",
  ui_story_5045_50451801_197_dialog_content = "맞아요. 이미 기사단에 지원을 요청해 그 주변을 포위해 뒀어요.",
  ui_story_5045_50451801_198_dialog_content = "대심판관님의 지시만 기다리고 있답니다.",
  ui_story_5045_50451801_199_dialog_content = "......",
  ui_story_5045_50451801_200_dialog_content = "카를이 도망친다! 다들 조심해!",
  ui_story_5045_50451801_201_dialog_content = "거기 서라!",
  ui_story_5045_50451801_202_dialog_content = "어딜 도망가려고!",
  ui_story_5045_50451801_203_dialog_content = "으...으윽...",
  ui_story_5045_50451901_1_dialog_content = "<color=#737378>시간: 정오 12시</color>",
  ui_story_5045_50451901_2_dialog_content = "<color=#737378>장소: 백야성 심판소, 연애 지부 사무실</color>",
  ui_story_5045_50451901_3_dialog_content = "대심판관님, 오늘 재판은 정말 수고가 많으셨습니다!",
  ui_story_5045_50451901_4_dialog_content = "대심판관님께선 PlayerName하고 말씀하시는 중이니까, 괜히 끼어들지 마세요.",
  ui_story_5045_50451901_5_dialog_content = "...틀린 말은 아니니까 넘어가 주지.",
  ui_story_5045_50451901_6_dialog_content = "PlayerName 씨, 오늘은 억울한 일을 겪게 만들었네요.",
  ui_story_5045_50451901_7_dialog_content = "이리돈 씨... 설마 처음부터 제가 누명을 쓴 걸 알고 있던 건 아니죠?",
  ui_story_5045_50451901_8_dialog_content = "전 그렇다고 말한 적은 없는걸요.",
  ui_story_5045_50451901_9_dialog_content = "만약 PlayerName 이 녀석이 사기를 쳐서 정말로 그 많은 돈을 벌었다면...",
  ui_story_5045_50451901_10_dialog_content = "보수 몇 푼 받자고 심판소 일을 도와주러 오진 않았을 것 같습니다만.",
  ui_story_5045_50451901_11_dialog_content = "...그 말을 듣고 좋아해야 할지 슬퍼해야 할지 모르겠네.",
  ui_story_5045_50451901_12_dialog_content = "티나 심판관, 레인 심판관, 두 사람의 활약엔 저도 감탄했어요.",
  ui_story_5045_50451901_13_dialog_content = "파니 씨가 납치당했다는 사실은 어떻게 알았죠?",
  ui_story_5045_50451901_14_dialog_content = "전 저희 사건의 당사자였던 퍼렐 씨를 찾아갔습니다.\n처음엔 대답할 마음이 없어 보였지만, 티나 덕분에...",
  ui_story_5045_50451901_15_dialog_content = "당신이 사랑하는 사람의 잘못을 밝히고 싶지 않은 건 알아요.\n하지만 당신이 소피 씨를 구할 방법은 이것뿐이에요!",
  ui_story_5045_50451901_16_dialog_content = "이대로 뒀다간 소피 씨는 영원히 마인드 마스터에게 조종당하면서,\n남은 평생을 더 고통스럽게 보내게 될 거라구요!",
  ui_story_5045_50451901_17_dialog_content = "소피를 구할 방법은... 오직 이것뿐이란 말입니까?",
  ui_story_5045_50451901_18_dialog_content = "퍼렐 씨는 소피 씨가 이상한 일을 하고 있다는 사실을\n진작부터 알고 있었다고 했어요.",
  ui_story_5045_50451901_19_dialog_content = "소피 씨와 그렇게 결혼하고 싶어 했던 것도,\n다 소피 씨를 그 마인드 마스터에게서 벗어나게 해 주고 싶어서였고요.",
  ui_story_5045_50451901_20_dialog_content = "그래서 퍼렐 씨는 저희에게 소피 씨가 자주 가던 곳들을 알려 줬어요.",
  ui_story_5045_50451901_21_dialog_content = "이렇게 넓은 곳을 대체 어디서부터 찾아야 좋을까요...",
  ui_story_5045_50451901_21X1_dialog_content = "어라? 레인 씨?",
  ui_story_5045_50451901_22_dialog_content = "실례합니다, 전 심판소의 심판관입니다.\n혹시 근처에서 수상한 사람들을 못 보셨습니까?",
  ui_story_5045_50451901_23_dialog_content = "꺄앗! 제가 봤어요! 잘생긴 심판관님! 제가 알려드릴게요!",
  ui_story_5045_50451901_24_dialog_content = "그리고 거기서 우린 파니 씨뿐만 아니라 한 소녀도 발견했어요.",
  ui_story_5045_50451901_25_dialog_content = "그 소녀는 소피 씨의 여동생이었었죠...",
  ui_story_5045_50451901_26_dialog_content = "인질을 잡고 다른 사람을 자기 뜻대로 휘두르다니,\n카를은 상습범이 분명합니다!",
  ui_story_5045_50451901_27_dialog_content = "하지만 소피 씨에겐 마인드 마스터의 손에서 스스로 벗어날 기회가 있었습니다.\n이제는 심판소의 처벌을 피할 수 없을 겁니다.",
  ui_story_5045_50451901_28_dialog_content = "두 사람 모두 연애 지부에서 많이 성장했군요.",
  ui_story_5045_50451901_29_dialog_content = "가, 감사합니다! 대심판관님!",
  ui_story_5045_50451901_30_dialog_content = "사실 이것도 PlayerName 씨가 귀띔해 준 덕분이에요.",
  ui_story_5045_50451901_31_dialog_content = "어? 내가?",
  ui_story_5045_50451901_32_dialog_content = "체포당하기 전, PlayerName 씨는 이 사건의 단서가 앞서 저희가 다뤘던\n두 사건에 있을지도 모른다고 알려 줬었습니다.",
  ui_story_5045_50451901_33_dialog_content = "그건 그냥 혼잣말이었는데... 사실 그떈 나도 긴가민가했거든...",
  ui_story_5045_50451901_34_dialog_content = "어쨌든 이번엔 저희가 한 건 제대로 해결했네요!",
  ui_story_5045_50451901_35_dialog_content = "이리돈 님, 혹시 저희한테 주시는 포상은 없나요?",
  ui_story_5045_50451901_36_dialog_content = "티나...",
  ui_story_5045_50451901_37_dialog_content = "그걸 자기 입으로 말하는 사람이 어디 있습니까?",
  ui_story_5045_50451901_38_dialog_content = "사실은 진작에 준비해 뒀어요.",
  ui_story_5045_50451901_39_dialog_content = "잠깐만요... 저와 안젤 몫도 있습니까?",
  ui_story_5045_50451901_40_dialog_content = "PlayerName 씨, 심판소에 일손이 가장 부족한 이 시기에\n기꺼이 찾아와 도와줘서 정말 고마워요.",
  ui_story_5045_50451901_41_dialog_content = "당신 덕분에 연애 지부의 심판관들이 두 사건의 심리를\n성공적으로 마칠 수 있었어요.",
  ui_story_5045_50451901_42_dialog_content = "게다가 본인이 직접 사건에 뛰어들어...",
  ui_story_5045_50451901_43_dialog_content = "백야성의 민심을 어지럽히던 마인드 마스터를 체포하는 데 도움을 줬죠.",
  ui_story_5045_50451901_44_dialog_content = "심판소의 일원들은 당신에게 <color=#1875ad>명예 심판관</color> 트로피를 수여하는 데 동의했어요.",
  ui_story_5045_50451901_45_dialog_content = "와! 조각상 모양으로 생긴 트로피네요! 정말 특이해요!",
  ui_story_5045_50451901_46_dialog_content = "PlayerName 씨, 그건 상당히 무거운 트로피입니다.",
  ui_story_5045_50451901_47_dialog_content = "어? 내가 못 들 정도로 무거운 거야?",
  ui_story_5045_50451901_48_dialog_content = "제 말은 트로피가 상징하는 명예가 무겁다는 의미였습니다.",
  ui_story_5045_50451901_49_dialog_content = "헤헷, PlayerName 씨가 못 들겠으면 제가 「신의 손」으로 도와줄게요~",
  ui_story_5045_50451901_50_dialog_content = "근데 지금 이 트로피를 준다는 건...",
  ui_story_5045_50451901_51_dialog_content = "왜 그러죠? 혹시 마음에 안 드나요?",
  ui_story_5045_50451901_52_dialog_content = "호, 혹시 이제 더는 제 도움이 필요 없게 된 건가... 하는 생각이 들어서요.",
  ui_story_5045_50451901_53_dialog_content = "음, 그렇다고 할 수도 있겠네요.",
  ui_story_5045_50451901_54_dialog_content = "최근 백야성에서 발생했던 사건 중 다수가 마인드 마스터와 연관이 있었어요.",
  ui_story_5045_50451901_55_dialog_content = "마인드 마스터가 체포됐으니 연애 지부의 담당 사건도 차차 줄어들겠죠.",
  ui_story_5045_50451901_56_dialog_content = "그리고 여명 아카데미에서도 많은 아이들이 견습을 오고 싶어 하니까,\n한동안 일손이 부족할 일은 없을 거예요.",
  ui_story_5045_50451901_57_dialog_content = "물론, 당신이 계속 남아 있고 싶다면...",
  ui_story_5045_50451901_58_dialog_content = "견습을 오는 아이들과 함께 연수에 참여한 다음, 심사에 통과하면 돼요.",
  ui_story_5045_50451901_59_dialog_content = "그 과정은 반년이 될 수도, 일 년이 될 수도 있어요.",
  ui_story_5045_50451901_60_dialog_content = "하지만 전 돌아가서 헤븐즈 가든도 가꿔야 하고,\n친구들이 자주 같이 모험을 하러 가자고 하니까...",
  ui_story_5045_50451901_61_dialog_content = "그럼 제 심판소 체험도 이쯤에서 마무리 짓는 게 맞을 것 같네요.",
  ui_story_5045_50451901_62_dialog_content = "내가 말했을 텐데. 심판소는 아무나 남을 수 있는 곳이 아니라고.",
  ui_story_5045_50451901_63_dialog_content = "그렇군요. PlayerName 씨, 이제 떠나시는 겁니까?",
  ui_story_5045_50451901_64_dialog_content = "PlayerName 씨...",
  ui_story_5045_50451901_65_dialog_content = "(왠지 이럴 땐 뭔가 한마디 해야 할 것 같긴 한데...)",
  ui_story_5045_50451901_66_dialog_content = "(무슨 말을 할까?)",
  ui_story_5045_50451901_67_dialog_content = "(아! 그래!)",
  ui_story_5045_50451901_68_dialog_content = "자, 그 물건들을 다시 볼 필요는 없을 것 같네요.",
  ui_story_5045_50451901_69_dialog_content = "(그런가? 근데 자꾸 뭔가 잊어버린 것 같은 느낌인데...)",
  ui_story_5045_50451901_70_dialog_content = "이 <color=#1875ad>연</color>, 아직 내가 가지고 있었어.",
  ui_story_5045_50451901_71_dialog_content = "PlayerName 씨는 저희가 이 연을 어떻게 처리해야 한다고 생각하십니까?",
  ui_story_5045_50451901_72_dialog_content = "소피 씨가 출소하길 기다리고 있을 기사 퍼렐 씨한테 돌려주자.",
  ui_story_5045_50451901_73_dialog_content = "소피 씨가 출소하고 나면, 그 두 사람이 다시 한번 이 연을\n날릴 기회가 있을지도 모르잖아.",
  ui_story_5045_50451901_74_dialog_content = "알겠습니다. 그렇게 하겠습니다.",
  ui_story_5045_50451901_75_dialog_content = "다시 백야성으로 돌아오실 땐 우리도 함께 연을 날릴 기회가 또 있겠죠...",
  ui_story_5045_50451901_76_dialog_content = "당연하지! 꼭 다시는 못 볼 것처럼 말하지 마!",
  ui_story_5045_50451901_77_dialog_content = "알겠습니다! 그럼 그때는 우리도 직접 연을 만들어 보도록 하죠!",
  ui_story_5045_50451901_78_dialog_content = "응! 약속이야!",
  ui_story_5045_50451901_79_dialog_content = "티나가 만들었던 <color=#1875ad>진흙 인형</color>, 아직 내가 가지고 있었어.",
  ui_story_5045_50451901_80_dialog_content = "PlayerName 씨, 그 진흙 인형은 선물로 줄게요!",
  ui_story_5045_50451901_81_dialog_content = "뭐?",
  ui_story_5045_50451901_82_dialog_content = "대신 오해하진 마세요.\n전 그냥 며칠 동안 덕분에 편하고 재미있게 일했던 게 고마워서 주는 거니까요.",
  ui_story_5045_50451901_83_dialog_content = "우린 연애 지부에서 일을 하고 있으니까...",
  ui_story_5045_50451901_84_dialog_content = "앞으로 당신이 좋아하는 사람을 만나고, 그 사람도 당신을 사랑하면서,\n둘이 영원히 행복하고 달콤한 시간을 보낼 수 있길 기원할게요!",
  ui_story_5045_50451901_85_dialog_content = "그 진흙 인형처럼...",
  ui_story_5045_50451901_86_dialog_content = "진흙 속에서 형태를 갖춘 사랑이, 뜨거운 불길을 거쳐 굳세고 단단해져서,\n마지막엔 영원히 스러지지 않는 애정이 되길 말이에요!",
  ui_story_5045_50451901_87_dialog_content = "고마워, 티나!",
  ui_story_5045_50451901_88_dialog_content = "지금의 나한테는 너무 이른 축복이 아닌가 싶지만...",
  ui_story_5045_50451901_89_dialog_content = "전혀 이르지 않아요!",
  ui_story_5045_50451901_90_dialog_content = "그러니까... 만약에 좋아하는 사람을 못 찾으시면,\n그땐 백야성으로, 심판소로 돌아와 보세요.",
  ui_story_5045_50451901_91_dialog_content = "당연하지, 꼭 다시 돌아올게.",
  ui_story_5045_50451901_92_dialog_content = "정말이죠?",
  ui_story_5045_50451901_93_dialog_content = "그럼 또 같이 교외에 가서 진흙 인형을 잔뜩 만들고,\n사랑하는 연인들한테 나눠 주기로 해요!",
  ui_story_5045_50451901_94_dialog_content = "응! 약속이야!",
  ui_story_5045_50451901_95_dialog_content = "연애 지부가 아니었으면 난 이 트로피를 못 받았을 거야.",
  ui_story_5045_50451901_96_dialog_content = "그러니까 이 트로피는 연애 지부에 놔두고 싶어.",
  ui_story_5045_50451901_97_dialog_content = "그거 정말 좋은 생각이네요!",
  ui_story_5045_50451901_98_dialog_content = "근데 PlayerName 씨, 트로피를 어디 두고 싶으신가요?",
  ui_story_5045_50451901_99_dialog_content = "고민할 게 뭐 있냐. 내 책상 위에 두도록 해!",
  ui_story_5045_50451901_100_dialog_content = "여길 둘러봐라. 내 책상 위가 제일 깨끗하잖아. 안 그래?",
  ui_story_5045_50451901_101_dialog_content = "내 생각엔...",
  ui_story_5045_50451901_102_dialog_content = "모두의 책상에 돌아가면서 두는 건 어떨까? 헤헤헤.",
  ui_story_5045_50451901_103_dialog_content = "좋습니다! 그러면 공평하겠군요!",
  ui_story_5045_50451901_104_dialog_content = "그럼 그렇게 해요!",
  ui_story_5045_50451901_105_dialog_content = "모두?",
  ui_story_5045_50451901_106_dialog_content = "그 모두에 나도 포함인 거 맞겠지? 어이...",
  ui_story_5045_50451901_107_dialog_content = "이 노트 안엔...",
